insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('legumbres_011', 'Judiones de la Granja', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 90, 'normal', 'invierno', 524, 28, 44, 26, 2, true, true, '{}', '[{"name":"Judiones","amount":250,"unit":"g"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Morcilla","amount":60,"unit":"g"},{"name":"Oreja de cerdo","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Poner judiones en un bol grande con agua fría y dejar en remojo un mínimo de 12 h.","Escurrir los judiones y reservar.","Pelar cebolla y cortar en trozos grandes.","Pelar ajo y dejar los dientes enteros.","Cortar oreja de cerdo en trozos de bocado.","Cortar chorizo en rodajas de 1 cm.","Cortar morcilla en rodajas de 1 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el ajo hasta que estén blandos, unos 5 min.","Añadir pimentón y remover 30 segundos hasta que se integre.","Incorporar los judiones escurridos y la oreja de cerdo; cubrir con agua fría (unos 2 cm por encima).","Llevar a ebullición a fuego fuerte; retirar la espuma que suba a la superficie con una cuchara.","Bajar a fuego suave, tapar la olla y cocer hasta que los judiones estén tiernos, unos 60 min.","Añadir el chorizo y la morcilla y cocer a fuego suave, destapado, 20 min más.","Retirar del fuego y dejar reposar 10 min antes de servir.","Servir los judiones bien calientes en plato hondo, repartiendo los trozos de oreja, chorizo y morcilla."}', 'Judiones blancos grandes guisados con chorizo, morcilla y oreja', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Tras un sofrito inicial en cazuela, incorpora los judiones remojados y las carnes con caldo. Cocina en el horno precalentado a 160°C durante 90-120 minutos, cubierto, para una cocción lenta y uniforme."},{"appliance":"thermomix","time":85,"difficulty":"normal","prepSummary":"Realiza el sofrito de cebolla y ajo, añade las carnes y los judiones remojados con el caldo. Cocina a 95°C, velocidad cuchara inversa, durante 75-90 minutos hasta que los judiones estén tiernos y el guiso ligado."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Prepara un sofrito rápido con cebolla y ajo, añade las carnes y los judiones (previamente remojados) con el caldo. Cierra la olla y cocina a presión durante 25-35 minutos para una cocción rápida y judiones perfectamente tiernos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_012', 'Ensalada de lentejas', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'verano', 312, 16, 34, 12, 2, true, true, '{"sulfitos"}', '[{"name":"Lentejas cocidas","amount":300,"unit":"g"},{"name":"Tomate","amount":120,"unit":"g"},{"name":"Cebolla morada","amount":50,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Escurrir lentejas cocidas con un colador y aclarar bajo agua fría hasta que estén a temperatura ambiente.","Cortar tomate en dados pequeños de aproximadamente 1 cm.","Cortar cebolla morada en dados pequeños.","Cortar pimiento verde en dados pequeños.","Cortar pepino en dados pequeños.","Mezclar en un bol las lentejas escurridas con el tomate, la cebolla morada, el pimiento verde y el pepino.","Añadir aceite de oliva y vinagre sobre la mezcla y remover hasta que todo quede bien integrado.","Tapar el bol y dejar reposar en la nevera hasta que esté bien fría, mínimo 10 min.","Servir la ensalada fría directamente del bol."}', 'Ensalada fría de lentejas con verduras de temporada', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_013', 'Garbanzos con calabaza', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'invierno', 356, 14, 48, 11, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Calabaza","amount":200,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino","amount":3,"unit":"g"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Pelar cebolla y picar en trozos pequeños. Pelar ajo y picar fino.","Pelar calabaza y cortar en dados de unos 2 cm.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada en el aceite caliente a fuego medio hasta que esté transparente, unos 4 min.","Añadir el ajo picado y sofreír 1 min hasta que empiece a dorarse.","Incorporar los dados de calabaza y saltear a fuego medio durante 5 min hasta que empiecen a ablandarse.","Añadir tomate triturado, comino y pimentón. Remover bien para integrar las especias.","Sofreír el conjunto a fuego medio durante 3 min hasta que el tomate pierda el agua y se concentre.","Añadir garbanzos cocidos y 150 ml de agua. Remover para mezclar todo.","Llevar a ebullición, tapar y cocer a fuego suave durante 15 min hasta que la calabaza esté tierna y el caldo se reduzca.","Retirar del fuego y servir en plato hondo con el caldo de cocción."}', 'Garbanzos guisados con calabaza y comino', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo. Mezcla con el resto de ingredientes en una fuente apta para horno y hornea a 180°C durante 30-35 minutos hasta que la calabaza esté tierna y los sabores se integren."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea y sofríe la cebolla y el ajo. Añade la calabaza, garbanzos, tomate y especias, y cocina a temperatura Varoma/100°C, velocidad cuchara, durante 20-25 minutos hasta que la calabaza esté cocida."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Prepara un sofrito con cebolla y ajo en la olla abierta. Incorpora el resto de ingredientes, cierra la olla y cocina a presión durante 5-7 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_014', 'Judías pintas con arroz', 'legumbres', 'legumbre', 'arroz', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 55, 'facil', 'all', 402, 18, 56, 10, 2, true, true, '{}', '[{"name":"Judías pintas","amount":200,"unit":"g"},{"name":"Arroz","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":18,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar zanahoria y cortar en rodajas de 1 cm. Reservar.","Pelar cebolla y picar en trozos pequeños. Reservar.","Limpiar pimiento verde, retirar las semillas y cortar en trozos pequeños. Reservar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada en el aceite caliente hasta que esté transparente, unos 4 min.","Añadir el pimiento verde y la zanahoria a la olla y sofreír 3 min hasta que empiecen a ablandarse.","Añadir pimentón y remover 30 segundos a fuego suave para que no se queme.","Incorporar judías pintas y laurel a la olla. Cubrir con agua fría hasta unos 4 cm por encima.","Llevar a ebullición a fuego fuerte y luego bajar a fuego suave. Tapar y cocer 35 min hasta que las judías estén tiernas.","Añadir arroz a la olla con las judías y remover para integrar. Cocer a fuego medio 15 min hasta que el arroz esté en su punto.","Retirar el laurel. Tapar la olla y dejar reposar 5 min fuera del fuego.","Servir el guiso bien caliente en cuencos hondos."}', 'Judías pintas guisadas con arroz y verduras', '[{"appliance":"horno","time":60,"difficulty":"facil","prepSummary":"Sofríe las verduras en una cazuela apta para horno, añade las judías (previamente cocidas), el arroz, el pimentón, laurel y caldo o agua. Cubre y hornea a 180°C durante 45-50 minutos hasta que el arroz esté tierno."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas en el vaso con aceite. Incorpora las judías (previamente cocidas), el arroz, pimentón, laurel y agua/caldo. Cocina a 100°C, giro inverso, velocidad cuchara durante 30-35 minutos."},{"appliance":"olla_express","time":30,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla express. Añade las judías (previamente cocidas), el arroz, pimentón, laurel y agua/caldo. Cierra la olla y cocina a presión durante 15-20 minutos desde que suba la válvula."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_015', 'Ensalada templada de garbanzos', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 332, 14, 34, 15, 2, true, true, '{"sulfitos"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Pimiento rojo asado","amount":120,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar tomate en dados pequeños y reservar.","Laminar cebolla morada en tiras finas y reservar.","Cortar pimiento rojo asado en tiras y reservar.","Picar perejil fino y reservar.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Añadir garbanzos cocidos y comino a la sartén y saltear 3 min hasta que estén ligeramente dorados.","Retirar la sartén del fuego y añadir el tomate en dados, la cebolla morada laminada y el pimiento asado en tiras.","Añadir vinagre de jerez y el aceite de oliva restante, y remover para mezclar bien.","Añadir el perejil picado, remover y servir de inmediato mientras la ensalada está templada."}', 'Ensalada templada de garbanzos con pimiento asado, comino y vinagre de Jerez', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_016', 'Potaje de habichuelas', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 55, 'facil', 'invierno', 378, 20, 46, 10, 2, true, true, '{}', '[{"name":"Alubias blancas","amount":250,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":18,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Escurrir alubias blancas del remojo y reservar.","Pelar patata y cortarla en trozos medianos.","Pelar zanahoria y cortarla en rodajas.","Picar cebolla en dados finos.","Picar ajo fino.","Introducir las alubias escurridas en una olla grande, cubrir con agua fría y añadir laurel y la zanahoria en rodajas.","Llevar a ebullición a fuego fuerte y cocer a fuego medio durante 45 min, hasta que las alubias estén tiernas.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada en la sartén a fuego suave hasta que esté transparente, unos 5 min.","Añadir el ajo picado y sofreír 1 min a fuego suave hasta que desprenda aroma.","Incorporar tomate triturado al sofrito y cocer a fuego medio durante 5 min hasta que reduzca y se concentre.","Añadir la patata en trozos a la olla con las alubias y cocer a fuego medio 15 min hasta que esté tierna.","Incorporar el sofrito a la olla y remover para ligar el caldo durante 5 min a fuego suave.","Retirar la hoja de laurel y servir el potaje bien caliente."}', 'Potaje sencillo de alubias blancas con patata y verduras', '[{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Prepara un sofrito inicial con cebolla, ajo, zanahoria y tomate en una olla apta para horno. Añade las alubias, patata, laurel y caldo/agua. Cocina tapado en el horno a 180°C durante unos 50-60 minutos, o hasta que las alubias estén tiernas, removiendo ocasionalmente y ajustando el líquido si es necesario."},{"appliance":"thermomix","time":65,"difficulty":"facil","prepSummary":"Trocea las verduras en el vaso, sofríe con aceite. Añade las alubias (previamente remojadas o cocidas), patata, laurel y caldo/agua. Programa 45-50 minutos, 100°C, giro inverso, velocidad cuchara, hasta que el potaje esté en su punto."},{"appliance":"olla_express","time":45,"difficulty":"facil","prepSummary":"Realiza un sofrito con la cebolla, ajo, zanahoria y tomate en la olla a presión. Incorpora las alubias (remojadas), patata, laurel y suficiente agua/caldo. Cierra la olla y cocina a fuego medio-alto durante 20-25 minutos desde que sube la válvula, dejando despresurizar de forma natural."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_017', 'Lentejas con pollo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'facil', 'all', 422, 32, 38, 14, 2, true, true, '{}', '[{"name":"Lentejas","amount":180,"unit":"g"},{"name":"Contramuslo de pollo","amount":200,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Patata","amount":120,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Cortar contramuslo de pollo en trozos de bocado de tamaño uniforme.","Pelar y picar cebolla en brunoise fina.","Pelar zanahoria y cortar en rodajas de unos 5 mm.","Pelar patata y cortar en dados de unos 2 cm.","Calentar aceite de oliva en una olla a fuego fuerte hasta que esté bien caliente.","Dorar los trozos de contramuslo de pollo en la olla hasta que estén dorados por todos los lados; retirar y reservar.","Sofreír la cebolla picada en la misma olla a fuego medio hasta que esté transparente.","Añadir la zanahoria y sofreír junto a la cebolla durante 2 min, removiendo.","Añadir tomate triturado y pimentón y remover hasta integrar; sofreír 2 min a fuego medio.","Incorporar lentejas, la patata en dados y los trozos de contramuslo de pollo reservados.","Cubrir con agua fría hasta superar los ingredientes unos 4 cm y llevar a ebullición a fuego fuerte.","Bajar a fuego suave, tapar y cocer hasta que las lentejas y la patata estén tiernas.","Comprobar el punto de sal y servir las lentejas con el pollo en platos hondos bien calientes."}', 'Lentejas guisadas con trozos de pollo y verduras', '[{"appliance":"horno","time":65,"difficulty":"facil","prepSummary":"Prepara un sofrito con las verduras y el pollo en una olla apta para horno. Añade las lentejas, tomate, pimentón y caldo. Hornea tapado a 180°C durante unos 60-70 minutos, removiendo ocasionalmente, hasta que las lentejas estén tiernas."},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas en el vaso. Incorpora el pollo, lentejas, tomate, pimentón y agua/caldo. Cocina a 100°C, giro inverso, velocidad cuchara, durante unos 50-55 minutos o hasta que las lentejas estén tiernas."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Sofríe las verduras y el pollo en la olla. Incorpora las lentejas, tomate, pimentón y agua/caldo. Cierra la olla y cocina a presión durante 15-20 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_018', 'Garbanzos con tomate', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 342, 14, 40, 14, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino","amount":3,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla y ajo en trozos finos.","Cortar pimiento verde en trozos pequeños.","Calentar aceite de oliva en una sartén grande a fuego medio.","Sofreír la cebolla, el ajo y el pimiento verde en sartén hasta que estén tiernos y la cebolla esté transparente.","Añadir tomate triturado y comino al sofrito y remover para integrar.","Cocer la salsa a fuego medio hasta que reduzca y se concentre el sabor.","Incorporar garbanzos cocidos a la salsa y remover para que se impregnen bien.","Guisar a fuego suave hasta que los garbanzos absorban la salsa y el conjunto ligue.","Servir los garbanzos con tomate bien calientes directamente de la sartén."}', 'Garbanzos en salsa de tomate casera con comino', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Prepara el sofrito en una sartén, luego transfiere todo a una cazuela apta para horno. Hornea a 180°C durante 25 minutos para que los sabores se integren y el guiso espese ligeramente."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica las verduras en el vaso, sofríelas con aceite. Añade el tomate, garbanzos y comino, y cocina a 100°C, velocidad cuchara, giro inverso durante 14 minutos para un guiso perfecto."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y pimiento en la olla abierta. Incorpora el tomate, garbanzos y comino, cierra la olla y cocina 5 minutos desde que sube la válvula para potenciar los sabores."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_019', 'Alubias blancas con almejas', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 386, 24, 40, 13, 2, false, true, '{"moluscos","gluten"}', '[{"name":"Alubias blancas cocidas","amount":300,"unit":"g"},{"name":"Almejas","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Harina","amount":10,"unit":"g"}]'::jsonb, '{"Poner almejas en un bol con agua fría y sal durante 20 min para que suelten la arena.","Escurrir y aclarar las almejas bajo agua fría; reservar.","Picar cebolla en trozos muy finos.","Picar ajo en trozos muy finos.","Picar perejil fino; reservar.","Calentar sartén a fuego medio-fuerte; añadir las almejas escurridas y vino blanco; tapar hasta que abran, unos 3 min.","Retirar las almejas abiertas; colar y reservar el caldo de cocción; descartar las que no hayan abierto.","Calentar aceite de oliva en una cazuela a fuego medio; sofreír la cebolla picada hasta que esté transparente, unos 4 min.","Añadir el ajo picado y sofreír 1 min más hasta que empiece a dorarse.","Añadir harina y remover sin parar durante 1 min hasta que se integre con el sofrito.","Incorporar el caldo de almejas reservado y remover hasta que la salsa espese y quede homogénea.","Añadir alubias blancas cocidas y mezclar con suavidad; cocer a fuego suave 5 min hasta que absorban el sabor.","Incorporar las almejas reservadas y el perejil picado; calentar a fuego suave 2 min hasta que todo esté bien caliente.","Servir el guiso en platos hondos con un poco de perejil picado por encima."}', 'Alubias blancas guisadas con almejas en salsa de vino blanco', '[{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Añade la harina, el vino, las alubias y las almejas. Cocina a temperatura y velocidad suaves (giro inverso) hasta que las almejas se abran y la salsa espese, unos 20-25 minutos."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla abierta. Incorpora la harina, el vino y las alubias. Añade las almejas, cierra la olla y cocina a presión baja solo 2-3 minutos desde que sube la válvula, para que las almejas se abran sin sobrecocer."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_020', 'Lentejas pardinas en ensalada templada', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 336, 16, 32, 15, 2, true, true, '{"mostaza","sulfitos"}', '[{"name":"Lentejas pardinas cocidas","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Cebolla morada","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de Módena","amount":10,"unit":"ml"},{"name":"Mostaza","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pimiento rojo y calabacín en dados de 1 cm.","Cortar cebolla morada en juliana fina y reservar en frío.","Mezclar vinagre de módena, mostaza y aceite de oliva en un bol hasta emulsionar.","Calentar sartén a fuego fuerte sin aceite hasta que humee.","Saltear los dados de pimiento rojo y calabacín hasta que estén dorados pero ligeramente crujientes, unos 5 min.","Añadir lentejas pardinas cocidas a la sartén y saltear hasta que estén templadas, unos 2 min.","Retirar la sartén del fuego y volcar las lentejas con las verduras en un bol.","Añadir la vinagreta sobre las lentejas y remover para que se integre bien.","Servir la ensalada templada con la cebolla morada en juliana por encima."}', 'Lentejas pardinas templadas con verduras salteadas y vinagreta', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Corta el pimiento, calabacín y cebolla en trozos. Mézclalos con aceite de oliva, sal y pimienta. Cocínalos en la airfryer a 190°C durante 15-18 minutos, agitando la cesta a mitad del tiempo, hasta que estén tiernos y ligeramente dorados. Mezcla con las lentejas y el aliño."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Trocea el pimiento, calabacín y cebolla, mézclalos con aceite de oliva, sal y pimienta. Extiéndelos en una bandeja y ásalos durante 15-20 minutos hasta que estén tiernos y ligeramente caramelizados. Combina con las lentejas cocidas y el aliño."},{"appliance":"thermomix","time":20,"difficulty":"normal","prepSummary":"Trocea la cebolla, pimiento y calabacín. Sofríelos en el vaso de la Thermomix con aceite a 120°C, velocidad cuchara, durante 10-12 minutos hasta que estén tiernos. Prepara el aliño en el vaso y luego mezcla todo con las lentejas cocidas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
