insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('legumbres_021', 'Ensalada de garbanzos de bote con atún y pimientos', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 460, 29, 33, 23, 2, true, true, '{"pescado","sulfitos"}', '[{"name":"Garbanzos cocidos de bote","amount":300,"unit":"g"},{"name":"Atún en aceite de oliva","amount":160,"unit":"g"},{"name":"Pimiento rojo asado","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Aceitunas negras","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos de bote bajo el grifo hasta que el agua salga limpia.","Escurrir atún en aceite de oliva y reservar el aceite de la lata.","Picar pimiento verde y cebolleta en dados pequeños.","Cortar pimiento rojo asado en tiras finas.","Desmigar el atún con un tenedor.","Añadir en un bol los garbanzos, el atún desmigado, el pimiento verde, la cebolleta y el pimiento rojo.","Añadir aceitunas negras al bol.","Aliñar con aceite de oliva, vinagre de jerez y sal.","Remover bien para integrar el aliño con todos los ingredientes.","Reposar la ensalada en la nevera hasta que esté fría y los sabores se asienten.","Servir la ensalada fría directamente del bol o en platos individuales."}', 'Ensalada rápida de garbanzos de bote con atún, pimientos y aceitunas, lista en cinco minutos.', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Pica los pimientos, la cebolleta y las aceitunas en el vaso. Añade los garbanzos escurridos, el atún y el aliño. Mezcla suavemente a velocidad baja para integrar todos los ingredientes sin triturarlos."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_022', 'Tosta de hummus, pepino y sésamo', 'legumbres', 'legumbre', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 510, 18, 60, 21, 2, true, false, '{"gluten","sesamo"}', '[{"name":"Pan de pueblo","amount":160,"unit":"g"},{"name":"Garbanzos cocidos","amount":240,"unit":"g"},{"name":"Tahini","amount":25,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pepino","amount":150,"unit":"g"},{"name":"Sésamo tostado","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo el grifo con un colador.","Pelar ajo y partir en trozos.","Triturar los garbanzos escurridos con tahini, zumo de limón, el ajo, comino molido y sal hasta obtener una crema lisa.","Añadir aceite de oliva y triturar de nuevo hasta integrar. Añadir un chorrito de agua si la crema ha quedado muy espesa.","Laminar pepino en rodajas finas.","Tostar pan de pueblo en una tostadora o bajo el grill hasta que esté dorado y crujiente.","Untar cada tosta generosamente con el hummus.","Repartir las láminas de pepino sobre el hummus.","Terminar con sésamo tostado y un chorrito de aceite de oliva por encima."}', 'Tostas crujientes untadas con hummus casero, pepino fresco y sésamo tostado.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es ideal para preparar el hummus. Tritura los garbanzos cocidos con el resto de ingredientes (tahini, zumo de limón, ajo, comino, aceite, sal) hasta obtener una crema fina y homogénea. El pan se tuesta aparte en tostadora o sartén y se monta la tosta."},{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"La airfryer es perfecta para tostar el pan de pueblo, dejándolo crujiente por fuera y tierno por dentro. Precalienta a 180°C y tuesta las rebanadas unos 5-7 minutos, dándoles la vuelta a mitad. El hummus se elabora aparte con una batidora o procesador de alimentos."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"El horno es excelente para tostar varias rebanadas de pan a la vez. Precalienta a 200°C con función grill y tuesta el pan durante 5-8 minutos, vigilando para que no se queme. Prepara el hummus aparte con una batidora o procesador de alimentos."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_023', 'Wrap vegetal de hummus y verduras crudas', 'legumbres', 'legumbre', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 420, 15, 55, 16, 2, true, false, '{"gluten","sesamo"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Garbanzos cocidos","amount":200,"unit":"g"},{"name":"Tahini","amount":20,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Pepino","amount":60,"unit":"g"},{"name":"Lechuga","amount":40,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo el grifo hasta que el agua salga limpia.","Pelar y picar ajo muy fino.","Rallar zanahoria con un rallador fino.","Cortar pepino en tiras finas.","Cortar pimiento rojo en tiras finas.","Cortar lechuga en tiras finas.","Triturar los garbanzos escurridos con tahini, zumo de limón, el ajo picado y comino molido hasta que la mezcla sea homogénea.","Añadir aceite de oliva y sal; triturar de nuevo hasta obtener un hummus cremoso.","Calentar tortilla de trigo en una sartén seca a fuego medio hasta que estén flexibles, 20-30 segundos por cada cara.","Untar cada tortilla con una capa generosa de hummus, dejando 2 cm libres en el borde.","Repartir la zanahoria rallada, el pepino, el pimiento rojo y la lechuga sobre el hummus de cada tortilla.","Enrollar cada tortilla apretando bien y cortar por la mitad en diagonal para servir."}', 'Wrap crujiente y colorido de hummus casero con verduras crudas, listo sin encender el fuego.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para el hummus: tritura los garbanzos cocidos con el tahini, zumo de limón, ajo, comino, aceite de oliva y sal durante 2-3 minutos a velocidad progresiva hasta obtener una crema suave. También puedes picar las verduras rápidamente."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_024', 'Bowl de falafel congelado con hummus y ensalada', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 25, 'facil', 'all', 530, 19, 48, 29, 2, true, false, '{"gluten","sesamo"}', '[{"name":"Falafel congelado","amount":200,"unit":"g"},{"name":"Garbanzos cocidos","amount":120,"unit":"g"},{"name":"Tahini","amount":10,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":18,"unit":"ml"},{"name":"Lechuga variada","amount":80,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Hornear falafel congelado en el horno a 200 °C hasta que estén dorados y crujientes.","Triturar garbanzos cocidos con tahini, zumo de limón, comino molido y la mitad de aceite de oliva hasta obtener un hummus homogéneo.","Cortar tomate cherry por la mitad.","Cortar pepino en rodajas.","Laminar cebolla morada en juliana fina.","Repartir lechuga variada como base en 2 boles.","Añadir el tomate cherry, el pepino y la cebolla morada sobre la lechuga.","Colocar el falafel horneado sobre la ensalada y una cucharada generosa de hummus.","Terminar con el resto del aceite de oliva y sal."}', 'Bowl completo con falafel del congelador, hummus rápido y ensalada fresca, listo en diez minutos.', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Cocina los falafel congelados durante 20-25 minutos, dándoles la vuelta a mitad para que doren uniformemente. Mientras, prepara el hummus y la ensalada."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Cocina los falafel congelados en la airfryer a 190°C durante 15-18 minutos, agitándolos a mitad de cocción para un acabado crujiente y dorado. Aprovecha para preparar el hummus y la ensalada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_025', 'Lentejas guisadas con chorizo y huevo poché', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 520, 27, 42, 26, 2, true, false, '{"huevo"}', '[{"name":"Lentejas pardinas","amount":200,"unit":"g"},{"name":"Chorizo","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar lentejas pardinas bajo el grifo y escurrir.","Pelar y picar cebolla en dados pequeños.","Picar ajo fino.","Cortar pimiento verde en dados pequeños.","Pelar y cortar zanahoria en dados pequeños.","Cortar chorizo en rodajas.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla, el ajo y el pimiento verde hasta que ablanden.","Añadir la zanahoria y el chorizo y sofreír hasta que el chorizo suelte su color.","Añadir pimentón dulce y tomate triturado y remover durante 1 min.","Añadir las lentejas pardinas y laurel y cubrir con agua hasta 3 cm por encima.","Llevar a ebullición a fuego fuerte.","Bajar el fuego, tapar y cocer hasta que las lentejas estén tiernas.","Llevar agua a ebullición en un cazo a fuego suave y añadir vinagre.","Remover el agua para crear un remolino y cascar huevo de uno en uno en el centro.","Cocer cada huevo hasta que la clara esté cuajada y la yema aún líquida.","Retirar los huevos con espumadera y reservar.","Servir las lentejas en platos hondos y coronar cada uno con un huevo poché."}', 'Lentejas guisadas con chorizo y coronadas con un huevo poché que rompe su yema sobre el guiso.', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Prepara el sofrito con las verduras y el chorizo en una cazuela apta para horno en la encimera. Luego, añade las lentejas, el pimentón, el laurel y el caldo, y cocina a fuego lento en el horno a 160-170°C durante 1.5-2 horas hasta que estén tiernas. Los huevos poché se hacen apar"},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríe en el vaso. Añade las lentejas, chorizo, pimentón, laurel y agua/caldo, programa 35-40 min, Varoma/100°C, giro inverso, velocidad cuchara. Los huevos poché se pueden hacer en el Varoma al mismo tiempo o al final para un resultado óptimo."},{"appliance":"olla_express","time":40,"difficulty":"normal","prepSummary":"Sofríe las verduras y el chorizo en la olla. Incorpora las lentejas, pimentón, laurel y agua/caldo. Cierra la olla y cocina a presión durante 15-20 minutos. Libera la presión y sirve las lentejas con los huevos poché hechos al momento en una cacerola aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_026', 'Hummus de remolacha con piñones tostados', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 470, 15, 41, 27, 2, true, true, '{"sesamo","frutos_secos"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Remolacha cocida","amount":150,"unit":"g"},{"name":"Tahini","amount":30,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos y enjuagarlos bajo el grifo.","Cortar remolacha cocida en dados.","Pelar ajo.","Tostar piñones en sartén sin aceite a fuego medio hasta que estén dorados, removiendo para que no se quemen.","Retirar los piñones de la sartén y reservar.","Triturar los garbanzos, la remolacha, tahini, zumo de limón, el ajo y comino molido hasta obtener una crema fina.","Añadir aceite de oliva poco a poco sin dejar de triturar hasta ligar la crema.","Añadir sal y triturar un instante más hasta integrar.","Extender el hummus en un plato haciendo un hueco en el centro con el dorso de una cuchara.","Repartir los piñones tostados por encima y servir."}', 'Hummus de un magenta intenso gracias a la remolacha, coronado con piñones tostados.', '[{"appliance":"thermomix","time":12,"difficulty":"facil","prepSummary":"Introduce todos los ingredientes (excepto los piñones) en el vaso de la Thermomix y tritura a velocidad progresiva hasta obtener una crema fina y homogénea. Sirve con los piñones tostados, que puedes hacer rápidamente en una sartén o en el mismo vaso de la Thermomix."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_027', 'Hummus de aguacate y lima', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 400, 12, 32, 25, 2, true, false, '{"sesamo"}', '[{"name":"Garbanzos cocidos","amount":250,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Zumo de lima","amount":25,"unit":"ml"},{"name":"Tahini","amount":15,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo el grifo y reservar.","Cortar aguacate por la mitad y retirar el hueso.","Sacar la pulpa del aguacate con una cuchara y reservar.","Pelar ajo y reservar.","Triturar los garbanzos con la pulpa de aguacate, zumo de lima, tahini, el ajo y comino molido hasta obtener una crema homogénea.","Añadir aceite de oliva poco a poco mientras se tritura, hasta que la crema quede suave y cremosa.","Añadir sal y triturar unos segundos hasta integrar.","Picar cilantro fresco finamente.","Servir el hummus en un bol, espolvorear el cilantro picado por encima y añadir un chorrito de aceite de oliva."}', 'Hummus cremoso y verde con aguacate y un toque ácido de lima que lo levanta.', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce todos los ingredientes en el vaso de la Thermomix y tritura a velocidad progresiva 5-10 hasta obtener una crema suave y homogénea. Si es necesario, baja los restos de las paredes y vuelve a triturar brevemente."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_028', 'Falafel crujiente con salsa de yogur y tahini', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 610, 27, 50, 33, 2, true, false, '{"gluten","lactosa","sesamo"}', '[{"name":"Garbanzos secos crudos (en remojo)","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil fresco","amount":15,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Comino molido","amount":5,"unit":"g"},{"name":"Cilantro molido","amount":3,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Levadura química","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Yogur griego","amount":150,"unit":"g"},{"name":"Tahini","amount":20,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Agua","amount":20,"unit":"ml"}]'::jsonb, '{"Escurrir garbanzos secos crudos (en remojo) y reservar.","Cortar cebolla en trozos y pelar ajo.","Triturar los garbanzos escurridos, la cebolla, el ajo, perejil fresco y cilantro fresco hasta obtener una pasta gruesa.","Añadir comino molido, cilantro molido, harina, levadura química y sal a la pasta.","Mezclar bien hasta integrar todos los ingredientes.","Tapar la masa y dejar reposar en la nevera.","Mezclar yogur griego, tahini, zumo de limón y agua en un bol hasta obtener una crema fluida.","Formar bolitas de unos 3 cm con las manos húmedas usando la masa reposada.","Calentar aceite de girasol en sartén honda a fuego medio-alto hasta que esté bien caliente.","Freír las bolitas en tandas hasta que estén doradas y crujientes por fuera.","Escurrir los falafel fritos sobre papel absorbente.","Servir los falafel calientes junto a la salsa de yogur y tahini para mojar."}', 'Falafel casero con una corteza dorada y crujiente, servido con salsa fresca de yogur y tahini.', '[{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Prepara la mezcla de falafel y forma las bolitas. Rocíalas ligeramente con aceite y cocínalas en la airfryer precalentada a 190-200°C durante 15-20 minutos, dándoles la vuelta a mitad del tiempo para un dorado uniforme y crujiente."},{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Forma los falafel y colócalos en una bandeja de horno con papel de hornear, rociados con un poco de aceite. Hornea a 180-190°C durante 25-30 minutos, volteándolos a mitad de cocción hasta que estén dorados y firmes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_029', 'Fabes con almejas y azafrán', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 90, 'normal', 'all', 480, 31, 46, 18, 2, false, true, '{"moluscos","sulfitos"}', '[{"name":"Fabes de la granja secas","amount":200,"unit":"g"},{"name":"Almejas","amount":300,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Poner fabes de la granja secas en un bol grande cubiertas de agua fría y dejar en remojo.","Pelar cebolla y dejarla entera.","Pelar ajo y dejarlo entero.","Escurrir las fabes y colocarlas en una olla cubiertas de agua fría 3 dedos por encima.","Añadir la cebolla, el ajo, laurel y aceite de oliva a la olla.","Llevar a ebullición a fuego fuerte.","Retirar la espuma que suba a la superficie con una espumadera.","Bajar el fuego al mínimo, tapar y cocer hasta que las fabes estén tiernas, añadiendo agua fría si rompe a hervir fuerte.","Poner almejas en un bol con agua fría y sal durante 30 min para que suelten la arena.","Calentar vino blanco en un cazo pequeño a fuego suave hasta que esté caliente.","Disolver azafrán en hebras en el vino blanco caliente y reservar.","Escurrir las almejas y reservar.","Retirar la cebolla y el ajo cocidos de la olla y triturarlos con un poco del caldo de cocción.","Devolver el triturado a la olla y remover para ligar el guiso.","Añadir el vino con azafrán a la olla y remover.","Añadir las almejas escurridas, tapar y cocer a fuego medio hasta que todas las almejas se abran.","Picar perejil fresco fino.","Espolvorear el perejil picado sobre el guiso y servir bien caliente."}', 'Fabes tiernas en caldo dorado por el azafrán, con almejas recién abiertas encima.', '[{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Prepara un sofrito con cebolla y ajo, añade las fabes previamente remojadas y el resto de ingredientes para cocerlas a temperatura Varoma o 100°C durante 60-90 minutos. Incorpora las almejas al final en el vaso o Varoma hasta que se abran."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla. Añade las fabes remojadas, el vino, el azafrán y el laurel, cubre con agua y cocina a presión durante 20-30 minutos. Despresuriza, añade las almejas y cocina unos minutos más hasta que se abran."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_030', 'Ensalada templada de lentejas, chorizo y manzana', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 430, 24, 38, 20, 2, true, true, '{"sulfitos","mostaza"}', '[{"name":"Lentejas pardinas","amount":200,"unit":"g"},{"name":"Chorizo","amount":80,"unit":"g"},{"name":"Manzana","amount":150,"unit":"g"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Vinagre de jerez","amount":15,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Mostaza a la antigua","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar lentejas pardinas bajo el grifo con agua fría hasta que salga clara.","Cocer las lentejas pardinas en una olla con agua fría y laurel a fuego fuerte hasta que rompa a hervir.","Bajar el fuego y cocer las lentejas pardinas a fuego suave hasta que estén tiernas pero enteras.","Cortar chorizo en dados pequeños.","Cortar manzana en dados pequeños, sin pelar.","Picar cebolleta en aros finos.","Mezclar aceite de oliva, vinagre de jerez, mostaza a la antigua y sal en un bol pequeño hasta emulsionar.","Escurrir las lentejas pardinas y dejarlas templar en un bol amplio.","Dorar el chorizo en sartén sin aceite a fuego medio hasta que quede crujiente y suelte su grasa.","Retirar el chorizo sobre papel absorbente.","Añadir la manzana, la cebolleta y el chorizo al bol con las lentejas templadas.","Aliñar con la vinagreta y remover con cuidado hasta integrar. Servir templado."}', 'Lentejas templadas con chorizo dorado y crujiente, manzana fresca y una vinagreta de mostaza.', '[{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Cocina las lentejas en el vaso a 100°C con giro inverso (aprox. 25-30 min). Sofríe el chorizo y la cebolleta en el mismo vaso o en una sartén aparte, y luego mezcla con la manzana y el aliño."},{"appliance":"olla_express","time":30,"difficulty":"facil","prepSummary":"Cuece las lentejas en la olla express (8-12 min desde que sube la válvula) para un cocinado rápido. Mientras, dora el chorizo y la cebolleta en una sartén, y saltea la manzana brevemente. Combina todo y aliña."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('legumbres_031', 'Garbanzos especiados con espinacas y piñones', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 380, 16, 34, 20, 2, true, true, '{"frutos_secos","sulfitos"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Espinacas frescas","amount":200,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Comino molido","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo el grifo y reservar.","Lavar espinacas frescas con abundante agua fría y escurrir bien.","Laminar ajo.","Calentar sartén a fuego medio sin aceite y tostar piñones hasta que estén dorados.","Retirar los piñones y reservar.","Calentar aceite de oliva en la misma sartén a fuego medio y sofreír el ajo laminado hasta que esté dorado.","Añadir comino molido y pimentón dulce y remover unos segundos hasta que suelten aroma.","Incorporar los garbanzos escurridos y saltear hasta que cojan el sabor de las especias.","Añadir las espinacas escurridas y saltear hasta que se reduzcan.","Rociar con vinagre de jerez y añadir sal y remover para integrar.","Servir los garbanzos con espinacas y repartir los piñones tostados por encima."}', 'Garbanzos salteados con especias, espinacas y piñones tostados, con aroma a comino.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Mezcla los garbanzos con aceite, ajo, comino y pimentón. Cocina en la airfryer a 190°C durante 15 minutos, agitando a mitad. Añade los piñones los últimos 3 minutos y las espinacas al final para que se marchiten con el calor residual."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Extiende los garbanzos con aceite, ajo, comino y pimentón en una bandeja. Hornea a 200°C durante 20 minutos, removiendo a mitad. Incorpora los piñones los últimos 5 minutos y las espinacas al sacar para que se ablanden con el calor."},{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Sofríe el ajo con aceite. Añade los garbanzos, especias y piñones, cocina unos minutos a temperatura Varoma, giro inverso, velocidad cuchara. Incorpora las espinacas y cocina 2-3 minutos más hasta que se marchiten."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_032', 'Lentejas rojas al curry con leche de coco', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 410, 17, 44, 19, 2, true, true, '{}', '[{"name":"Lentejas rojas peladas","amount":180,"unit":"g"},{"name":"Leche de coco","amount":200,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Curry en polvo","amount":10,"unit":"g"},{"name":"Cúrcuma","amount":3,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Enjuagar lentejas rojas peladas bajo el grifo hasta que el agua salga clara.","Pelar y picar fino cebolla.","Pelar y picar fino ajo.","Pelar y picar fino jengibre fresco.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir el ajo picado y el jengibre picado y sofreír hasta que suelten el aroma.","Añadir curry en polvo y cúrcuma y remover para tostar las especias.","Añadir tomate triturado y cocinar hasta que se integre con las especias.","Añadir las lentejas enjuagadas y leche de coco.","Cubrir con agua hasta superar los ingredientes 2 cm y llevar a ebullición.","Cocer a fuego suave hasta que las lentejas se deshagan y el curry espese, removiendo de vez en cuando.","Picar cilantro fresco fino.","Rectificar con sal.","Servir el curry en cuencos y espolvorear el cilantro picado por encima."}', 'Curry cremoso de lentejas rojas con leche de coco, sin nata y con mucho sabor.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica y sofríe la cebolla, ajo y jengibre con aceite. Incorpora las lentejas, leche de coco, tomate y especias, y cocina a 90-100°C, velocidad cuchara, durante unos 20 minutos hasta que las lentejas estén tiernas."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y jengibre en la olla. Añade las lentejas, leche de coco, tomate y especias, cierra la olla y cocina a presión durante 5-7 minutos. Deja despresurizar antes de abrir y servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_033', 'Hummus de guisantes y menta', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 320, 13, 26, 19, 2, true, true, '{"sesamo"}', '[{"name":"Guisantes congelados","amount":250,"unit":"g"},{"name":"Garbanzos cocidos","amount":100,"unit":"g"},{"name":"Tahini","amount":15,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua con sal en un cazo a fuego fuerte.","Cocer guisantes congelados en el agua hirviendo hasta que estén tiernos.","Escurrir los guisantes y refrescar bajo agua fría hasta que estén completamente fríos.","Escurrir y enjuagar garbanzos cocidos bajo agua fría.","Pelar ajo y reservar.","Separar la mitad de menta fresca y reservar para el emplatado.","Triturar los guisantes, los garbanzos, tahini, zumo de limón, el ajo y la mitad de la menta hasta obtener una crema fina.","Añadir aceite de oliva poco a poco mientras se tritura hasta ligar la crema.","Rectificar de sal al gusto y triturar un instante más para integrar.","Picar la menta reservada en fino.","Servir el hummus en un bol y espolvorear la menta picada por encima."}', 'Hummus verde y fresco de guisantes y menta, distinto al hummus clásico.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Cocina los guisantes al vapor en el Varoma (10-12 min). Luego, añade los demás ingredientes al vaso y tritura a velocidad progresiva hasta obtener una crema suave y homogénea."},{"appliance":"vaporera","time":15,"difficulty":"facil","prepSummary":"Cuece los guisantes al vapor hasta que estén tiernos (8-10 min). Después, tritura los guisantes cocidos con el resto de ingredientes en una batidora hasta lograr una textura cremosa."},{"appliance":"microondas","time":10,"difficulty":"facil","prepSummary":"Cocina los guisantes en el microondas con un poco de agua en un recipiente tapado (3-5 min). Luego, procesa los guisantes con los demás ingredientes en una batidora hasta conseguir un hummus cremoso."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_034', 'Buñuelos de garbanzo especiados', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 480, 20, 42, 26, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Harina","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Comino molido","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Levadura química","amount":3,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Yogur natural","amount":100,"unit":"g"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Ajo","amount":3,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos con un colador y secarlos bien con papel de cocina.","Picar cebolleta muy fina.","Picar perejil fresco fino.","Triturar los garbanzos escurridos con la cebolleta picada, el perejil picado, comino molido y pimentón dulce hasta obtener una pasta gruesa.","Añadir huevo, harina, levadura química y sal a la pasta.","Mezclar todo hasta integrar una masa espesa y homogénea.","Tapar la masa y reposar en la nevera 10 min.","Rallar ajo fino.","Picar menta fresca fina.","Mezclar yogur natural con la menta picada y el ajo rallado hasta integrar. Reservar en frío.","Calentar aceite de girasol en una sartén honda a fuego medio hasta que esté caliente.","Formar los buñuelos con 2 cucharas cogiendo porciones de masa del tamaño de una nuez.","Freír los buñuelos en tandas hasta que estén dorados por todos los lados, unos 3-4 min por tanda.","Escurrir los buñuelos sobre papel absorbente.","Servir los buñuelos calientes acompañados de la salsa de yogur y menta."}', 'Buñuelos de garbanzo dorados y crujientes por fuera, tiernos por dentro, con salsa de yogur.', '[{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Forma los buñuelos y rocíalos ligeramente con aceite. Cocínalos en la airfryer precalentada a 180-190°C durante 15-20 minutos, dándoles la vuelta a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Prepara la masa y forma los buñuelos. Colócalos en una bandeja de horno con papel de hornear, pincela con un poco de aceite y hornea a 200°C durante 20-25 minutos, hasta que estén dorados."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Utiliza la Thermomix para picar finamente la cebolleta, el perejil, la menta y el ajo, y para mezclar todos los ingredientes de los buñuelos y la salsa de yogur en pocos minutos. Luego, cocina los buñuelos en sartén, horno o airfryer."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_035', 'Ensalada de garbanzos, chorizo crujiente y pimientos', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 460, 24, 38, 24, 2, true, true, '{"sulfitos"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Chorizo","amount":90,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de jerez","amount":12,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos y enjuagarlos bajo el grifo.","Cortar chorizo en dados pequeños.","Calentar sartén a fuego medio sin aceite y dorar el chorizo hasta que esté crujiente.","Retirar el chorizo sobre papel absorbente y reservar la grasa de la sartén.","Cortar pimiento rojo en dados pequeños.","Cortar pimiento verde en dados pequeños.","Picar cebolla morada en juliana fina.","Picar perejil fresco fino.","Mezclar en un bol los garbanzos escurridos, el pimiento rojo, el pimiento verde, la cebolla morada y el perejil picado.","Añadir el chorizo crujiente y la grasa reservada por encima de la mezcla.","Aliñar con aceite de oliva, vinagre de jerez y sal.","Remover bien y servir de inmediato."}', 'Ensalada contundente de garbanzos con chorizo crujiente y pimientos de colores.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta el chorizo en rodajas y los pimientos en tiras. Cocina en la airfryer a 190°C durante 12-15 minutos, agitando a mitad, hasta que el chorizo esté crujiente y los pimientos tiernos. Luego, mezcla con los garbanzos y el resto de ingredientes."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Dispón el chorizo en rodajas y los pimientos en tiras en una bandeja de horno y ásalos durante 15-20 minutos, hasta que el chorizo esté crujiente y los pimientos asados. Luego, mezcla con los garbanzos y el resto de ingredientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_036', 'Judiones con almejas', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 100, 'normal', 'all', 470, 30, 46, 18, 2, false, true, '{"moluscos","sulfitos"}', '[{"name":"Judiones secos","amount":250,"unit":"g"},{"name":"Almejas","amount":350,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Poner judiones secos en un bol cubiertos de agua fría y dejar en remojo toda la noche.","Escurrir los judiones y trasladarlos a una olla grande.","Pelar cebolla y añadirla entera a la olla junto con laurel y aceite de oliva.","Cubrir con agua fría y llevar a ebullición a fuego fuerte.","Retirar la espuma con una espumadera hasta que el caldo quede limpio.","Bajar el fuego al mínimo, tapar y cocer hasta que los judiones estén cremosos por fuera y enteros por dentro.","Cubrir almejas con agua fría y sal y dejar reposar 30 min para que suelten la arena.","Picar ajo muy fino.","Picar perejil fresco fino y reservar.","Escurrir las almejas y reservar.","Sacar la cebolla cocida de la olla y triturarla con un cucharón de caldo hasta obtener una crema lisa.","Devolver la crema de cebolla a la olla y remover para ligar el caldo con los judiones.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír el ajo picado a fuego suave hasta que empiece a dorarse sin quemarse.","Añadir pimentón dulce a la sartén, remover y retirar del fuego en 10 segundos para que no se queme.","Añadir vino blanco a la sartén y dejar reducir a fuego medio hasta que el alcohol se evapore.","Volcar el sofrito de ajo, pimentón y vino sobre la olla de judiones y remover para integrar.","Añadir las almejas escurridas a la olla, tapar y cocer a fuego medio hasta que todas las almejas se abran.","Retirar las almejas que no se hayan abierto y desechar.","Espolvorear el perejil picado sobre el guiso y servir bien caliente en plato hondo."}', 'Judiones enormes y cremosos en caldo dorado, con almejas recién abiertas.', '[{"appliance":"thermomix","time":90,"difficulty":"normal","prepSummary":"Prepara el sofrito en el vaso (10 min, 120°C, vel 1). Añade los judiones remojados y agua, cocinando 60-90 min (100°C, giro inverso, vel cuchara). Incorpora las almejas en los últimos 5-7 min, cocinando hasta que se abran."},{"appliance":"olla_express","time":40,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla (10 min). Añade los judiones remojados, pimentón, laurel y agua, cociendo a presión durante 20-30 min. Despresuriza, incorpora las almejas y cocina sin tapa 5 min más hasta que se abran."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_037', 'Lentejas con boletus y tomillo', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'invierno', 380, 19, 42, 14, 2, true, true, '{"sulfitos"}', '[{"name":"Lentejas pardinas","amount":200,"unit":"g"},{"name":"Boletus","amount":200,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Tomillo fresco","amount":5,"unit":"g"},{"name":"Vino oloroso","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar lentejas pardinas bajo el grifo y escurrir.","Limpiar boletus con un paño húmedo y laminar en láminas gruesas.","Pelar cebolla y picar en dados pequeños.","Pelar ajo y picar fino.","Pelar zanahoria y cortar en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y la zanahoria a fuego medio hasta que ablanden.","Añadir el ajo picado y sofreír hasta que empiece a dorarse.","Incorporar los boletus laminados y saltear a fuego fuerte hasta que se doren.","Añadir vino oloroso y remover hasta que se evapore el alcohol.","Incorporar las lentejas escurridas, laurel y tomillo fresco.","Cubrir con agua fría hasta superar 3 cm por encima y llevar a ebullición a fuego fuerte.","Bajar el fuego suave, tapar y cocer hasta que las lentejas estén tiernas.","Añadir sal y remover para integrar.","Servir en cuencos bien caliente con un chorrito de aceite de oliva."}', 'Guiso reconfortante de lentejas con boletus salteados y aroma a tomillo fresco.', '[{"appliance":"horno","time":75,"difficulty":"normal","prepSummary":"Sofríe los aromáticos en una olla apta para horno. Añade las lentejas, boletus, vino, caldo o agua y especias. Cocina tapado en el horno precalentado a 160°C durante 75 minutos, removiendo ocasionalmente, para una cocción lenta y uniforme."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"Sofríe la cebolla, ajo y zanahoria en el vaso. Incorpora las lentejas, boletus, vino, agua/caldo y especias, y cocina a 100°C, giro inverso, velocidad cuchara durante 45 minutos, hasta que las lentejas estén tiernas."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Sofríe los vegetales en la olla express. Añade las lentejas, boletus, vino y caldo, cierra la olla y cocina a presión durante 12-15 minutos. Deja despresurizar naturalmente para un resultado tierno y sabroso en menos tiempo."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('legumbres_038', 'Garbanzos con espinacas y huevo escalfado', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 400, 20, 34, 20, 2, true, false, '{"huevo","gluten"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Espinacas frescas","amount":200,"unit":"g"},{"name":"Pan del día anterior","amount":40,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Comino molido","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo agua fría y reservar.","Lavar espinacas frescas con abundante agua fría y escurrir bien.","Cortar pan del día anterior en dados pequeños.","Pelar y laminar ajo.","Calentar aceite de oliva en sartén a fuego medio.","Freír el pan en dados hasta que esté dorado. Retirar y reservar en un mortero o vaso triturador.","Freír el ajo laminado en la misma sartén hasta que se dore. Retirar y añadir al pan.","Añadir comino molido y un chorrito de agua al mortero y triturar hasta obtener un majado homogéneo.","Calentar el resto del aceite en una cazuela a fuego suave.","Añadir pimentón dulce y remover durante 10 segundos hasta que empiece a soltar aroma, sin dejar que se queme.","Incorporar los garbanzos escurridos y las espinacas. Saltear a fuego medio hasta que las espinacas se reduzcan.","Añadir el majado y un chorrito de agua. Remover y cocer a fuego suave hasta que la mezcla ligue.","Llevar a ebullición agua en un cazo. Añadir vinagre y reducir a fuego suave.","Cascar huevo uno a uno en un cuenco y deslizar cada uno con cuidado en el agua con vinagre.","Cocer los huevos 3 min hasta que la clara esté cuajada y la yema aún líquida. Retirar con espumadera.","Salpimentar los garbanzos con sal y remover.","Servir los garbanzos en platos hondos y coronar cada uno con un huevo escalfado."}', 'Garbanzos con espinacas al estilo andaluz, con la yema del huevo escalfado rota por encima.', '[{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Sofríe el ajo en el vaso con aceite. Incorpora los garbanzos, espinacas y especias, cocinando a temperatura Varoma. Escalfa los huevos en el recipiente Varoma al mismo tiempo para optimizar el tiempo."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo en la olla abierta. Añade los garbanzos, espinacas y especias con un poco de agua y cocina a presión 3-5 minutos. Escalfa los huevos por separado en un cazo con agua y vinagre."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_039', 'Potaje de garbanzos con langostinos', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 428, 30, 36, 18, 2, true, true, '{"marisco","pescado"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Langostinos","amount":250,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":300,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo agua fría y reservar.","Pelar langostinos, reservando las cabezas y cáscaras aparte.","Picar cebolla en dados pequeños.","Picar ajo fino.","Cortar pimiento rojo en dados pequeños.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír las cabezas y cáscaras de langostino hasta que estén doradas y suelten su jugo.","Retirar las cabezas y cáscaras de la cazuela y desechar.","Sofreír la cebolla picada, el ajo picado y el pimiento rojo a fuego medio hasta que ablanden.","Añadir pimentón dulce y remover para que no se queme.","Añadir tomate triturado y cocinar hasta que pierda el agua y la mezcla espese.","Incorporar los garbanzos escurridos, azafrán en hebras y caldo de pescado.","Cocer a fuego medio hasta que los sabores se integren y el caldo reduzca ligeramente.","Añadir los langostinos pelados y cocer hasta que cambien de color y estén hechos.","Salpimentar con sal y remover para integrar.","Servir el potaje bien caliente en cuencos hondos."}', 'Potaje de garbanzos dorado con langostinos, un guiso contundente y marinero.', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Se puede preparar en una cazuela apta para horno. Primero, hacer el sofrito en la misma cazuela sobre la encimera, luego añadir el resto de ingredientes (excepto langostinos), cubrir y hornear a 180°C durante 40-50 minutos. Incorporar los langostinos los últimos 10 minutos."},{"appliance":"thermomix","time":40,"difficulty":"facil","prepSummary":"Ideal para este potaje, ya que pica las verduras, sofríe y cocina en el mismo vaso. Sofreír cebolla, ajo y pimiento, añadir el resto de ingredientes (excepto langostinos) y programar 25-30 minutos a 100°C, velocidad cuchara. Incorporar los langostinos los últimos 5 minutos."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Perfecta para acelerar el proceso. Sofríe las verduras en la olla, añade los garbanzos, tomate, caldo y especias. Cierra la olla y cocina a presión durante 10-12 minutos. Libera la presión, añade los langostinos y cocina unos minutos más hasta que estén hechos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_040', 'Fabada asturiana ligera con compango crujiente', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 130, 'elaborada', 'invierno', 610, 34, 42, 34, 4, true, true, '{}', '[{"name":"Fabes de la granja secas","amount":400,"unit":"g"},{"name":"Chorizo asturiano","amount":150,"unit":"g"},{"name":"Morcilla asturiana","amount":150,"unit":"g"},{"name":"Panceta","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Laurel","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cubrir fabes de la granja secas con agua fría abundante y dejar en remojo 12 h.","Pelar cebolla y dejarla entera. Pelar ajo y dejar los dientes enteros.","Escurrir las fabes y colocarlas en una olla grande. Cubrir con agua fría.","Añadir la cebolla entera, el ajo, laurel, chorizo asturiano y panceta a la olla.","Llevar a ebullición a fuego fuerte. Retirar la espuma que suba a la superficie con una espumadera.","Bajar el fuego al mínimo y tapar la olla. Cocer 75 min, añadiendo un chorro de agua fría cada vez que rompa a hervir fuerte.","Calentar un poco de caldo de cocción en un cazo pequeño a fuego suave.","Disolver azafrán en hebras y pimentón dulce en el caldo caliente del cazo. Remover hasta integrar.","Verter el caldo con el azafrán y el pimentón en la olla. Remover con suavidad.","Añadir morcilla asturiana entera a la olla. Cocer a fuego mínimo tapado 20 min.","Cortar el chorizo asturiano en rodajas de 1 cm de grosor.","Calentar aceite de oliva en sartén a fuego fuerte.","Dorar las rodajas de chorizo en la sartén a fuego fuerte hasta que estén crujientes. Reservar.","Retirar la cebolla, el ajo y el laurel de la olla.","Sacar el chorizo, la morcilla y la panceta de la olla. Cortar en trozos.","Añadir sal a las fabes y remover con suavidad.","Servir las fabes con el compango troceado encima y las rodajas de chorizo crujiente por encima."}', 'Fabada asturiana clásica aligerada, con el compango extra dorado y crujiente por encima.', '[{"appliance":"horno","time":200,"difficulty":"elaborada","prepSummary":"Las fabes, previamente remojadas, se cocinan lentamente en una cazuela de hierro fundido tapada a 160°C durante unas 3 horas. El compango se asa en una bandeja aparte a 200°C los últimos 20 minutos para que quede crujiente y se incorpora al guiso."},{"appliance":"olla_express","time":80,"difficulty":"normal","prepSummary":"Las fabes, tras un remojo de 12 horas, se cocinan con los aromáticos y el compango en la olla express a presión durante 35-40 minutos. Para el toque crujiente, el compango se puede dorar en una sartén o airfryer antes de añadirlo al final."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
