insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('legumbres_041', 'Alubias blancas estofadas con costilla', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 95, 'normal', 'all', 560, 34, 38, 30, 2, true, true, '{}', '[{"name":"Alubias blancas secas","amount":200,"unit":"g"},{"name":"Costilla de cerdo","amount":300,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Poner alubias blancas secas en un bol grande cubierto con agua fría abundante y dejar en remojo toda la noche.","Pelar y picar cebolla en trozos pequeños.","Pelar y picar ajo fino.","Pelar y cortar zanahoria en rodajas finas.","Cortar pimiento verde en trozos pequeños.","Escurrir las alubias del agua de remojo y reservar.","Salpimentar costilla de cerdo por todos los lados con sal.","Calentar aceite de oliva en una olla a fuego fuerte.","Dorar la costilla de cerdo por todos los lados hasta que esté dorada.","Retirar la costilla de cerdo dorada y reservar en un plato.","Bajar el fuego a medio y sofreír la cebolla, el ajo, la zanahoria y el pimiento verde en la misma olla.","Añadir pimentón dulce y remover hasta que el sofrito huela a especias tostadas.","Añadir tomate triturado y cocinar hasta que pierda el exceso de agua y se integre con el sofrito.","Incorporar las alubias escurridas, la costilla de cerdo dorada y laurel.","Cubrir con agua fría hasta superar los ingredientes unos 3 cm y llevar a ebullición a fuego fuerte.","Retirar la espuma que suba a la superficie con una cuchara.","Bajar el fuego al mínimo, tapar y cocer hasta que las alubias estén tiernas y la carne se separe del hueso.","Rectificar de sal al gusto y retirar el laurel.","Tapar y reposar fuera del fuego antes de servir.","Servir las alubias blancas estofadas bien calientes con la costilla de cerdo."}', 'Alubias blancas estofadas con costilla de cerdo, caldo espeso y carne que se deshace.', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora las costillas en una olla apta para horno. Añade las alubias remojadas, tomate, pimentón, laurel y agua. Hornea a 160°C durante 120 minutos hasta que las alubias y la costilla estén tiernas, removiendo ocasionalmente."},{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Prepara el sofrito en el vaso. Incorpora las costillas troceadas y sofríe. Añade las alubias remojadas, tomate, pimentón, laurel y caldo. Cocina a 100°C, giro inverso, velocidad cuchara durante 90-100 minutos, ajustando el tiempo hasta que las alubias y la costilla estén tiernas."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora las costillas en la olla. Añade las alubias remojadas, tomate, pimentón, laurel y agua. Cierra la olla y cocina a presión durante 35-40 minutos. Deja despresurizar naturalmente para una costilla y alubias muy tiernas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_042', 'Lentejas con verduras de otoño y castañas', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'invierno', 400, 18, 55, 12, 2, true, true, '{}', '[{"name":"Lentejas pardinas","amount":200,"unit":"g"},{"name":"Castañas cocidas","amount":150,"unit":"g"},{"name":"Calabaza","amount":150,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomillo fresco","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar lentejas pardinas bajo el grifo y escurrir.","Laminar ajo.","Cortar puerro en rodajas finas.","Pelar zanahoria y cortarla en dados pequeños.","Pelar calabaza y cortarla en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y el ajo hasta que ablanden.","Añadir la zanahoria y la calabaza y sofreír a fuego medio.","Incorporar las lentejas escurridas y tomillo fresco y remover.","Añadir caldo de verduras y llevar a ebullición a fuego fuerte.","Bajar el fuego, tapar y cocer hasta que las lentejas empiecen a estar tiernas.","Añadir castañas cocidas y cocer tapado hasta que las lentejas estén completamente tiernas.","Salpimentar con sal y remover.","Servir las lentejas bien calientes."}', 'Lentejas con verduras de otoño y castañas dulces, un guiso de colores cálidos.', '[{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Sofríe las verduras en una cazuela apta para horno con el aceite, añade las lentejas, el caldo, las castañas y el tomillo. Tapa y cocina en el horno precalentado a 170°C durante 50-60 minutos hasta que las lentejas estén tiernas y los sabores bien integrados."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas con aceite. Añade las lentejas, el caldo, las castañas y el tomillo, y programa 40-45 minutos, 100°C, velocidad cuchara, giro inverso, hasta obtener unas lentejas cremosas y en su punto."},{"appliance":"olla_express","time":30,"difficulty":"facil","prepSummary":"Prepara un sofrito con las verduras en la olla, incorpora las lentejas, el caldo, las castañas y el tomillo. Cierra la olla y cocina a presión durante 10-12 minutos desde que sube la válvula, dejando despresurizar de forma natural para un resultado óptimo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_043', 'Ensalada de alubias, atún y pimientos', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 420, 28, 32, 20, 2, true, true, '{"pescado","sulfitos"}', '[{"name":"Alubias blancas cocidas de bote","amount":350,"unit":"g"},{"name":"Atún en aceite de oliva","amount":160,"unit":"g"},{"name":"Pimiento rojo asado","amount":100,"unit":"g"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Aceitunas negras","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir alubias blancas cocidas de bote con un colador y enjuagar bajo el grifo hasta que el agua salga limpia.","Escurrir atún en aceite de oliva y desmigar con un tenedor en trozos medianos.","Cortar pimiento rojo asado en tiras finas.","Cortar cebolleta en aros finos.","Picar perejil fresco fino.","Mezclar en un bol las alubias escurridas, el atún desmigado, las tiras de pimiento rojo asado y los aros de cebolleta.","Añadir aceitunas negras y el perejil picado al bol.","Aliñar con aceite de oliva, vinagre de jerez y sal.","Remover con cuidado hasta que el aliño cubra todos los ingredientes sin romper las alubias."}', 'Ensalada fresca de alubias con atún y pimientos, perfecta para tupper o para plato.', '[{"appliance":"thermomix","time":12,"difficulty":"facil","prepSummary":"Pica la cebolleta y el perejil en el vaso durante unos segundos. Luego añade las alubias escurridas, el atún, el pimiento asado, las aceitunas, el aceite, el vinagre y la sal, y mezcla a velocidad cuchara o giro inverso para integrar suavemente sin triturar."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_044', 'Garbanzos con calamares', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 418, 32, 36, 16, 2, true, true, '{"moluscos","sulfitos"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Calamar limpio","amount":300,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo el grifo y reservar.","Cortar calamar limpio en anillas de unos 2 cm.","Picar cebolla y pimiento verde en trozos pequeños.","Picar ajo fino.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla, el ajo y el pimiento verde hasta que estén blandos.","Añadir pimentón dulce y remover 30 segundos para que no se queme.","Añadir tomate triturado y sofreír hasta que pierda el agua, removiendo.","Verter vino blanco y dejar reducir hasta que se evapore el alcohol.","Incorporar las anillas de calamar y saltear a fuego fuerte hasta que estén opacas.","Añadir los garbanzos escurridos y cubrir justo con agua hasta nivelar.","Cocer a fuego medio, tapado, hasta que los sabores se integren y el calamar esté tierno.","Picar perejil fresco fino.","Salpimentar con sal, espolvorear el perejil picado y servir en plato hondo."}', 'Garbanzos guisados con anillas tiernas de calamar en un sofrito oscuro y sabroso.', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Sofríe las verduras y el calamar en una cazuela apta para horno. Añade el resto de ingredientes, cubre y hornea a 180°C durante unos 35-40 minutos, permitiendo que los sabores se integren lentamente."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas con el aceite. Incorpora el calamar, el vino y el resto de ingredientes, y cocina a 100°C, giro inverso, velocidad cuchara, durante 25-30 minutos hasta que el calamar esté tierno."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Sofríe las verduras y el calamar en la olla. Añade los garbanzos, tomate, pimentón y vino. Cierra la olla y cocina a presión durante 10-12 minutos, logrando una textura tierna y sabores concentrados en menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_045', 'Hummus de remolacha y comino', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'all', 300, 10, 28, 17, 2, true, true, '{"sesamo"}', '[{"name":"Garbanzos cocidos","amount":250,"unit":"g"},{"name":"Remolacha cocida","amount":150,"unit":"g"},{"name":"Tahini","amount":25,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos y reservar.","Cortar remolacha cocida en dados.","Pelar ajo y retirar el germen central para que no amargue.","Añadir los garbanzos escurridos, la remolacha, el ajo, tahini, zumo de limón y comino molido al vaso de la batidora.","Triturar a máxima potencia hasta obtener una pasta homogénea, parando para bajar los restos de las paredes si hace falta.","Añadir aceite de oliva en hilo mientras se tritura de nuevo hasta que el hummus quede cremoso y de un magenta uniforme.","Triturar 20 segundos más si la textura sigue densa.","Extender el hummus en un plato hondo formando un surco con el dorso de una cuchara.","Terminar con un chorrito de aceite de oliva y una pizca de comino molido por encima antes de servir."}', 'Crema de garbanzos y remolacha de color magenta intenso, con el aroma cálido del comino.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Introduce todos los ingredientes en el vaso de la Thermomix y tritura a velocidad progresiva hasta obtener una crema suave y homogénea. Raspa las paredes si es necesario para asegurar una textura perfecta."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_046', 'Potaje de vigilia con bacalao y espinacas', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 55, 'normal', 'invierno', 390, 29, 34, 12, 2, true, true, '{"pescado"}', '[{"name":"Alubias blancas cocidas","amount":350,"unit":"g"},{"name":"Bacalao desalado","amount":150,"unit":"g"},{"name":"Espinacas","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"}]'::jsonb, '{"Desmigar bacalao desalado con los dedos en lascas medianas y reservar.","Picar cebolla en dados finos.","Laminar ajo.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir el ajo laminado y sofreír hasta que empiece a dorarse, sin que se queme.","Retirar la olla del fuego e incorporar pimentón dulce; remover rápidamente.","Añadir tomate triturado y volver a fuego medio.","Sofreír el tomate hasta que reduzca y espese.","Incorporar alubias blancas cocidas y cubrir con agua hasta superarlas ligeramente.","Llevar a ebullición a fuego fuerte.","Añadir espinacas, tapar y cocer a fuego suave hasta que el caldo espese ligeramente.","Incorporar el bacalao desmigado y remover con suavidad.","Cocer a fuego suave hasta que el bacalao esté hecho.","Servir en platos hondos, repartiendo las lascas de bacalao por encima."}', 'Potaje de vigilia con alubias blancas, bacalao desmigado y espinacas.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Comienza haciendo el sofrito de cebolla, ajo, tomate y pimentón en una cazuela apta para horno sobre la encimera. Luego, incorpora las alubias, el bacalao y las espinacas, añade un poco de agua si es necesario, cubre y hornea a 180°C durante 45-50 minutos para una cocción lenta y"},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríelos con el aceite. Añade el tomate y el pimentón, cocinando unos minutos más. Incorpora el bacalao en trozos, las alubias y las espinacas, y programa 30-35 minutos a 95°C, giro inverso, velocidad cuchara, para un potaje perfectamente cocinado y emu"},{"appliance":"olla_express","time":20,"difficulty":"normal","prepSummary":"Realiza el sofrito de cebolla, ajo, tomate y pimentón en la olla abierta. Agrega las alubias, el bacalao y las espinacas con un chorrito de agua o caldo. Cierra la olla y cocina a presión durante 5-7 minutos desde que sube la válvula, logrando un potaje con sabores concentrados e"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_047', 'Lentejas estofadas con calabaza', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 365, 17, 55, 8, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Calabaza","amount":250,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":18,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"}]'::jsonb, '{"Escurrir lentejas en un colador y lavar bajo el grifo hasta que el agua salga limpia.","Pelar calabaza y cortar en dados de unos 2 cm.","Pelar y picar cebolla y ajo fino.","Pelar zanahoria y cortar en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el ajo a fuego medio hasta que estén transparentes.","Añadir la zanahoria y sofreír a fuego medio hasta que empiece a ablandarse.","Añadir tomate triturado y comino molido y sofreír hasta que el tomate pierda el agua.","Añadir las lentejas escurridas y los dados de calabaza y remover para que se impregnen del sofrito.","Cubrir con agua hasta superar los ingredientes unos 3 cm y llevar a ebullición a fuego fuerte.","Bajar a fuego suave, tapar y cocer hasta que las lentejas y la calabaza estén tiernas.","Servir bien caliente, con la calabaza ligeramente deshecha en el caldo."}', 'Lentejas guisadas con calabaza que se deshace en el caldo, dulces y reconfortantes.', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Prepara un sofrito en una cazuela apta para horno. Añade las lentejas, calabaza, tomate triturado, comino y suficiente agua o caldo. Tapa y hornea a 160°C durante 90-100 minutos, o hasta que las lentejas estén tiernas y el guiso haya espesado."},{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas con aceite. Incorpora las lentejas, calabaza, tomate, comino y agua/caldo. Cocina a 100°C, giro inverso, velocidad cuchara, durante 45-50 minutos, o hasta que las lentejas estén en su punto."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Realiza el sofrito de cebolla, zanahoria y ajo en la olla. Agrega las lentejas, calabaza, tomate, comino y agua/caldo. Cierra la olla y cocina a presión durante 10-15 minutos desde que sube la válvula. Deja despresurizar antes de servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_048', 'Alubias pintas con costillas de cerdo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 90, 'normal', 'invierno', 640, 34, 45, 32, 2, true, true, '{}', '[{"name":"Alubias pintas","amount":200,"unit":"g"},{"name":"Costillas de cerdo","amount":300,"unit":"g"},{"name":"Cebolla","amount":90,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Hoja de laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Poner alubias pintas en un bol grande con agua fría abundante y dejar en remojo un mínimo de 8 horas.","Escurrir las alubias pintas y reservar.","Cortar costillas de cerdo en piezas de unos 4 cm si no vienen ya troceadas.","Picar cebolla y pimiento verde en dados pequeños.","Picar ajo fino.","Calentar aceite de oliva en una olla a fuego fuerte hasta que esté bien caliente.","Dorar las costillas de cerdo por todos los lados hasta que estén bien selladas, unos 6 min.","Retirar las costillas doradas de la olla y reservar.","Sofreír la cebolla picada, el pimiento verde picado y el ajo picado en el mismo aceite a fuego medio hasta que estén blandos.","Retirar la olla del fuego y añadir pimentón dulce; remover para que no se queme.","Volver la olla al fuego y añadir tomate triturado; sofreír a fuego medio hasta que reduzca ligeramente.","Incorporar las alubias pintas escurridas, las costillas reservadas y hoja de laurel; remover para integrar.","Cubrir con agua fría hasta superar los ingredientes unos 4 cm y llevar a ebullición a fuego fuerte.","Tapar la olla, bajar el fuego al mínimo y cocer hasta que las alubias y las costillas estén tiernas, unos 65 min.","Añadir agua caliente si el caldo reduce demasiado durante la cocción para que los ingredientes queden cubiertos.","Retirar la hoja de laurel del guiso.","Servir el guiso bien caliente y espeso en platos hondos."}', 'Guiso espeso de alubias pintas y costilla de cerdo, con la carne deshaciéndose de tierna.', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Prepara un sofrito con las verduras y dora las costillas en una cazuela apta para horno. Añade las alubias (previamente remojadas) y el caldo, y cocina a 160°C durante 2 horas, removiendo ocasionalmente, hasta que las alubias estén tiernas y el guiso ligado."},{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Realiza el sofrito en el vaso, luego incorpora las costillas y rehoga. Añade las alubias (remojadas) y el caldo, y cocina a 100°C, giro inverso, velocidad cuchara, durante 90-100 minutos, hasta que las alubias estén en su punto."},{"appliance":"olla_express","time":50,"difficulty":"facil","prepSummary":"Sofríe las verduras y dora las costillas en la olla. Incorpora las alubias (remojadas) y el caldo. Cierra la olla y cocina a presión durante 25-30 minutos desde que sube la válvula, logrando un guiso tierno y rápido."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_049', 'Ensalada tibia de lentejas y salmón ahumado', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 380, 27, 32, 16, 2, false, false, '{"pescado"}', '[{"name":"Lentejas cocidas","amount":300,"unit":"g"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de manzana","amount":15,"unit":"ml"}]'::jsonb, '{"Calentar lentejas cocidas en un cazo a fuego suave hasta que estén templadas.","Picar cebolleta muy fina.","Picar eneldo fresco fino.","Cortar salmón ahumado en lascas de bocado.","Mezclar aceite de oliva y vinagre de manzana en un bol pequeño hasta integrar el aliño.","Repartir rúcula en la base de los platos.","Añadir las lentejas templadas sobre la rúcula y verter el aliño por encima.","Repartir el salmón, la cebolleta picada y el eneldo sobre las lentejas.","Servir enseguida mientras las lentejas están templadas."}', 'Lentejas templadas con salmón ahumado, cebolleta y eneldo sobre un fondo de rúcula.', '[{"appliance":"thermomix","time":12,"difficulty":"facil","prepSummary":"Pica la cebolleta y emulsiona el aderezo en el vaso. Luego, calienta las lentejas cocidas suavemente a 90°C durante unos minutos para que queden tibias y listas para mezclar."},{"appliance":"microondas","time":5,"difficulty":"facil","prepSummary":"Calienta las lentejas cocidas en un recipiente apto para microondas durante 2-3 minutos a potencia media-alta, removiendo a mitad, hasta que estén tibias. Luego, mezcla con el resto de ingredientes."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('legumbres_050', 'Garbanzos fritos crujientes especiados', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 320, 12, 30, 17, 2, true, false, '{}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Pimentón picante","amount":4,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos con un colador y secarlos bien con papel de cocina hasta que no quede humedad superficial.","Calentar aceite de oliva en sartén amplia a fuego fuerte hasta que esté bien caliente.","Añadir los garbanzos en una sola capa sin moverlos hasta que se doren por debajo.","Saltear los garbanzos removiendo con frecuencia hasta que estén dorados y crujientes por todos los lados.","Retirar los garbanzos de la sartén y escurrirlos sobre papel de cocina.","Espolvorear pimentón picante, comino molido y ajo en polvo sobre los garbanzos aún calientes.","Remover los garbanzos para que las especias se adhieran bien por todos los lados.","Servir los garbanzos templados en un bol."}', 'Garbanzos dorados y crujientes por fuera, especiados para picotear recién hechos.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Mezcla los garbanzos con el aceite y las especias. Cocina en la airfryer a 190°C durante 15-20 minutos, agitando la cesta a mitad para asegurar un dorado y crujido uniforme."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Extiende los garbanzos sazonados con aceite y especias en una bandeja de horno. Hornea a 200°C durante 20-25 minutos, removiendo una o dos veces para que queden bien crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
