insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('legumbres_051', 'Judías verdes con garbanzos y jamón', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 340, 20, 32, 14, 2, true, true, '{}', '[{"name":"Judías verdes","amount":300,"unit":"g"},{"name":"Garbanzos cocidos","amount":250,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Tomate triturado","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Despuntar judías verdes, retirar los hilos si los tienen y cortar en trozos de unos 4 cm.","Picar cebolla y ajo finos.","Cortar jamón serrano en taquitos pequeños.","Llevar a ebullición agua con sal en un cazo y cocer las judías verdes hasta que estén tiernas pero firmes.","Escurrir las judías verdes y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y el ajo picados a fuego medio hasta que estén blandos.","Añadir el jamón serrano en taquitos y saltear hasta que suelte su aroma.","Añadir tomate triturado y sofreír a fuego medio.","Añadir las judías verdes escurridas y garbanzos cocidos y saltear todo junto a fuego medio-fuerte.","Servir bien caliente, con cuidado al rectificar la sal ya que el jamón aporta salinidad."}', 'Judías verdes salteadas con garbanzos y virutas de jamón serrano.', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Asa las judías verdes, cebolla y ajo con aceite en una bandeja a 190°C durante 20-25 minutos. Luego, incorpora los garbanzos, jamón y tomate triturado, y cocina 10 minutos más para que los sabores se integren y el tomate reduzca ligeramente."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Añade las judías verdes y un poco de agua, cocinando a 100°C o Varoma. Finalmente, incorpora los garbanzos, jamón y tomate triturado, y cocina unos minutos más a velocidad cuchara para integrar los sabores."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, el ajo y el jamón en la olla. Añade las judías verdes, garbanzos y tomate triturado con un chorrito de agua. Cierra la olla y cocina 5-7 minutos desde que sube la presión. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_052', 'Alubiada con butifarra y costilla', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 100, 'normal', 'invierno', 680, 36, 48, 36, 2, true, true, '{}', '[{"name":"Alubias blancas","amount":220,"unit":"g"},{"name":"Butifarra","amount":150,"unit":"g"},{"name":"Costilla de cerdo","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Hoja de laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Dejar alubias blancas en remojo con agua fría abundante durante al menos 8 horas o toda la noche.","Escurrir las alubias blancas y reservar.","Picar cebolla en dados pequeños.","Picar zanahoria en dados pequeños.","Picar ajo fino.","Calentar aceite de oliva en una olla a fuego fuerte.","Dorar costilla de cerdo por todos sus lados hasta que esté bien sellada, unos 5 min. Reservar.","Sofreír la cebolla picada, la zanahoria picada y el ajo picado en el mismo aceite a fuego medio.","Continuar sofriendo hasta que la verdura esté blanda, unos 6 min.","Añadir tomate triturado y sofreír a fuego medio hasta que se evapore el líquido, unos 3 min.","Incorporar las alubias escurridas, la costilla reservada y hoja de laurel a la olla.","Cubrir con agua fría hasta superar los ingredientes unos 4 cm y llevar a ebullición a fuego fuerte.","Retirar la espuma que pueda formarse en la superficie con una cuchara.","Tapar la olla, bajar a fuego suave y cocer hasta que las alubias empiecen a estar tiernas, unos 50 min.","Añadir butifarra entera y continuar la cocción a fuego suave hasta que las alubias y la carne estén tiernas.","Cocer tapado a fuego suave hasta que todo esté tierno y el caldo haya espesado, unos 20 min.","Retirar la hoja de laurel y desechar.","Cortar la butifarra en rodajas y volver a incorporar a la olla.","Servir el guiso bien caliente y espeso en platos hondos."}', 'Guiso catalán de alubias con butifarra y costilla de cerdo, generoso y de cuchara.', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora la carne en una cazuela apta para horno. Añade las alubias, el tomate y el laurel, cubre con caldo y hornea a 160°C durante 90-120 minutos hasta que las alubias estén tiernas y los sabores se hayan integrado."},{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Trocea las verduras y sofríelas. Incorpora la butifarra y la costilla troceadas para dorar ligeramente. Añade las alubias, tomate, laurel y caldo, y cocina a 100°C, velocidad cuchara, giro inverso, durante 80-90 minutos, hasta que las alubias estén tiernas."},{"appliance":"olla_express","time":60,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora la carne en la olla. Añade las alubias (previamente remojadas), tomate, laurel y caldo. Cierra la olla y cocina a presión alta durante 25-30 minutos, dejando despresurizar de forma natural para un resultado tierno y sabroso."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_053', 'Garbanzos con pulpo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 380, 28, 34, 12, 2, true, true, '{"moluscos"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Pulpo cocido","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pimentón dulce","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Picar cebolla y ajo en dados pequeños.","Cortar pulpo cocido en rodajas de un dedo de grosor.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla y el ajo picados a fuego medio hasta que estén transparentes.","Retirar la cazuela del fuego y añadir pimentón dulce.","Remover rápido el pimentón para que no se queme.","Incorporar garbanzos cocidos con un chorrito de agua y remover para integrar con el sofrito.","Cocer a fuego suave hasta que los garbanzos absorban el sabor del pimentón.","Añadir las rodajas de pulpo y calentar a fuego suave hasta que estén calientes, sin que hierva fuerte.","Picar perejil fresco fino.","Repartir los garbanzos y el pulpo en platos hondos.","Rociar con el resto del aceite de oliva en crudo y espolvorear con el perejil picado."}', 'Garbanzos guisados en un suave sofrito de pimentón con rodajas de pulpo tierno.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"Sofreír la cebolla y el ajo aparte. Mezclar con los garbanzos, pulpo, pimentón y aceite, y cocinar en la airfryer a 180-190°C durante 15-20 minutos, removiendo a mitad, para calentar y dorar ligeramente."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Sofreír la cebolla y el ajo en una fuente apta para horno. Añadir los garbanzos, pulpo, pimentón y aceite, mezclando bien, y hornear a 180°C durante 30-35 minutos para que los sabores se integren."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Picar cebolla y ajo, y sofreír con aceite. Incorporar los garbanzos, pulpo y pimentón, y cocinar a temperatura y velocidad bajas (ej. 100°C, velocidad cuchara, 15-20 min) para integrar los sabores."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_054', 'Lentejas con morcilla y manzana', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'facil', 'all', 560, 24, 50, 28, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Morcilla de Burgos","amount":150,"unit":"g"},{"name":"Manzana","amount":120,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"}]'::jsonb, '{"Lavar lentejas bajo el grifo en un colador hasta que el agua salga limpia.","Escurrir las lentejas y reservar.","Picar cebolla en dados pequeños.","Cortar zanahoria en dados pequeños.","Pelar manzana y cortarla en dados algo más grandes que la cebolla y la zanahoria.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y la zanahoria a fuego medio hasta que estén blandas.","Retirar la olla del fuego y añadir pimentón dulce.","Remover el pimentón con la verdura hasta integrarlo y volver a poner la olla al fuego.","Añadir las lentejas escurridas y cubrir con agua hasta superarlas unos 3 cm.","Llevar a ebullición a fuego fuerte.","Bajar el fuego a suave, tapar la olla y cocer hasta que las lentejas estén casi tiernas.","Retirar la piel de morcilla de burgos y desmenuzarla en trozos.","Añadir la morcilla desmenuzada y la manzana en dados a la olla.","Cocer sin tapar a fuego suave hasta que la manzana esté tierna y el guiso haya espesado.","Retirar la olla del fuego y dejar reposar el guiso.","Servir las lentejas bien calientes."}', 'Lentejas guisadas con morcilla desmenuzada y dados de manzana, un contraste dulce y sabroso.', '[{"appliance":"horno","time":80,"difficulty":"normal","prepSummary":"Prepara un sofrito con la cebolla y zanahoria en una cazuela apta para horno. Añade las lentejas, el pimentón, agua o caldo y hornea tapado a 180°C durante 60-75 minutos. Incorpora la morcilla y la manzana los últimos 15 minutos para que se integren bien."},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Sofríe la cebolla y zanahoria picadas en el vaso con aceite. Añade las lentejas, agua o caldo, el pimentón y programa 35-40 minutos, 100°C, giro inverso, velocidad cuchara. Incorpora la morcilla y la manzana troceadas al final para que se cocinen brevemente."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Haz un sofrito con la cebolla y zanahoria en la olla. Añade las lentejas, el pimentón y el agua o caldo. Cierra y cocina a presión durante 12-15 minutos. Una vez despresurizada, incorpora la morcilla y la manzana y cocina a fuego suave unos minutos más para que se integren los sa"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_055', 'Potaje de habichuelas con conejo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 75, 'normal', 'invierno', 480, 30, 42, 18, 2, true, true, '{}', '[{"name":"Judías blancas","amount":200,"unit":"g"},{"name":"Conejo troceado","amount":300,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón dulce","amount":4,"unit":"g"},{"name":"Hoja de laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Poner judías blancas en un bol grande cubiertas con agua fría abundante y dejar en remojo un mínimo de 8 horas.","Escurrir las judías blancas remojadas y reservar.","Picar cebolla en dados pequeños.","Picar pimiento rojo en dados pequeños.","Picar ajo fino.","Calentar aceite de oliva en una olla a fuego fuerte hasta que esté bien caliente.","Dorar conejo troceado por todos los lados hasta que esté bien sellado, unos 6 min.","Retirar el conejo dorado de la olla y reservar.","Sofreír la cebolla picada, el pimiento picado y el ajo picado en el mismo aceite a fuego medio hasta que estén blandos.","Retirar la olla del fuego, añadir pimentón dulce y remover para que no se queme.","Volver la olla al fuego medio, añadir tomate triturado y sofreír hasta que el tomate pierda el agua y se integre.","Añadir las judías escurridas, el conejo reservado y hoja de laurel a la olla.","Cubrir con agua fría hasta superar los ingredientes unos 4 cm y llevar a ebullición a fuego fuerte.","Tapar la olla, bajar a fuego suave y cocer hasta que las judías y el conejo estén tiernos, unos 50 min.","Añadir agua caliente si el caldo reduce demasiado durante la cocción.","Retirar la hoja de laurel del potaje antes de servir.","Servir el potaje bien caliente en cuencos hondos, con el caldo espeso."}', 'Potaje suave de judías blancas con conejo, de caldo espeso y sabroso.', '[{"appliance":"horno","time":90,"difficulty":"normal","prepSummary":"Se sofríen las verduras y se dora el conejo en una cazuela apta para horno. Se añaden las judías (previamente en remojo o cocidas), el tomate, pimentón, laurel y el líquido. Se cocina a fuego lento en el horno a unos 160-170°C durante 90 minutos, permitiendo que los sabores se in"},{"appliance":"thermomix","time":75,"difficulty":"normal","prepSummary":"Se prepara el sofrito en el vaso de la Thermomix. Se incorpora el conejo troceado y se dora. Luego se añaden las judías (previamente en remojo o cocidas), el tomate, pimentón, laurel y el líquido, cocinando a 100°C, velocidad cuchara, durante 75 minutos para un guiso homogéneo y "},{"appliance":"olla_express","time":45,"difficulty":"normal","prepSummary":"Se sofríen las verduras y se dora el conejo en la olla abierta. Se añaden las judías (previamente en remojo), tomate, pimentón, laurel y el líquido. Se cierra la olla y se cocina a presión durante 25-30 minutos, logrando un guiso tierno y con sabores concentrados en mucho menos t"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_056', 'Ensalada de garbanzos asados crujientes con feta', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 380, 16, 32, 20, 2, true, true, '{"lactosa"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Queso feta","amount":80,"unit":"g"},{"name":"Tomates cherry","amount":100,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Cebolla roja","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Escurrir garbanzos cocidos y secarlos bien con papel de cocina.","Extender los garbanzos en una bandeja de horno.","Añadir aceite de oliva, comino molido y sal sobre los garbanzos y mezclar hasta que queden bien cubiertos.","Hornear los garbanzos 20 min hasta que estén dorados y crujientes, removiendo a mitad de cocción.","Cortar tomates cherry por la mitad.","Cortar pepino en dados pequeños.","Laminar cebolla roja en juliana fina.","Desmenuzar queso feta en trozos irregulares con los dedos o un tenedor.","Mezclar en un bol los tomates cherry, el pepino y la cebolla roja.","Aliñar la mezcla con el resto del aceite de oliva, zumo de limón y orégano seco.","Retirar los garbanzos del horno cuando estén crujientes y dejarlos templar 2 min.","Incorporar los garbanzos templados al bol y mezclar con suavidad.","Repartir el queso feta desmenuzado por encima y servir de inmediato."}', 'Garbanzos asados hasta quedar crujientes sobre una ensalada fresca con feta desmenuzado.', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Los garbanzos se mezclan con aceite y especias, se extienden en una bandeja y se asan en el horno precalentado a 200°C durante 25-30 minutos, removiendo a mitad, hasta que estén dorados y crujientes. Luego se mezclan con el resto de ingredientes frescos."},{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Para unos garbanzos extra crujientes en menos tiempo, cocínalos en la airfryer a 190°C durante 15-20 minutos, agitándolos cada 5 minutos. Es clave no sobrecargar la cesta para asegurar una cocción uniforme y crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_057', 'Alubias negras con arroz estilo cubano', 'legumbres', 'legumbre', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 480, 16, 82, 10, 2, true, true, '{}', '[{"name":"Alubias negras cocidas","amount":300,"unit":"g"},{"name":"Arroz blanco","amount":160,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Hoja de laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Llevar a ebullición agua con sal en un cazo a fuego fuerte.","Añadir arroz blanco y cocer a fuego medio hasta que esté tierno.","Picar cebolla en dados pequeños.","Picar pimiento verde en dados pequeños.","Picar ajo fino.","Escurrir el arroz cocido y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada y el pimiento picado a fuego medio hasta que estén blandos.","Añadir el ajo picado y comino molido y sofreír hasta que suelten aroma.","Incorporar alubias negras cocidas y hoja de laurel a la sartén.","Cocer a fuego suave hasta que el conjunto espese ligeramente.","Aplastar ligeramente algunas alubias con el dorso de una cuchara para espesar la salsa.","Retirar la hoja de laurel de las alubias.","Servir las alubias negras junto al arroz blanco, uno al lado del otro en el plato."}', 'Alubias negras guisadas al estilo cubano, servidas junto a arroz blanco suelto.', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Sofríe las verduras en una cazuela apta para horno, añade las alubias cocidas, especias y un poco de agua o caldo. Hornea a 180°C durante 35-40 minutos para que los sabores se integren. El arroz se cocina aparte en una olla."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Pica las verduras y sofríelas con aceite. Añade las alubias cocidas, especias y agua, cocinando a 100°C, velocidad cuchara, durante 20-25 minutos. Puedes cocinar el arroz en el cestillo al mismo tiempo para una cocción simultánea y eficiente."},{"appliance":"olla_express","time":40,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla express, añade las alubias cocidas, especias y un poco de agua o caldo. Cierra la olla y cocina a presión durante 7-10 minutos para que los sabores se concentren rápidamente. El arroz se prepara en una olla aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_058', 'Garbanzos con curry y espinacas', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 420, 16, 40, 22, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Espinacas","amount":150,"unit":"g"},{"name":"Leche de coco","amount":150,"unit":"ml"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Curry en polvo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Tomate triturado","amount":60,"unit":"ml"}]'::jsonb, '{"Picar cebolla en dados finos.","Picar ajo fino.","Rallar jengibre fresco fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté transparente.","Añadir el ajo picado y el jengibre rallado y sofreír hasta que suelten aroma.","Añadir curry en polvo y remover hasta que tueste ligeramente sin quemarse.","Añadir tomate triturado y sofreír hasta que reduzca ligeramente.","Incorporar garbanzos cocidos y leche de coco y remover hasta mezclar bien.","Llevar a ebullición suave a fuego medio-bajo.","Cocer a fuego medio-bajo hasta que el guiso espese y los sabores se integren.","Añadir espinacas y cocer hasta que se ablanden.","Servir bien caliente."}', 'Garbanzos en un guiso de curry cremoso con espinacas, rápido y de sabor potente.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica la cebolla, ajo y jengibre unos segundos. Sofríe con aceite 5 min a 120°C. Añade el resto de ingredientes (excepto espinacas), programa 15 min a 100°C, giro inverso, velocidad cuchara. Incorpora las espinacas los últimos 2-3 min."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y jengibre en la olla abierta con aceite. Añade el curry, tomate, leche de coco y garbanzos. Cierra la olla y cocina a presión mínima durante 3-5 minutos. Libera la presión, incorpora las espinacas y cocina un par de minutos más hasta que se integren."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_059', 'Lentejas con salchichas y pimentón', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 520, 24, 48, 24, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Salchichas frescas","amount":150,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón dulce","amount":6,"unit":"g"}]'::jsonb, '{"Lavar lentejas en un colador bajo el grifo hasta que el agua salga limpia y escurrir.","Picar cebolla y ajo fino.","Cortar zanahoria en dados pequeños.","Cortar salchichas frescas en rodajas de un dedo de grosor.","Calentar aceite de oliva en una olla a fuego medio-fuerte.","Dorar las salchichas en la olla hasta que estén tostadas por fuera, unos 3 min, y reservar.","Sofreír la cebolla, la zanahoria y el ajo en el mismo aceite a fuego medio hasta que estén blandos.","Retirar la olla del fuego y añadir pimentón dulce removiendo rápido para que no se queme.","Incorporar tomate triturado y sofreír a fuego medio hasta que reduzca y se integre.","Añadir las lentejas escurridas y cubrir con agua hasta superarlas unos 3 cm.","Llevar la olla a ebullición a fuego fuerte.","Tapar, bajar el fuego al mínimo y cocer hasta que las lentejas estén casi tiernas.","Incorporar las salchichas reservadas y cocer a fuego suave hasta que las lentejas estén completamente tiernas.","Servir en platos hondos bien caliente."}', 'Lentejas guisadas con salchichas y el rojo del pimentón, un plato de toda la vida.', '[{"appliance":"horno","time":80,"difficulty":"normal","prepSummary":"Sofríe la cebolla, zanahoria y ajo en una cazuela apta para horno. Añade las salchichas para dorarlas ligeramente. Incorpora las lentejas, tomate, pimentón y agua o caldo, y cocina tapado en el horno precalentado a 180°C durante 60-70 minutos, o hasta que las lentejas estén tiern"},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Trocea la cebolla, zanahoria y ajo y sofríe con aceite. Añade las salchichas troceadas y sofríe unos minutos más. Incorpora las lentejas, tomate, pimentón y agua, y cocina a 100°C, giro inverso, velocidad cuchara, durante 35-40 minutos, o hasta que las lentejas estén a tu gusto."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Sofríe la cebolla, zanahoria y ajo en la olla express. Añade las salchichas para dorarlas. Incorpora las lentejas, tomate, pimentón y agua o caldo. Cierra la olla y cocina a presión durante 15-20 minutos desde que sube la válvula, dejando despresurizar antes de abrir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_060', 'Hummus de calabaza asada', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 320, 9, 32, 17, 2, true, true, '{"sesamo"}', '[{"name":"Garbanzos cocidos","amount":250,"unit":"g"},{"name":"Calabaza","amount":200,"unit":"g"},{"name":"Tahini","amount":20,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar calabaza y cortar en dados de 2 cm.","Pelar ajo y reservar.","Disponer los dados de calabaza en una bandeja de horno en una sola capa.","Regar la calabaza con aceite de oliva y hornear hasta que esté blanda y ligeramente dorada.","Retirar la bandeja del horno y dejar templar la calabaza asada.","Añadir garbanzos cocidos, la calabaza templada, tahini, zumo de limón, el ajo y comino molido a un vaso batidor.","Triturar a máxima potencia hasta obtener una crema homogénea.","Añadir el resto del aceite de oliva en hilo fino mientras se tritura hasta que la crema quede suave y cremosa.","Extender el hummus en un plato hondo y terminar con aceite de oliva por encima."}', 'Hummus suave con el dulzor de la calabaza asada, sorprendente y cremoso.', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Asa la calabaza y el ajo troceados con un chorrito de aceite de oliva durante 25-30 minutos hasta que estén tiernos y ligeramente caramelizados. Luego, tritura todos los ingredientes hasta obtener un hummus suave."},{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Corta la calabaza en cubos pequeños y ásala junto al ajo en la airfryer a 190°C durante 15-20 minutos, removiendo a mitad, hasta que esté tierna y dorada. Después, procesa todos los ingredientes hasta conseguir una textura cremosa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('legumbres_061', 'Alubias blancas con setas y romero', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 55, 'normal', 'invierno', 380, 16, 40, 16, 2, true, true, '{"sulfitos","lactosa"}', '[{"name":"Alubias blancas cocidas","amount":350,"unit":"g"},{"name":"Setas variadas","amount":200,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Romero fresco","amount":3,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Nata para cocinar","amount":40,"unit":"ml"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo y cortar en trozos las que sean grandes.","Picar cebolla en dados finos.","Picar ajo en dados finos.","Picar romero fresco fino.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté transparente.","Añadir el ajo picado y las setas troceadas y saltear a fuego fuerte hasta que las setas se doren.","Añadir el romero picado y vino blanco, subir el fuego y cocer hasta que el alcohol se evapore.","Incorporar alubias blancas cocidas y remover para integrar con las setas.","Cocer a fuego suave, tapado, hasta que los sabores se integren.","Añadir nata para cocinar y remover con suavidad.","Cocer a fuego suave hasta que la salsa esté cremosa, sin que llegue a hervir fuerte.","Servir bien caliente."}', 'Alubias blancas en un guiso cremoso con setas salteadas y aroma a romero fresco.', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Sofríe ligeramente la cebolla y el ajo en una sartén apta para horno o directamente en el horno con las setas y romero a 180°C durante 20-25 min. Luego, añade las alubias, el vino y la nata, y hornea otros 15-20 min para que los sabores se integren."},{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Añade las setas y el romero, cocina a temperatura Varoma. Incorpora las alubias, el vino blanco y la nata, y cocina a 90°C con giro inverso hasta que la salsa espese y los sabores se integren."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla, el ajo y las setas con aceite y romero en la olla abierta. Añade las alubias, el vino blanco y la nata. Cocina a fuego medio-bajo durante 10-15 minutos, removiendo ocasionalmente, para que los sabores se integren y la salsa espese ligeramente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_062', 'Garbanzos con chorizo y huevo frito', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 580, 28, 40, 34, 2, true, false, '{"huevo"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Chorizo","amount":100,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Pimentón dulce","amount":4,"unit":"g"}]'::jsonb, '{"Picar cebolla y ajo en dados finos.","Cortar chorizo en rodajas de unos 5 mm.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y el ajo picados hasta que estén blandos.","Añadir el chorizo en rodajas y saltear hasta que suelte su grasa y aroma.","Retirar la sartén del fuego y añadir pimentón dulce; remover rápido.","Volver al fuego y añadir tomate triturado; sofreír a fuego medio.","Añadir garbanzos cocidos con un chorrito de agua; cocer a fuego medio removiendo de vez en cuando.","Calentar el resto del aceite de oliva en otra sartén a fuego fuerte.","Freír huevo uno a uno hasta que la clara esté cuajada y el borde crujiente, con la yema jugosa.","Repartir los garbanzos con chorizo en 2 platos y coronar cada uno con un huevo frito."}', 'Garbanzos guisados con chorizo, con la puntilla crujiente de un huevo frito encima.', '[{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y chorizo en la olla abierta. Añade el tomate, garbanzos y pimentón. Cierra la olla y cocina a presión 5-7 minutos para integrar sabores. Sirve con un huevo frito recién hecho en una sartén aparte."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea y sofríe la cebolla y el ajo en el vaso. Añade el chorizo troceado y sofríe. Incorpora el tomate, garbanzos y pimentón, cocinando a 100°C/Vel. Cuchara/Giro inverso durante 15-20 minutos. Sirve con un huevo frito hecho aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_063', 'Cocido madrileño en tres vuelcos', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 150, 'facil', 'invierno', 610, 37, 38, 31, 4, true, true, '{"gluten"}', '[{"name":"Garbanzos","amount":500,"unit":"g"},{"name":"Morcillo de ternera","amount":300,"unit":"g"},{"name":"Pollo","amount":240,"unit":"g"},{"name":"Tocino","amount":100,"unit":"g"},{"name":"Hueso de jamón","amount":100,"unit":"g"},{"name":"Chorizo","amount":120,"unit":"g"},{"name":"Morcilla","amount":100,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Zanahoria","amount":200,"unit":"g"},{"name":"Repollo","amount":300,"unit":"g"},{"name":"Fideos finos","amount":80,"unit":"g"}]'::jsonb, '{"Cubrir garbanzos con agua fría abundante y dejar en remojo un mínimo de 12 horas.","Pelar patata y zanahoria y cortar en trozos grandes.","Cortar repollo en cuartos.","Escurrir los garbanzos remojados.","Colocar morcillo de ternera, pollo, tocino y hueso de jamón en una olla grande y cubrir con agua fría abundante.","Llevar a ebullición a fuego fuerte.","Espumar la superficie con una espumadera hasta que el caldo salga limpio.","Añadir los garbanzos escurridos y la zanahoria troceada, bajar a fuego suave y tapar.","Cocer tapado a fuego suave durante 60 min.","Incorporar la patata troceada, el repollo y chorizo entero; tapar y subir ligeramente el fuego.","Cocer tapado a fuego suave hasta que la patata esté tierna, unos 20 min.","Añadir morcilla entera y cocer tapado 10 min más para que no se deshaga.","Retirar la morcilla, el chorizo, el morcillo, el pollo y el tocino de la olla y reservar en una fuente tapada.","Retirar los garbanzos, la patata, la zanahoria y el repollo con una espumadera y reservar en una fuente aparte.","Colar el caldo sobrante y llevar a ebullición en un cazo a fuego fuerte.","Cocer fideos finos en el caldo hirviendo hasta que estén tiernos, unos 3 min.","Servir la sopa con los fideos como primer vuelco en soperas o platos hondos.","Servir como segundo vuelco los garbanzos con la zanahoria, la patata y el repollo bien escurridos en una fuente.","Trinchar el morcillo, el pollo y el tocino en porciones y cortar el chorizo y la morcilla en rodajas.","Servir las carnes y embutidos como tercer vuelco en una fuente aparte."}', 'El cocido de siempre servido en sus tres vuelcos: sopa, garbanzos con verdura y carnes, la comida que resuelve varios días.', '[{"appliance":"olla_express","time":120,"difficulty":"facil","prepSummary":"Ideal para acortar el tiempo de cocción de garbanzos y carnes, logrando un caldo sabroso y concentrado. Cocina los ingredientes principales a presión y luego añade las verduras y fideos para el punto final."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_064', 'Sopa de cocido con fideos finos', 'legumbres', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'invierno', 180, 6, 28, 5, 2, true, true, '{"gluten"}', '[{"name":"Caldo de cocido","amount":600,"unit":"ml"},{"name":"Fideos finos","amount":80,"unit":"g"},{"name":"Perejil fresco","amount":3,"unit":"g"}]'::jsonb, '{"Colar caldo de cocido sobre la olla para retirar restos de verdura o grasa suelta.","Llevar el caldo a ebullición a fuego fuerte.","Picar perejil fresco fino y reservar.","Añadir fideos finos cuando el caldo rompa a hervir y remover para que no se peguen.","Cocer a fuego medio hasta que los fideos estén sueltos y tiernos.","Retirar del fuego y dejar reposar.","Servir en tazones hondos y espolvorear el perejil picado por encima."}', 'El primer vuelco del cocido servido solo: caldo dorado con fideos finos recién cocidos.', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Vierte el caldo en el vaso y calienta 10 min/100°C/vel 1. Añade los fideos y cocina 8-10 min/100°C/vel 1, o el tiempo indicado en el paquete, hasta que estén al dente. Sirve con perejil fresco."},{"appliance":"microondas","time":10,"difficulty":"facil","prepSummary":"Calienta el caldo en un recipiente apto para microondas a máxima potencia durante 5-7 minutos hasta que hierva. Incorpora los fideos y cocina 3-5 minutos más, o hasta que estén tiernos, removiendo a mitad de cocción. Finaliza con perejil."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_065', 'Ropa vieja de cocido con garbanzos', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 480, 32, 30, 24, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":250,"unit":"g"},{"name":"Carne de cocido variada","amount":250,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Pimentón dulce","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Desmenuzar carne de cocido variada con las manos o dos tenedores en tiras finas.","Picar cebolla y pimiento verde en dados pequeños.","Picar ajo fino.","Calentar aceite de oliva en una sartén amplia a fuego medio.","Sofreír la cebolla y el pimiento verde hasta que estén blandos.","Añadir el ajo y sofreír hasta que desprenda aroma.","Retirar la sartén del fuego y añadir pimentón dulce.","Remover el pimentón con la verdura hasta que se integre.","Volver la sartén al fuego y añadir tomate triturado.","Sofreír el tomate a fuego medio hasta que pierda el agua y se oscurezca.","Añadir la carne desmenuzada y saltear a fuego fuerte hasta que se dore por los bordes.","Incorporar garbanzos cocidos y saltear hasta que estén bien calientes y ligados con la salsa.","Servir bien caliente directamente desde la sartén."}', 'La carne y el garbanzo sobrantes del cocido, salteados y dorados en la sartén del día siguiente.', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Prepara un sofrito con las verduras en una sartén. Incorpora la carne, garbanzos, tomate y pimentón, mezcla bien y pasa a una fuente de horno. Hornea a 180°C durante 15-20 minutos para que los sabores se integren y se caliente uniformemente."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas con aceite. Añade la carne desmenuzada, garbanzos, tomate y pimentón. Cocina a temperatura Varoma, giro inverso, velocidad cuchara durante 10-12 minutos para integrar los sabores."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, pimiento y ajo en la olla express abierta con aceite. Añade el tomate, pimentón, carne y garbanzos. Tapa y cocina a fuego medio durante 5-7 minutos sin presión para que los sabores se mezclen bien."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_066', 'Puchero andaluz con hierbabuena', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 100, 'facil', 'invierno', 520, 28, 42, 24, 4, true, true, '{}', '[{"name":"Garbanzos","amount":400,"unit":"g"},{"name":"Pollo troceado","amount":400,"unit":"g"},{"name":"Tocino","amount":80,"unit":"g"},{"name":"Chorizo","amount":100,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Judías verdes","amount":150,"unit":"g"},{"name":"Calabaza","amount":200,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Hierbabuena fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Poner garbanzos en remojo en un bol grande cubiertos con agua fría abundante un mínimo de 12 h.","Escurrir los garbanzos y reservar.","Pelar patata y calabaza y cortar ambas en trozos grandes.","Despuntar judías verdes y cortar en trozos de unos 4 cm.","Picar cebolla fina.","Picar tomate en trozos pequeños.","Colocar pollo troceado y tocino en una olla grande y cubrir con agua fría abundante.","Llevar a ebullición a fuego fuerte.","Espumar la superficie con una espumadera hasta que el caldo salga limpio.","Añadir la cebolla picada, el tomate picado, aceite de oliva y los garbanzos escurridos.","Bajar el fuego a suave, tapar la olla y cocer 45 min.","Incorporar la patata, las judías verdes, la calabaza y chorizo entero.","Tapar de nuevo y cocer a fuego suave 25 min hasta que la patata y los garbanzos estén tiernos.","Picar hierbabuena fresca fina.","Añadir la hierbabuena picada al puchero y cocer 5 min más a fuego suave.","Retirar el chorizo y el tocino de la olla y cortar ambos en rodajas.","Devolver el chorizo y el tocino en rodajas a la olla y mezclar con el resto.","Servir bien caliente repartiendo caldo, garbanzos, verduras y carne en cada plato."}', 'Puchero de garbanzos y pollo perfumado con hierbabuena fresca, distinto del cocido del norte.', '[{"appliance":"horno","time":120,"difficulty":"facil","prepSummary":"Sofríe las carnes y verduras en una olla apta para horno, añade los garbanzos y el resto de ingredientes con agua o caldo. Cocina tapado a 160°C durante 2 horas para un puchero tierno y sabroso."},{"appliance":"thermomix","time":90,"difficulty":"facil","prepSummary":"Trocea y sofríe las verduras y carnes en el vaso. Incorpora los garbanzos, patata, judías, calabaza y líquido. Programa 90 min, 100°C, giro inverso, velocidad cuchara, para un guiso homogéneo."},{"appliance":"olla_express","time":45,"difficulty":"facil","prepSummary":"Dora las carnes y sofríe las verduras en la olla. Añade los garbanzos (previamente remojados), patata, judías, calabaza y agua. Cierra y cocina 30-35 minutos desde que sube la válvula para un puchero rápido y tierno."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_067', 'Buddha bowl de garbanzos asados y tahini', 'legumbres', 'legumbre', 'quinoa', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 480, 18, 46, 24, 2, true, false, '{"sesamo"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Quinoa","amount":100,"unit":"g"},{"name":"Boniato","amount":200,"unit":"g"},{"name":"Rúcula","amount":60,"unit":"g"},{"name":"Aguacate","amount":100,"unit":"g"},{"name":"Tahini","amount":25,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Pimentón ahumado","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar boniato y cortar en dados de 2 cm.","Escurrir garbanzos cocidos y secar con papel de cocina hasta que estén bien secos.","Mezclar el boniato y los garbanzos con aceite de oliva, comino molido y pimentón ahumado en una bandeja.","Hornear 25 min hasta que el boniato esté tierno y los garbanzos crujientes.","Llevar a ebullición agua con sal en un cazo y cocer quinoa según el tiempo del envase.","Escurrir la quinoa y dejar templar.","Mezclar tahini, zumo de limón y el resto del aceite de oliva con 2 cucharadas de agua hasta que el aliño esté fluido.","Laminar aguacate.","Retirar la bandeja del horno cuando el boniato esté tierno y los garbanzos crujientes.","Repartir la quinoa en 2 boles y añadir rúcula encima.","Añadir el boniato asado, los garbanzos crujientes y el aguacate laminado sobre cada bol.","Terminar cada bol con un chorrito del aliño de tahini por encima."}', 'Cuencos de colores con garbanzos asados crujientes, quinoa, boniato y un aliño cremoso de tahini.', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Asa los garbanzos y el boniato cortado en cubos en el horno precalentado a 200°C durante 20-25 minutos, hasta que estén dorados y tiernos. Cocina la quinoa en una olla aparte y prepara la salsa de tahini mientras se asan los vegetales."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C y cocina los garbanzos y el boniato en tandas durante 15-20 minutos, agitándolos a mitad, hasta que estén crujientes. Cocina la quinoa por separado y mezcla el aderezo de tahini."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('meriendas_001', 'Smoothie de kéfir y fruta', 'meriendas', 'none', NULL, ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 210, 9, 34, 4, 2, true, false, '{"lactosa"}', '[{"name":"Kéfir","amount":300,"unit":"ml"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Fresas","amount":120,"unit":"g"},{"name":"Miel","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar plátano y cortar en trozos.","Retirar el pedúnculo a fresas y cortar en mitades.","Añadir kéfir, el plátano troceado y las fresas al vaso de la batidora.","Añadir miel y triturar hasta que la mezcla quede cremosa y sin grumos.","Servir de inmediato en vasos bien fríos."}', 'Batido cremoso de kéfir con plátano y fresas endulzado con miel', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('meriendas_002', 'Tostada de plátano y miel', 'meriendas', 'none', 'pan', ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 260, 6, 46, 5, 2, true, false, '{"gluten"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Plátano","amount":2,"unit":"ud"},{"name":"Miel","amount":20,"unit":"ml"}]'::jsonb, '{"Tostar pan en una tostadora o bajo el grill del horno hasta que esté dorado y crujiente.","Laminar plátano en rodajas de unos 5 mm.","Disponer las rodajas de plátano sobre las tostadas, cubriéndolas bien.","Repartir miel en hilo fino sobre el plátano y servir de inmediato."}', 'Merienda rápida de tostada con plátano en rodajas y miel', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('meriendas_003', 'Bocadillo de jamón serrano', 'meriendas', 'none', 'pan', ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 380, 20, 44, 13, 2, true, true, '{"gluten"}', '[{"name":"Pan de barra","amount":200,"unit":"g"},{"name":"Jamón serrano","amount":80,"unit":"g"},{"name":"Tomate maduro","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan de barra por la mitad a lo largo para abrir cada pieza.","Cortar tomate maduro por la mitad y rallar la pulpa sobre cada mitad de pan hasta que quede bien impregnada.","Repartir aceite de oliva por encima de la pulpa de tomate en cada mitad de pan.","Distribuir jamón serrano sobre la base de cada bocadillo y cerrar con la tapa de pan.","Servir de inmediato para que el pan no se ablande."}', 'Bocadillo de jamón serrano con tomate y aceite', NULL, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
