insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('meriendas_004', 'Bocadillo de pavo y queso', 'meriendas', 'none', 'pan', ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 360, 22, 42, 12, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Pan de barra","amount":200,"unit":"g"},{"name":"Pechuga de pavo","amount":90,"unit":"g"},{"name":"Queso en lonchas","amount":50,"unit":"g"}]'::jsonb, '{"Cortar pan de barra por la mitad a lo largo sin llegar al fondo, dejando las dos mitades unidas.","Disponer queso en lonchas sobre la mitad inferior del pan, cubriéndola de manera uniforme.","Colocar pechuga de pavo sobre el queso, distribuyendo las lonchas en una sola capa.","Cerrar el bocadillo presionando ligeramente y servir."}', 'Bocadillo de fiambre de pavo con queso', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('meriendas_005', 'Fruta con frutos secos', 'meriendas', 'none', NULL, ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 250, 6, 34, 11, 2, false, true, '{"frutos_secos"}', '[{"name":"Manzana","amount":1,"unit":"ud"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Nueces","amount":40,"unit":"g"}]'::jsonb, '{"Pelar plátano y cortarlo en rodajas.","Lavar manzana, retirar el corazón y cortarla en trozos.","Repartir la manzana y el plátano en 2 cuencos.","Añadir nueces por encima de la fruta y servir."}', 'Merienda de fruta troceada con nueces', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('meriendas_006', 'Batido de leche y cacao', 'meriendas', 'none', NULL, ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 3, 'facil', 'all', 220, 9, 32, 6, 2, true, false, '{"lactosa"}', '[{"name":"Leche","amount":400,"unit":"ml"},{"name":"Cacao en polvo","amount":30,"unit":"g"}]'::jsonb, '{"Verter leche en un cazo y calentar a fuego medio hasta que esté templada, o dejarla fría según preferencia.","Añadir cacao en polvo a la leche y remover con energía hasta que el cacao quede completamente disuelto sin grumos.","Servir el batido repartido en 2 vasos."}', 'Vaso de leche con cacao, la merienda clásica de la infancia', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_001', 'Macarrones con tomate', 'pasta_arroces', 'none', 'pasta', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 412, 14, 62, 12, 2, true, true, '{"gluten"}', '[{"name":"Macarrones","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar y picar ajo fino.","Llevar a ebullición una olla grande con agua abundante y sal.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada en la sartén hasta que esté transparente.","Añadir el ajo picado y sofreír 1 min hasta que se dore ligeramente.","Añadir tomate triturado y orégano a la sartén y remover.","Cocer la salsa a fuego suave, sin tapar, hasta que espese ligeramente.","Cocer macarrones en el agua hirviendo con sal según el tiempo indicado en el envase.","Escurrir los macarrones cuando estén al dente y reservar.","Añadir los macarrones escurridos a la sartén con la salsa y mezclar a fuego suave 1 min.","Servir los macarrones en platos hondos."}', 'Macarrones con salsa de tomate casera y orégano', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, luego añade el tomate triturado y el orégano para la salsa. Incorpora los macarrones y el agua, cocinando a 100°C, velocidad cuchara, giro inverso, hasta que la pasta esté al dente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_002', 'Espaguetis a la boloñesa', 'pasta_arroces', 'ternera', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 518, 26, 58, 20, 2, true, true, '{"gluten"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Carne picada de ternera","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vino tinto","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar cebolla y picarla en dados finos. Pelar ajo y picarlo muy fino.","Pelar zanahoria y rallarla con un rallador fino.","Calentar aceite de oliva en sartén grande a fuego medio hasta que esté caliente.","Sofreír la cebolla picada y el ajo picado en la sartén a fuego medio hasta que estén transparentes.","Añadir la zanahoria rallada y sofreír junto con la cebolla hasta que esté tierna.","Incorporar carne picada de ternera y saltear a fuego fuerte, desmenuzando con una cuchara, hasta que se dore por completo.","Añadir vino tinto y remover hasta que se evapore el alcohol.","Incorporar tomate triturado y remover bien.","Tapar la sartén y cocer a fuego suave hasta que la salsa espese.","Llevar a ebullición una olla con abundante agua y sal.","Cocer espaguetis en el agua hirviendo hasta que estén al dente, según el tiempo indicado en el paquete.","Escurrir los espaguetis y volcarlos en la sartén con la boloñesa.","Mezclar a fuego suave hasta que los espaguetis queden bien integrados con la salsa.","Servir los espaguetis con la salsa boloñesa bien repartida."}', 'Espaguetis con ragú de carne picada, tomate y zanahoria', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Prepara el sofrito y dora la carne en una olla apta para horno en la encimera. Añade el resto de ingredientes de la salsa y hornea a 150°C durante 1.5-2 horas para una boloñesa de sabor profundo. Los espaguetis se cuecen aparte."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Pica las verduras en el vaso, sofríelas con aceite, añade la carne y el vino para dorar. Incorpora el tomate y cocina la salsa a temperatura y velocidad controladas. Los espaguetis se pueden cocer en el vaso o cestillo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_003', 'Arroz con tomate frito', 'pasta_arroces', 'none', 'arroz', ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 342, 6, 58, 8, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar y picar ajo muy fino.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír el ajo picado en el aceite caliente hasta que esté dorado y fragante, sin que llegue a quemarse.","Añadir arroz y sofreír sin parar de remover hasta que los granos estén ligeramente translúcidos.","Incorporar tomate triturado y remover para integrar bien con el arroz.","Añadir 360 ml de agua, remover y llevar a ebullición a fuego fuerte.","Tapar la cazuela, bajar a fuego suave y cocer hasta que el arroz haya absorbido todo el líquido y esté tierno.","Retirar del fuego y dejar reposar tapado 2 min antes de servir.","Servir el arroz con tomate en platos hondos recién hecho."}', 'Arroz blanco cocido con salsa de tomate frito', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo y el tomate en una cazuela apta para horno. Añade el arroz y el doble de agua, lleva a ebullición, tapa y hornea a 180°C durante 18-20 minutos hasta que el líquido se absorba."},{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe el ajo y el tomate en el vaso. Añade el arroz y el doble de agua, programa 18-20 minutos, 100°C, giro inverso, velocidad cuchara para un arroz suelto y bien integrado."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe el ajo y el tomate en la olla. Añade el arroz y 1.5 veces su volumen de agua, cierra la olla y cocina a presión durante 6-7 minutos. Deja despresurizar de forma natural para un arroz perfecto."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_004', 'Arroz al horno', 'pasta_arroces', 'cerdo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'invierno', 528, 24, 56, 22, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Costilla de cerdo","amount":150,"unit":"g"},{"name":"Morcilla","amount":60,"unit":"g"},{"name":"Garbanzos cocidos","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en rodajas de unos 5 mm de grosor.","Calentar aceite de oliva en una cazuela de barro a fuego medio.","Dorar costilla de cerdo en el aceite caliente hasta que esté dorada por todos los lados; retirar y reservar.","Dorar morcilla en la misma cazuela a fuego medio hasta que esté marcada; retirar y reservar.","Añadir tomate triturado a la cazuela y sofreír a fuego medio durante 3 min hasta que reduzca ligeramente.","Incorporar pimentón al sofrito y remover 30 segundos a fuego suave para que no se queme.","Precalentar el horno a 200 °C con calor arriba y abajo.","Repartir arroz de forma uniforme sobre el sofrito en la cazuela de barro.","Distribuir garbanzos cocidos, las rodajas de patata, la costilla reservada y la morcilla reservada sobre el arroz.","Verter agua o caldo caliente hasta cubrir el arroz unos 2 cm por encima (aprox. 360 ml); salpimentar al gusto.","Hornear la cazuela destapada a 200 °C durante 25 min hasta que el arroz esté seco y la superficie ligeramente dorada.","Retirar la cazuela del horno y dejar reposar 3 min antes de servir.","Servir el arroz al horno directamente en la cazuela de barro."}', 'Arroz al horno valenciano con costilla, morcilla y garbanzos', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara un sofrito con la costilla y el tomate, añade el arroz y el caldo (o agua con pimentón) en una cazuela de barro. Hornea a 190°C durante 45-50 minutos, incorporando la morcilla y las patatas cortadas a mitad de cocción para que se doren y el arroz quede suelto y con socarrat en el fondo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_005', 'Espaguetis carbonara', 'pasta_arroces', 'cerdo', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 548, 22, 56, 26, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Panceta","amount":100,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Queso parmesano","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Rallar queso parmesano finamente y reservar.","Cortar panceta en dados de unos 5 mm y reservar.","Batir huevo en un bol.","Añadir el queso parmesano rallado al huevo batido y mezclar hasta obtener una crema homogénea. Reservar.","Llevar a ebullición una olla con agua abundante y sal al gusto.","Cocer espaguetis en el agua hirviendo hasta que estén al dente, siguiendo el tiempo del paquete.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la panceta en dados hasta que esté dorada y crujiente.","Escurrir los espaguetis reservando un vaso del agua de cocción.","Retirar la sartén del fuego e incorporar los espaguetis escurridos a la panceta.","Añadir la crema de huevo y parmesano sobre la pasta y remover con rapidez.","Añadir el agua de cocción reservada poco a poco hasta que la salsa ligue y quede cremosa sin cuajar el huevo.","Servir de inmediato con más queso parmesano rallado al gusto."}', 'Espaguetis carbonara con panceta, huevo y parmesano', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_006', 'Macarrones con atún', 'pasta_arroces', 'pescado_azul', 'pasta', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 448, 24, 58, 14, 2, true, true, '{"gluten","pescado"}', '[{"name":"Macarrones","amount":200,"unit":"g"},{"name":"Atún en conserva","amount":120,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Picar cebolla en trozos finos y picar ajo.","Llevar a ebullición una olla con agua abundante y sal.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada en la sartén hasta que esté transparente.","Añadir el ajo picado y sofreír 1 min hasta que se dore ligeramente.","Incorporar tomate triturado a la sartén y remover. Cocer a fuego medio hasta que reduzca.","Cocer macarrones en el agua hirviendo según el tiempo indicado en el paquete, hasta que estén al dente.","Escurrir atún en conserva y desmenuzarlo con un tenedor.","Añadir el atún desmenuzado a la salsa de tomate y mezclar a fuego suave.","Añadir orégano a la salsa y remover para integrar.","Escurrir los macarrones y añadirlos a la sartén con la salsa. Mezclar bien a fuego suave hasta que estén integrados.","Servir los macarrones en platos hondos y añadir orégano al gusto."}', 'Macarrones con salsa de tomate y atún en conserva', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Añade el tomate triturado, orégano y un poco de agua, cocina unos minutos. Incorpora los macarrones y cocina el tiempo indicado en el paquete. Finalmente, añade el atún escurrido y mezcla."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_007', 'Arroz con pollo', 'pasta_arroces', 'pollo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 498, 30, 54, 16, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Contramuslo de pollo","amount":250,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Cortar contramuslo de pollo en trozos de unos 4 cm.","Salpimentar los trozos de contramuslo de pollo y reservar.","Picar cebolla en brunoise fina.","Cortar pimiento rojo en dados pequeños.","Calentar aceite de oliva en una cazuela amplia a fuego medio hasta que esté caliente.","Dorar los trozos de contramuslo de pollo en la cazuela a fuego medio-fuerte hasta que estén dorados por todos los lados.","Retirar el contramuslo de pollo dorado y reservar en un plato.","Sofreír la cebolla picada y el pimiento rojo en la misma cazuela a fuego medio hasta que estén tiernos.","Añadir tomate triturado y pimentón al sofrito; remover hasta integrar.","Cocinar el sofrito a fuego medio hasta que el tomate pierda el agua.","Añadir arroz y remover hasta que los granos queden bien impregnados del sofrito.","Incorporar el contramuslo de pollo reservado y guisantes; remover para integrar.","Cubrir con 360 ml de agua caliente, llevar a ebullición a fuego fuerte y ajustar de sal.","Cocer a fuego suave, tapado, sin remover hasta que el arroz haya absorbido todo el líquido.","Retirar del fuego y dejar reposar tapado antes de servir.","Servir el arroz con pollo directamente de la cazuela, repartiendo el pollo de forma uniforme."}', 'Arroz caldoso con trozos de pollo, pimiento y guisantes', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Prepara un sofrito con el pollo y las verduras en una cazuela apta para horno. Añade el arroz, tomate, pimentón y el doble de caldo caliente que de arroz, y hornea a 190°C durante 25-30 minutos hasta que el arroz absorba el líquido y esté tierno."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea y sofríe las verduras, luego dora el pollo. Incorpora el arroz, tomate, pimentón y el caldo (doble de agua que de arroz), y cocina a 100°C, giro inverso, velocidad cuchara, durante 20-22 minutos, hasta que el arroz esté en su punto."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe el pollo y las verduras en la olla abierta. Añade el arroz, tomate, pimentón y el caldo (1.5 veces el volumen de arroz), cierra la olla y cocina a presión media-alta durante 8-10 minutos desde que sube la válvula. Deja reposar unos minutos antes de abrir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pasta_arroces_008', 'Fideos con carne', 'pasta_arroces', 'cerdo', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 472, 24, 54, 18, 2, true, true, '{"gluten"}', '[{"name":"Fideos gruesos","amount":180,"unit":"g"},{"name":"Carne picada de cerdo","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Picar cebolla y pimiento verde en trozos pequeños. Picar ajo fino. Reservar por separado.","Calentar aceite de oliva en una sartén amplia a fuego fuerte hasta que esté caliente.","Añadir carne picada de cerdo y dorar a fuego fuerte, removiendo, hasta que pierda el color rosado y esté dorada.","Retirar la carne de la sartén y reservar en un plato.","Bajar a fuego medio. Sofreír la cebolla y el pimiento verde picados en la misma sartén hasta que estén tiernos.","Añadir el ajo picado y pimentón y sofreír hasta que el ajo esté dorado, sin que se queme.","Añadir tomate triturado y sofreír a fuego medio hasta que reduzca y la salsa esté concentrada.","Añadir fideos gruesos y tostar en la salsa a fuego medio, removiendo, hasta que se doren ligeramente.","Cubrir los fideos con agua caliente o caldo hasta superarlos en 1 cm. Llevar a ebullición a fuego fuerte.","Incorporar la carne reservada, remover y cocer a fuego medio hasta que los fideos estén tiernos y absorban el caldo.","Retirar del fuego y dejar reposar 1 min antes de servir.","Servir los fideos con la carne directamente en platos hondos."}', 'Fideos gruesos guisados con carne picada y sofrito', '[{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica la cebolla, pimiento y ajo. Sofríe con aceite, añade la carne y sofríe. Incorpora el tomate, pimentón, fideos y agua/caldo. Cocina a temperatura y tiempo indicados para los fideos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_009', 'Arroz a la cubana', 'pasta_arroces', 'huevo', 'arroz', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 468, 14, 62, 18, 2, true, false, '{"huevo"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Plátano macho","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar ajo y picar fino. Reservar.","Pelar plátano macho y cortar en rodajas de 1 cm. Reservar.","Llevar a ebullición una olla con agua y sal a fuego fuerte.","Añadir arroz al agua hirviendo y cocer a fuego medio durante 18 min hasta que esté tierno.","Calentar aceite de oliva en sartén a fuego medio y sofreír el ajo picado 1 min hasta que empiece a dorarse.","Añadir tomate triturado a la sartén con el ajo y cocer a fuego suave 8 min hasta que la salsa espese.","Retirar la salsa de tomate de la sartén y reservar.","Calentar aceite de oliva en sartén a fuego fuerte y freír las rodajas de plátano macho 2 min hasta que estén doradas.","Dar la vuelta a las rodajas de plátano macho y freír 2 min más hasta que estén doradas por el otro lado. Retirar y reservar.","Freír huevo en la misma sartén a fuego medio hasta que la clara esté cuajada y el borde dorado.","Escurrir el arroz cocido.","Servir el arroz en plato junto a la salsa de tomate, el huevo frito y las rodajas de plátano macho."}', 'Arroz blanco con tomate frito, huevo frito y plátano', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_010', 'Pasta al pesto', 'pasta_arroces', 'none', 'pasta', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 478, 14, 54, 24, 2, true, true, '{"gluten","frutos_secos","lactosa"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Albahaca fresca","amount":30,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Rallar queso parmesano con un rallador fino y reservar.","Llevar una olla con agua abundante y sal a ebullición a fuego fuerte.","Cocer espaguetis en el agua hirviendo siguiendo el tiempo indicado en el envase, hasta que estén al dente.","Poner albahaca fresca, piñones, ajo, el queso parmesano rallado y aceite de oliva en el vaso de la batidora.","Triturar todos los ingredientes del vaso hasta obtener una pasta homogénea y reservar el pesto.","Reservar un cazo pequeño con agua de cocción de la olla antes de escurrir los espaguetis.","Escurrir los espaguetis y devolverlos a la olla a fuego suave.","Añadir el pesto reservado a la olla y mezclar bien con los espaguetis hasta que queden uniformemente cubiertos.","Añadir un chorrito del agua de cocción reservada y remover hasta que la salsa ligue y tenga textura cremosa.","Servir los espaguetis al pesto en platos hondos."}', 'Espaguetis con pesto casero de albahaca y piñones', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"La Thermomix es ideal para esta receta. Primero, tritura los ingredientes del pesto en el vaso a velocidad progresiva durante unos segundos. Luego, sin limpiar el vaso, añade agua y sal, calienta y cocina los espaguetis según el tiempo indicado en el paquete."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_011', 'Arroz con verduras', 'pasta_arroces', 'none', 'arroz', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 368, 8, 58, 12, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Judías verdes","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Cortar judías verdes en trozos de 2-3 cm y zanahoria en dados pequeños.","Cortar pimiento rojo en dados pequeños.","Calentar aceite de oliva en una cazuela amplia a fuego medio.","Sofreír las judías verdes, la zanahoria y el pimiento rojo hasta que estén ligeramente tiernos, unos 5 min.","Añadir guisantes y remover para integrar con el resto de verduras.","Añadir tomate triturado y pimentón y sofreír hasta que el tomate pierda el agua, unos 2 min.","Añadir arroz y remover para que se impregne bien del sofrito durante 1 min.","Añadir 360 ml de agua caliente, llevar a ebullición a fuego fuerte y remover una sola vez.","Reducir a fuego suave, tapar la cazuela y cocer hasta que el arroz absorba todo el líquido, unos 16 min.","Retirar del fuego y dejar reposar tapado 2 min antes de servir.","Servir el arroz con verduras directamente de la cazuela."}', 'Arroz seco con verduras de temporada al estilo paella', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Sofríe las verduras en una cazuela apta para horno. Añade el arroz, tomate, pimentón y el doble de agua caliente. Cubre bien y hornea a 190°C durante 30-35 minutos, hasta que el arroz absorba el líquido y quede suelto."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea las verduras en el vaso y sofríelas con aceite. Incorpora el arroz, tomate, pimentón y el agua (aprox. el doble que de arroz). Cocina a 100°C, giro inverso, velocidad cuchara, durante unos 20-25 minutos, hasta que el arroz esté cocido."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla abierta con aceite. Añade el arroz, tomate, pimentón y 1.5 veces su volumen de agua caliente. Cierra la olla y cocina a presión (posición 2) durante 5-7 minutos. Apaga el fuego y deja despresurizar sola."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_012', 'Espaguetis con gambas', 'pasta_arroces', 'marisco', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 438, 24, 56, 14, 2, true, true, '{"gluten","marisco"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Guindilla","amount":1,"unit":"ud"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Laminar ajo finamente y reservar.","Cortar guindilla en rodajas finas y reservar.","Cocer espaguetis en el agua hirviendo hasta que estén al dente, unos 8 min.","Calentar sartén a fuego medio con aceite de oliva.","Sofreír el ajo laminado y la guindilla en rodajas hasta que el ajo esté dorado, unos 2 min.","Añadir gambas peladas y saltear a fuego fuerte hasta que estén rosadas, unos 2 min.","Verter vino blanco y remover a fuego fuerte hasta que se evapore el alcohol, unos 2 min.","Escurrir los espaguetis y añadirlos a la sartén.","Mezclar a fuego suave hasta que la pasta quede bien ligada con la salsa, 1 min.","Picar perejil fino y esparcir sobre la pasta antes de servir."}', 'Espaguetis salteados con gambas al ajillo y vino blanco', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina la pasta en el vaso con agua y sal. Luego, en el mismo vaso, sofríe el ajo y la guindilla, añade las gambas y el vino blanco para hacer la salsa, y finalmente mezcla todo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_013', 'Arroz negro', 'pasta_arroces', 'marisco', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 432, 20, 56, 14, 2, false, false, '{"moluscos","pescado"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Sepia","amount":200,"unit":"g"},{"name":"Tinta de calamar","amount":8,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":400,"unit":"ml"}]'::jsonb, '{"Pelar y picar cebolla en trozos finos.","Pelar y picar ajo en trozos finos.","Cortar sepia en trozos de bocado de unos 2 cm.","Disolver tinta de calamar en caldo de pescado removiendo hasta que se integre por completo. Reservar.","Calentar aceite de oliva en una paella o cazuela ancha a fuego medio hasta que esté caliente.","Sofreír la cebolla picada y el ajo picado a fuego medio, removiendo, hasta que estén blandos y translúcidos.","Añadir la sepia troceada y saltear a fuego fuerte hasta que se dore ligeramente por fuera.","Añadir tomate triturado y sofreír a fuego medio hasta que pierda el agua y el conjunto se concentre.","Incorporar arroz y remover durante 1 min hasta que los granos queden impregnados del sofrito.","Verter el caldo con la tinta reservado, repartir bien el arroz en una capa uniforme y llevar a ebullición.","Cocer a fuego medio-suave, sin remover, hasta que el arroz absorba el caldo y esté en su punto.","Retirar del fuego y dejar reposar tapado 2 min antes de servir.","Servir el arroz negro directamente desde la cazuela, repartiendo la sepia de forma uniforme entre los platos."}', 'Arroz teñido con tinta de calamar y sepia troceada', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Se prepara el sofrito con la sepia en una cazuela apta para horno. Se añade el arroz, la tinta y el caldo caliente, se lleva a ebullición y se hornea a 180°C durante 20-25 minutos hasta que el arroz absorba el líquido y quede en su punto."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica cebolla y ajo, sofríe con aceite. Añade la sepia y tomate, luego el arroz, la tinta y el caldo, programando 20-22 minutos a 100°C, giro inverso y velocidad cuchara hasta que el arroz esté cocido y jugoso."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Se sofríen las verduras y la sepia en la olla. Se añade el arroz, la tinta y el caldo, se cierra la olla y se cocina a presión durante 7-8 minutos. Se despresuriza y se deja reposar unos minutos antes de servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_014', 'Pasta con salmón y champiñones', 'pasta_arroces', 'pescado_azul', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 472, 24, 52, 18, 2, true, true, '{"gluten","lactosa","pescado"}', '[{"name":"Macarrones","amount":200,"unit":"g"},{"name":"Salmón","amount":200,"unit":"g"},{"name":"Champiñones","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Nata","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Laminar champiñones y reservar.","Picar cebolla en trozos finos y reservar.","Picar ajo fino y reservar.","Cortar salmón en dados de unos 2 cm y reservar.","Llevar a ebullición agua con sal en una olla a fuego fuerte.","Cocer macarrones en el agua hirviendo hasta que estén al dente, según el tiempo del paquete.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada y el ajo picado en la sartén hasta que estén tiernos y ligeramente dorados.","Añadir los champiñones laminados y saltear a fuego fuerte hasta que pierdan el agua y se doren.","Añadir los dados de salmón y saltear a fuego medio hasta que estén sellados por fuera, unos 2 min.","Añadir nata y remover a fuego suave hasta que la salsa ligue y espese ligeramente.","Escurrir los macarrones y añadirlos a la sartén; remover hasta que se integren bien con la salsa.","Picar perejil y repartir sobre la pasta antes de servir."}', 'Pasta con salmón, champiñones y cebolla en una salsa suave y sedosa', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, el ajo y los champiñones en el vaso. Añade la pasta, el agua y la sal, cocinando el tiempo indicado en el paquete. Incorpora el salmón en dados y la nata, y mezcla a baja velocidad hasta integrar una salsa suave y sedosa. Termina con perejil."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_015', 'Arroz tres delicias', 'pasta_arroces', 'huevo', 'arroz', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 428, 16, 56, 14, 2, true, true, '{"huevo","soja"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Salsa de soja","amount":15,"unit":"ml"}]'::jsonb, '{"Llevar a ebullición agua con sal en una olla a fuego fuerte.","Añadir arroz y cocer según el paquete hasta que esté tierno.","Pelar zanahoria y cortar en dados de 5 mm.","Cortar jamón cocido en dados de 5 mm.","Batir huevo en un bol con salsa de soja hasta que estén homogéneos.","Escurrir el arroz cocido y extender en una bandeja para que enfríe.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Añadir el huevo batido y cuajar sin remover hasta que esté hecho por dentro.","Retirar la tortilla de la sartén y cortar en dados de 5 mm. Reservar.","Subir el fuego a fuerte en la misma sartén. Saltear la zanahoria 2 min hasta que empiece a estar tierna.","Añadir guisantes y saltear junto a la zanahoria 1 min hasta que estén calientes.","Añadir el jamón cocido y saltear 1 min removiendo hasta que se integre con las verduras.","Añadir el arroz frío y saltear a fuego fuerte 2 min removiendo sin parar hasta que esté suelto.","Verter salsa de soja sobre el arroz y saltear 1 min removiendo hasta que tome color uniforme.","Añadir los dados de tortilla reservados y mezclar con suavidad hasta incorporarlos sin que se deshagan.","Servir de inmediato."}', 'Arroz salteado con tortilla, guisantes, zanahoria y jamón', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_016', 'Tallarines con pollo', 'pasta_arroces', 'pollo', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 472, 30, 54, 14, 2, true, true, '{"gluten","soja"}', '[{"name":"Tallarines","amount":200,"unit":"g"},{"name":"Pechuga de pollo","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Calabacín","amount":80,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en tiras finas de 1 cm de grosor.","Cortar pimiento rojo en juliana fina.","Cortar calabacín en juliana fina.","Picar ajo muy fino.","Llevar a ebullición una olla grande con agua abundante y salsa de soja.","Añadir tallarines cuando el agua rompa a hervir y cocer hasta que estén al dente, según el tiempo del paquete.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Saltear las tiras de pechuga de pollo en sartén a fuego fuerte hasta que estén doradas por fuera y cocidas por dentro.","Añadir el pimiento rojo, el calabacín y el ajo picado a sartén.","Saltear las verduras a fuego fuerte hasta que estén tiernas pero con mordida.","Escurrir los tallarines al dente y reservar un poco del agua de cocción.","Incorporar los tallarines escurridos a sartén y añadir salsa de soja.","Saltear a fuego fuerte removiendo constantemente hasta que todo esté bien integrado.","Servir los tallarines con pollo directamente desde sartén al plato, bien calientes."}', 'Tallarines salteados con tiras de pollo y verduras', '[{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Sofríe el ajo, pollo y verduras en el vaso. Añade los tallarines, agua (o caldo) y salsa de soja, y cocina a la temperatura y tiempo indicados para la pasta, usando la mariposa para remover."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_017', 'Lasaña de carne', 'pasta_arroces', 'ternera', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 562, 28, 42, 30, 2, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Placas de lasaña","amount":120,"unit":"g"},{"name":"Carne picada de ternera","amount":250,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"ml"},{"name":"Bechamel","amount":200,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar cebolla en dados finos.","Calentar aceite de oliva en una sartén grande a fuego medio.","Sofreír la cebolla picada en sartén hasta que esté transparente, unos 5 min a fuego medio.","Añadir carne picada de ternera y saltear a fuego fuerte hasta que pierda el color rosado por completo.","Añadir tomate triturado, remover y cocer a fuego suave hasta que la salsa reduzca y espese, unos 10 min.","Cocer placas de lasaña en una olla con agua hirviendo con sal el tiempo indicado en el envase; escurrir y reservar sobre un paño limpio.","Precalentar el horno a 190 °C con calor arriba y abajo.","Cubrir la base de una bandeja para horno con una capa fina de bechamel.","Disponer una capa de placas de lasaña sobre la bechamel, cubriendo toda la superficie sin solapar.","Extender la mitad de la boloñesa sobre las placas de lasaña de forma uniforme.","Verter una capa de bechamel sobre la boloñesa y alisar con una espátula.","Repetir el orden: placas de lasaña, el resto de la boloñesa y otra capa de bechamel.","Cubrir la superficie con el resto de la bechamel y esparcir queso rallado por encima de manera uniforme.","Hornear en el horno precalentado a 190 °C durante 25 min hasta que la superficie esté dorada y burbujeante.","Retirar la bandeja del horno y dejar reposar 5 min antes de cortar.","Cortar en porciones y servir directamente desde la bandeja."}', 'Lasaña de placas con ragú de ternera, bechamel y queso gratinado', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara la carne y la bechamel por separado, monta la lasaña por capas en una fuente y hornea a 180-200°C durante 30-40 minutos hasta que el queso esté gratinado y burbujeante."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Monta la lasaña en un molde pequeño apto para airfryer. Cocina a 170-180°C durante 25-30 minutos, vigilando que no se dore demasiado rápido y cubriendo si es necesario para un gratinado perfecto."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pasta_arroces_018', 'Cannelones de carne', 'pasta_arroces', 'ternera', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'invierno', 538, 28, 38, 30, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Placas de cannelones","amount":100,"unit":"g"},{"name":"Carne picada de ternera","amount":250,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Bechamel","amount":250,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nuez moscada","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla muy fina.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, a fuego suave.","Añadir carne picada de ternera y sofreír a fuego medio hasta que pierda el color rosado, removiendo con frecuencia.","Incorporar tomate triturado y remover para integrar.","Cocer a fuego suave hasta que el relleno reduzca y espese.","Retirar el relleno del fuego y reservar.","Llevar a ebullición una olla con abundante agua con sal.","Precalentar el horno a 190 °C con calor arriba y abajo.","Cocer placas de cannelones según el tiempo indicado en el envase, removiendo ocasionalmente.","Escurrir las placas y extenderlas sobre un paño limpio hasta que se enfríen.","Disponer una porción del relleno en el borde de cada placa.","Enrollar cada placa con cuidado hasta formar los cannelones.","Verter una fina capa de bechamel en el fondo de una fuente apta para horno.","Colocar los cannelones sobre la bechamel, bien juntos y en una sola capa.","Cubrir los cannelones con el resto de la bechamel, repartiéndola de forma uniforme.","Espolvorear queso rallado sobre la bechamel.","Añadir nuez moscada por encima del queso.","Hornear a 190 °C durante 20 min, hasta que la superficie esté dorada y burbujeante.","Retirar la fuente del horno y dejar reposar 3 min antes de servir.","Servir los cannelones directamente de la fuente, bien calientes."}', 'Cannelones rellenos de carne con bechamel y queso gratinado', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara el relleno y la bechamel por separado. Monta los canelones en una fuente, cubre con bechamel y queso. Hornea a 180-200°C durante 20-25 minutos hasta que estén dorados y burbujeantes."},{"appliance":"thermomix","time":70,"difficulty":"normal","prepSummary":"Utiliza la Thermomix para picar y sofreír la cebolla con la carne, y para preparar una bechamel perfecta. Luego, rellena los canelones y gratínalos en el horno a 190°C durante 20-25 minutos."},{"appliance":"airfryer","time":60,"difficulty":"normal","prepSummary":"Una vez montados los canelones con su bechamel y queso (preparados aparte), gratínalos en la airfryer en pequeñas porciones. Precalienta a 180°C y cocina durante 15-20 minutos hasta que el queso esté fundido y dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_019', 'Arroz caldoso con marisco', 'pasta_arroces', 'marisco', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 442, 24, 52, 14, 2, false, false, '{"marisco","moluscos","pescado"}', '[{"name":"Arroz","amount":160,"unit":"g"},{"name":"Gambas","amount":150,"unit":"g"},{"name":"Almejas","amount":100,"unit":"g"},{"name":"Sepia","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":500,"unit":"ml"}]'::jsonb, '{"Picar ajo fino y cortar sepia en trozos pequeños.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír el ajo picado hasta que empiece a dorarse, sin que se queme.","Añadir la sepia troceada y saltear a fuego fuerte hasta que pierda el agua y tome color.","Añadir tomate triturado y sofreír a fuego medio hasta que reduzca y oscurezca.","Añadir arroz y remover sin parar durante 1 min para que se impregne del sofrito.","Calentar caldo de pescado en un cazo aparte hasta que rompa a hervir.","Verter el caldo caliente sobre el arroz, subir a fuego fuerte y llevar a ebullición.","Bajar a fuego medio y cocer el arroz sin tapar durante 10 min, removiendo de vez en cuando.","Añadir gambas y almejas y cocer a fuego medio hasta que las almejas se abran.","Retirar del fuego y reposar 2 min antes de servir para que el arroz asiente.","Servir el arroz caldoso directamente en la cazuela o en platos hondos."}', 'Arroz caldoso con gambas, almejas y sepia', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_020', 'Pasta con verduras salteadas', 'pasta_arroces', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 386, 12, 56, 12, 2, true, true, '{"gluten"}', '[{"name":"Penne","amount":200,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Berenjena","amount":80,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Albahaca","amount":5,"unit":"g"}]'::jsonb, '{"Cortar calabacín, pimiento rojo y berenjena en dados de 1 cm.","Laminar ajo finamente.","Llevar a ebullición una olla con abundante agua salada a fuego fuerte.","Cocer penne en el agua hirviendo hasta que estén al dente, según el tiempo del paquete.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Saltear los dados de calabacín, pimiento rojo y berenjena a fuego fuerte hasta que se doren, removiendo con frecuencia.","Añadir el ajo laminado a la sartén y sofreír a fuego medio hasta que esté dorado, sin que se queme.","Escurrir la pasta cocida y añadirla a la sartén con las verduras.","Mezclar a fuego medio durante 1 min hasta que la pasta quede bien integrada con las verduras.","Añadir albahaca picada, remover y retirar del fuego.","Servir la pasta con verduras en platos hondos calientes."}', 'Penne con calabacín, berenjena y pimiento salteados', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo y las verduras con aceite en el vaso. Luego, añade el agua y la pasta, cocinando a la temperatura y tiempo indicados para la pasta, logrando un plato completo y sabroso sin esfuerzo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_021', 'Arroz a banda', 'pasta_arroces', 'pescado_blanco', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 418, 18, 56, 12, 2, true, false, '{"pescado","marisco"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Rape","amount":100,"unit":"g"},{"name":"Gambas","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":400,"unit":"ml"}]'::jsonb, '{"Pelar gambas, reservar las colas y apartar las cabezas para el caldo.","Limpiar rape y cortar en dados de unos 3 cm; reservar.","Picar ajo muy fino; reservar.","Verter caldo de pescado en un cazo, añadir las cabezas de las gambas reservadas y llevar a ebullición a fuego fuerte.","Cocer el caldo a fuego medio durante 5 min, colar y mantener caliente a fuego suave.","Calentar aceite de oliva en una paella o cazuela amplia a fuego medio.","Sofreír el ajo picado hasta que esté dorado, sin que se queme.","Añadir tomate triturado y sofreír a fuego medio hasta que pierda el agua y se concentre, unos 3 min.","Añadir pimentón y remover 20 segundos fuera del fuego para que no se queme.","Incorporar arroz y sofreír removiendo a fuego medio durante 1 min hasta que los granos estén nacarados.","Verter el caldo caliente colado en proporción 2,2:1 sobre el arroz y remover una sola vez para igualar.","Cocer a fuego fuerte los primeros 5 min sin tapar y sin remover.","Bajar a fuego suave y cocer 13 min más hasta que el arroz absorba todo el caldo.","Calentar una plancha a fuego fuerte y marcar los dados de rape 1 min por cada lado hasta que estén dorados.","Marcar las colas de gambas en la misma plancha a fuego fuerte durante 1 min hasta que estén rosadas.","Retirar el arroz del fuego y dejar reposar tapado 2 min.","Servir el arroz en un plato y el rape y las gambas marcadas aparte, al estilo tradicional."}', 'Arroz seco cocinado en caldo de pescado, servido aparte', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Prepara el sofrito en una cazuela apta para horno. Añade el arroz y el caldo de pescado caliente. Cocina en el horno precalentado a 190°C durante 18-20 minutos, incorporando el rape y las gambas en los últimos 5-7 minutos para que no se sequen. El horno asegura una cocción uniforme."},{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Sofríe el ajo y el tomate en la Thermomix. Añade el arroz, pimentón y caldo, programando 18-20 minutos, 100°C, giro inverso, velocidad cuchara. Incorpora el rape y las gambas los últimos 5 minutos para una cocción perfecta y sin pegarse."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_022', 'Espaguetis al ajo y guindilla', 'pasta_arroces', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 396, 10, 56, 14, 2, false, true, '{"gluten"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Guindilla","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Llevar una olla grande con agua abundante y sal a ebullición a fuego fuerte.","Laminar ajo en rodajas finas y cortar guindilla en aros, retirando las semillas si se desea menos picante.","Añadir espaguetis al agua hirviendo y cocer según el tiempo del fabricante hasta que estén al dente.","Calentar aceite de oliva en sartén a fuego suave hasta que esté templado.","Añadir el ajo laminado y los aros de guindilla al aceite templado y sofreír a fuego suave hasta que el ajo esté dorado y fragante.","Reservar 1 cazo del agua de cocción antes de escurrir los espaguetis.","Escurrir los espaguetis y añadirlos a la sartén con el aceite, el ajo y la guindilla.","Añadir el agua de cocción reservada y saltear a fuego medio removiendo hasta que la salsa ligue y cubra la pasta.","Picar perejil fino y espolvorear sobre la pasta justo antes de servir."}', 'Espaguetis aglio e olio con ajo dorado y guindilla', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Pica el ajo y la guindilla, sofríelos con aceite en el vaso. Después, añade el agua y la sal, calienta y cocina los espaguetis al dente, integrando todo al finalizar."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_023', 'Fideuá de pollo', 'pasta_arroces', 'pollo', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 462, 28, 52, 16, 2, true, false, '{"gluten"}', '[{"name":"Fideos n°2","amount":180,"unit":"g"},{"name":"Contramuslo de pollo","amount":250,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pollo","amount":400,"unit":"ml"}]'::jsonb, '{"Cortar contramuslo de pollo en trozos de bocado y salpimentar.","Cortar pimiento rojo en brunoise fina y picar ajo.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Dorar el contramuslo troceado en la sartén caliente hasta que esté dorado por todos los lados; retirar y reservar.","Bajar a fuego medio y sofreír el pimiento rojo y el ajo en la misma sartén hasta que estén tiernos.","Añadir tomate triturado y pimentón al sofrito; remover y cocer hasta que el tomate pierda el agua y se concentre.","Incorporar fideos n°2 y tostar removiendo sin parar hasta que estén dorados de forma uniforme.","Verter caldo de pollo caliente y llevar a ebullición a fuego fuerte.","Incorporar el contramuslo reservado, repartir de forma uniforme y bajar a fuego medio.","Cocer sin tapar hasta que los fideos absorban el caldo y estén al dente y el pollo esté cocinado por completo.","Retirar del fuego y dejar reposar 2 min antes de servir.","Servir la fideuá directamente en la sartén o repartir en platos hondos."}', 'Fideos tostados con pollo y pimiento en caldo', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Sofreír el pollo y las verduras en una sartén apta para horno. Añadir los fideos y el caldo, llevar a ebullición y hornear a 200°C durante unos 15-20 minutos, hasta que los fideos absorban el líquido y se doren."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Sofreír el pollo y las verduras en el vaso. Incorporar los fideos y el caldo, programar temperatura Varoma, giro inverso y velocidad cuchara durante el tiempo necesario para que la pasta absorba el líquido."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_024', 'Ensalada de pasta mediterránea', 'pasta_arroces', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'verano', 408, 14, 46, 18, 2, true, true, '{"gluten","lactosa","frutos_secos","sulfitos"}', '[{"name":"Fusilli","amount":200,"unit":"g"},{"name":"Tomate cherry","amount":120,"unit":"g"},{"name":"Mozzarella fresca","amount":100,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Aceitunas negras","amount":30,"unit":"g"},{"name":"Pesto","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Llevar a ebullición una olla con agua abundante y sal.","Cocer fusilli en el agua hirviendo hasta que estén al dente, siguiendo el tiempo del paquete.","Cortar tomate cherry por la mitad.","Cortar mozzarella fresca en dados de 1 cm.","Escurrir los fusilli y enfriar bajo agua fría hasta que estén a temperatura ambiente.","Añadir los tomates cherry, la mozzarella, rúcula, aceitunas negras y pesto a la pasta escurrida.","Mezclar todo con suavidad hasta que el pesto cubra bien la pasta y el resto de ingredientes.","Servir con aceite de oliva por encima."}', 'Ensalada fría de pasta con cherry, mozzarella, rúcula, aceitunas y pesto', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_025', 'Risotto de champiñones', 'pasta_arroces', 'none', 'arroz', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'invierno', 428, 10, 56, 18, 2, true, false, '{"lactosa"}', '[{"name":"Arroz arborio","amount":180,"unit":"g"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Caldo de verduras","amount":500,"unit":"ml"}]'::jsonb, '{"Cortar cebolla en dados pequeños.","Limpiar champiñones y laminar.","Rallar queso parmesano y reservar.","Calentar caldo de verduras en un cazo a fuego suave hasta que esté caliente; mantener a fuego mínimo.","Fundir mantequilla en una olla a fuego medio.","Sofreír la cebolla en la mantequilla fundida hasta que esté transparente.","Añadir los champiñones laminados y saltear a fuego fuerte hasta que pierdan el agua y se doren.","Añadir arroz arborio y sofreír, removiendo sin parar, hasta que los granos estén nacarados.","Verter vino blanco y remover hasta que el arroz lo absorba por completo.","Añadir el caldo caliente cucharón a cucharón, removiendo sin parar y esperando a que cada adición se absorba.","Retirar la olla del fuego cuando el arroz esté al dente y cremoso.","Añadir el queso parmesano rallado y remover con energía hasta integrar por completo.","Tapar la olla y dejar reposar 2 min para que el risotto asiente.","Servir el risotto en platos hondos inmediatamente."}', 'Risotto cremoso de champiñones con parmesano', '[{"appliance":"thermomix","time":28,"difficulty":"facil","prepSummary":"Sofríe la cebolla y los champiñones, luego tuesta el arroz con el vino. Incorpora el caldo y cocina 15-18 min a 100°C, velocidad cuchara, giro inverso, hasta obtener la cremosidad deseada, finalizando con mantequilla y parmesano."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_026', 'Pasta rápida con tomate cherry, ajo y albahaca', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 440, 13, 68, 14, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Espaguetis","amount":180,"unit":"g"},{"name":"Tomates cherry","amount":300,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Laminar ajo.","Cortar tomates cherry por la mitad.","Rallar queso parmesano.","Cocer espaguetis en el agua hirviendo hasta que estén al dente, según el tiempo del envase.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo laminado a fuego medio hasta que se dore ligeramente, sin que se queme.","Añadir los tomates cherry a la sartén y saltear a fuego fuerte hasta que empiecen a reventar.","Retirar un cucharón del agua de cocción y añadirlo a la sartén con los tomates.","Escurrir los espaguetis al dente y añadirlos a la sartén.","Saltear todo junto a fuego fuerte durante 1 min hasta que la pasta absorba la salsa.","Añadir albahaca fresca troceada a mano y el queso parmesano rallado.","Servir enseguida con un chorrito de aceite de oliva por encima."}', 'Espaguetis con cherrys reventados en la sartén, ajo dorado y hoja fresca de albahaca.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_027', 'Espaguetis al huevo y queso (carbonara exprés)', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 560, 22, 66, 22, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Espaguetis","amount":180,"unit":"g"},{"name":"Huevo","amount":120,"unit":"g"},{"name":"Yema de huevo","amount":20,"unit":"g"},{"name":"Queso parmesano","amount":50,"unit":"g"},{"name":"Bacon en taquitos","amount":80,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Rallar queso parmesano finamente.","Batir huevo y yema de huevo en un bol hasta homogeneizar.","Añadir el queso parmesano rallado y pimienta negra a la mezcla de huevo y batir hasta obtener una crema lisa.","Cocer espaguetis en el agua hirviendo el tiempo indicado en el envase.","Dorar bacon en taquitos en sartén a fuego medio sin aceite hasta que quede crujiente.","Reservar un cucharón del agua de cocción antes de escurrir la pasta.","Escurrir los espaguetis y añadirlos a la sartén con el bacon, fuera del fuego.","Verter la crema de huevo y queso sobre los espaguetis calientes y remover sin parar fuera del fuego hasta que ligue y quede cremosa.","Añadir un poco del agua de cocción reservada si la salsa ha espesado demasiado, removiendo hasta conseguir una textura sedosa.","Servir enseguida con más pimienta negra y queso parmesano rallado por encima."}', 'Espaguetis cremosos con huevo y queso, sin nata, listos en el tiempo de cocción de la pasta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL)
