insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pasta_arroces_028', 'Pasta con pesto de bote y tomates cherry', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 480, 14, 64, 18, 2, true, true, '{"gluten","frutos_secos","lactosa"}', '[{"name":"Fusilli","amount":180,"unit":"g"},{"name":"Pesto de albahaca","amount":80,"unit":"g"},{"name":"Tomates cherry","amount":150,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"},{"name":"Piñones","amount":15,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Lavar tomates cherry y cortar cada uno por la mitad.","Calentar sartén a fuego medio sin aceite y tostar piñones removiendo hasta que estén dorados.","Cocer fusilli en el agua hirviendo el tiempo indicado en el envase.","Reservar un cucharón del agua de cocción antes de escurrir la pasta.","Escurrir los fusilli y volcarlos de nuevo en la olla fuera del fuego.","Añadir pesto de albahaca y un poco del agua de cocción reservada, removiendo hasta cubrir uniformemente la pasta.","Incorporar los tomates cherry cortados y remover con suavidad para no aplastarlos.","Rallar queso parmesano sobre cada ración y repartir los piñones tostados por encima."}', 'Pasta verde vivo con pesto de bote y toques rojos de tomate cherry, del tarro a la mesa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_029', 'Pasta con atún, tomate y aceitunas exprés', 'pasta_arroces', 'pescado_azul', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 470, 26, 62, 14, 2, true, true, '{"gluten","pescado"}', '[{"name":"Macarrones","amount":180,"unit":"g"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Aceitunas negras","amount":50,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Pelar y picar ajo fino.","Añadir macarrones al agua hirviendo y cocer según el tiempo del envase.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado hasta que empiece a dorar sin que se queme.","Añadir tomate triturado y cocer a fuego medio hasta que espese ligeramente.","Escurrir atún en conserva y añadirlo a la sartén.","Añadir aceitunas negras y remover para integrar todos los ingredientes.","Cocer 2 min a fuego suave hasta que los sabores se integren.","Escurrir los macarrones cocidos y añadirlos a la sartén.","Mezclar bien hasta que la salsa cubra todos los macarrones.","Servir caliente en platos hondos."}', 'Pasta con atún, tomate y aceitunas, de la despensa a la mesa en un cuarto de hora.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_030', 'Risotto de setas y trufa negra', 'pasta_arroces', 'none', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 560, 14, 74, 20, 2, true, true, '{"lactosa"}', '[{"name":"Arroz arborio","amount":160,"unit":"g"},{"name":"Setas variadas","amount":200,"unit":"g"},{"name":"Caldo de verduras","amount":700,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Queso parmesano","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Trufa negra","amount":8,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Picar cebolla muy fina.","Limpiar setas variadas y laminar.","Rallar queso parmesano y reservar.","Laminar trufa negra muy fina y reservar.","Llevar caldo de verduras a ebullición en una olla, luego bajar a fuego suave para mantenerlo caliente.","Calentar aceite de oliva en una cazuela ancha a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir las setas laminadas y saltear hasta que suelten el agua y se doren ligeramente.","Añadir arroz arborio y remover hasta que los granos queden translúcidos por fuera.","Añadir vino blanco y remover hasta que el alcohol se evapore por completo.","Añadir un cucharón de caldo caliente y remover sin parar hasta que se absorba por completo.","Repetir el proceso, añadiendo el caldo cucharón a cucharón y removiendo sin parar, hasta que el arroz esté cremoso y al dente.","Salpimentar con sal al final de la cocción.","Retirar la cazuela del fuego y añadir mantequilla fría cortada en dados.","Añadir el queso parmesano rallado y mezclar con movimientos envolventes hasta obtener una textura cremosa.","Tapar la cazuela y dejar reposar.","Servir el risotto en platos hondos y disponer las láminas de trufa negra por encima."}', 'Risotto cremoso de setas con láminas de trufa negra recién cortadas por encima.', NULL, '{}', true, NULL, NULL, '{"seta"}', NULL),
  ('pasta_arroces_031', 'Arroz negro con alioli', 'pasta_arroces', 'marisco', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 610, 28, 70, 22, 2, true, true, '{"moluscos","huevo","sulfitos","pescado"}', '[{"name":"Arroz bomba","amount":160,"unit":"g"},{"name":"Calamar","amount":200,"unit":"g"},{"name":"Tinta de calamar","amount":8,"unit":"g"},{"name":"Caldo de pescado","amount":450,"unit":"ml"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pimiento rojo","amount":50,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Alioli","amount":60,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar calamar en aros y tiras pequeñas.","Picar cebolla, pimiento rojo y ajo muy finos.","Calentar caldo de pescado en un cazo a fuego medio hasta que rompa a hervir; mantenerlo caliente.","Calentar aceite de oliva en una paellera a fuego medio.","Sofreír la cebolla, el pimiento rojo y el ajo a fuego medio hasta que estén blandos.","Añadir el calamar y saltear a fuego medio hasta que empiece a dorarse.","Incorporar tomate triturado y sofreír a fuego medio hasta que pierda el agua.","Añadir arroz bomba y remover a fuego medio hasta que se impregne del sofrito.","Disolver tinta de calamar en un cazo pequeño con un poco del caldo caliente hasta integrar.","Añadir la tinta disuelta a la paellera junto con el resto del caldo caliente.","Repartir el arroz de forma uniforme, añadir sal y cocer a fuego fuerte.","Reducir a fuego suave y cocer sin remover hasta que el arroz absorba todo el líquido.","Retirar del fuego y dejar reposar tapado con un paño.","Servir el arroz con alioli en el centro."}', 'Arroz negro intenso con la nube blanca de alioli servida al centro.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_032', 'Paella de marisco con sofrito casero', 'pasta_arroces', 'marisco', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 70, 'elaborada', 'all', 590, 32, 68, 18, 4, true, true, '{"marisco","moluscos","pescado"}', '[{"name":"Arroz bomba","amount":320,"unit":"g"},{"name":"Gambas","amount":200,"unit":"g"},{"name":"Mejillones","amount":250,"unit":"g"},{"name":"Calamar","amount":150,"unit":"g"},{"name":"Caldo de pescado","amount":900,"unit":"ml"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Azafrán","amount":1,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Pelar gambas, reservando las cabezas, y limpiar calamar.","Cortar el calamar en aros de 1 cm.","Limpiar mejillones raspando las conchas y retirando las barbas.","Picar cebolla, pimiento rojo y ajo muy finos.","Llevar caldo de pescado a ebullición en una olla a fuego medio.","Añadir las cabezas de gambas al caldo y mantener a fuego suave.","Calentar aceite de oliva en la paella a fuego fuerte.","Saltear las gambas peladas 1 min por cada lado hasta que se doren.","Retirar las gambas de la paella y reservar.","Sofreír la cebolla, el pimiento rojo y el ajo picados a fuego medio hasta que estén blandos.","Añadir los aros de calamar y saltear a fuego medio hasta que estén ligeramente dorados.","Añadir tomate triturado y sofreír a fuego medio hasta que espese y pierda el agua.","Añadir arroz bomba y remover hasta que se impregne bien del sofrito.","Colar el caldo, retirar las cabezas de gambas y disolver azafrán en el caldo caliente.","Sazonar con sal y verter el caldo sobre el arroz, repartiendo el arroz de forma uniforme.","Cocer a fuego fuerte sin remover durante 10 min.","Repartir los mejillones y las gambas reservadas sobre el arroz.","Bajar a fuego suave y cocer hasta que se absorba el líquido y se forme el socarrat en el fondo.","Retirar la paella del fuego y tapar con un paño limpio.","Reposar tapada hasta que el arroz termine de asentarse.","Servir en la misma paella en la mesa."}', 'Paella de marisco con sofrito casero, socarrat dorado en el borde y marisco entero repartido.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_033', 'Fideuá negra con alioli', 'pasta_arroces', 'marisco', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 570, 27, 66, 20, 2, true, true, '{"gluten","moluscos","huevo","sulfitos","marisco","pescado"}', '[{"name":"Fideos huecos nº 2","amount":180,"unit":"g"},{"name":"Calamar","amount":150,"unit":"g"},{"name":"Gambas","amount":100,"unit":"g"},{"name":"Tinta de calamar","amount":6,"unit":"g"},{"name":"Caldo de pescado","amount":500,"unit":"ml"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Alioli","amount":50,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Limpiar calamar y cortarlo en tiras pequeñas.","Pelar gambas y reservarlas.","Picar cebolla y ajo muy finos.","Calentar caldo de pescado en una olla a fuego medio hasta que esté caliente; reservar caliente.","Calentar aceite de oliva en sartén ancha a fuego medio.","Sofreír la cebolla picada y el ajo picado hasta que estén blandos.","Añadir el calamar en tiras y saltear a fuego fuerte hasta que tome color.","Añadir tomate triturado y sofreír a fuego medio hasta que pierda el agua.","Añadir fideos huecos nº 2 y remover a fuego medio hasta que se doren ligeramente.","Disolver tinta de calamar en un cazo con un poco de caldo caliente hasta integrar.","Añadir la tinta disuelta y el resto del caldo caliente a la sartén.","Añadir sal, repartir los fideos en capa uniforme y cocer a fuego fuerte 5 min sin remover.","Bajar a fuego medio y cocer hasta que el caldo se absorba casi por completo.","Repartir las gambas peladas por encima cuando queden 4 min de cocción.","Retirar del fuego cuando el líquido se haya absorbido y reposar tapado 2 min.","Servir con alioli en el centro de la sartén."}', 'Fideuá negra con los fideos tostados, alioli como contraste cremoso.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_034', 'Arroz meloso de rabo de toro', 'pasta_arroces', 'ternera', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 210, 'elaborada', 'invierno', 650, 34, 62, 26, 4, true, true, '{"sulfitos"}', '[{"name":"Rabo de toro troceado","amount":800,"unit":"g"},{"name":"Arroz bomba","amount":320,"unit":"g"},{"name":"Caldo de carne","amount":900,"unit":"ml"},{"name":"Vino tinto","amount":200,"unit":"ml"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla, zanahoria, puerro y ajo en trozos pequeños.","Salpimentar rabo de toro troceado por todas sus caras con sal.","Calentar aceite de oliva en una olla a fuego fuerte.","Dorar el rabo de toro por todas sus caras hasta que esté bien sellado. Reservar en un plato.","Sofreír la cebolla picada, la zanahoria, el puerro y el ajo en la misma olla a fuego medio hasta que estén blandos.","Añadir tomate triturado y sofreír a fuego medio hasta que pierda el agua y se oscurezca.","Devolver el rabo de toro a la olla y verter vino tinto. Subir el fuego a fuerte.","Reducir el vino a fuego fuerte hasta que el alcohol se evapore y la salsa espese ligeramente.","Verter caldo de carne hasta cubrir el rabo de toro. Tapar la olla y bajar el fuego a suave.","Cocer a fuego suave tapado hasta que la carne se despegue del hueso con facilidad. Añadir caldo si se queda seco.","Retirar el rabo de toro de la olla y dejar templar sobre una bandeja hasta que se pueda manipular.","Desmigar la carne del rabo de toro con las manos o dos tenedores, descartando huesos y grasa.","Triturar la salsa de cocción con un túrmix hasta que quede fina. Colar si quedan tropezones.","Verter la salsa triturada en una cazuela ancha y calentar a fuego medio junto con el caldo restante.","Añadir arroz bomba y la carne desmigada a la cazuela. Repartir bien con una cuchara.","Cocer a fuego medio removiendo de vez en cuando hasta que el arroz esté en su punto y la textura sea melosa.","Retirar del fuego y reposar sin tapar hasta que el arroz termine de absorber el caldo.","Servir el arroz meloso bien caliente en platos hondos."}', 'Arroz meloso con el brillo untuoso del guiso y la carne de rabo de toro deshecha entre el grano.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_035', 'Ravioli de boletus con mantequilla de salvia', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 90, 'elaborada', 'all', 540, 16, 58, 26, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Harina de trigo","amount":250,"unit":"g"},{"name":"Huevo","amount":150,"unit":"g"},{"name":"Boletus secos","amount":30,"unit":"g"},{"name":"Ricotta","amount":150,"unit":"g"},{"name":"Queso parmesano","amount":40,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Salvia fresca","amount":8,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Hidratar boletus secos en agua templada hasta que estén rehidratados.","Tamizar harina de trigo sobre la encimera y hacer un volcán en el centro.","Cascar huevo en el centro del volcán de harina.","Mezclar los huevos con la harina desde el centro hacia fuera hasta integrar.","Amasar la masa con fuerza hasta que esté lisa y elástica.","Envolver la masa en film transparente y dejar reposar a temperatura ambiente.","Escurrir los boletus rehidratados reservando el agua de remojo, y picar fino.","Rallar queso parmesano finamente.","Mezclar los boletus picados con ricotta y el parmesano rallado en un bol.","Añadir sal al relleno y remover hasta obtener una mezcla homogénea.","Dividir la masa reposada en 2 porciones y estirar cada una con rodillo hasta dejarla muy fina.","Colocar montoncitos de relleno sobre una lámina, separados unos 4 cm entre sí.","Cubrir con la segunda lámina de masa y presionar alrededor de cada montoncito para sellar sin dejar aire.","Cortar los ravioli con un cortapastas o cuchillo, dejando borde sellado en cada pieza.","Llevar a ebullición una olla grande con agua abundante y sal.","Cocer los ravioli hasta que suban a la superficie y estén tiernos.","Calentar mantequilla en sartén a fuego medio hasta que empiece a dorarse ligeramente.","Añadir salvia fresca a la mantequilla dorada y freír hasta que esté crujiente.","Escurrir los ravioli con cuidado y pasarlos a la sartén con la mantequilla de salvia.","Servir los ravioli con la mantequilla de salvia por encima y láminas de parmesano."}', 'Ravioli caseros de boletus con pasta translúcida y hojas de salvia fritas por encima.', NULL, '{}', true, NULL, NULL, '{"seta"}', NULL),
  ('pasta_arroces_036', 'Tagliatelle al ragú de jabalí', 'pasta_arroces', 'ternera', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 150, 'normal', 'invierno', 610, 32, 62, 22, 4, true, true, '{"gluten","sulfitos","lactosa"}', '[{"name":"Carne de jabalí picada","amount":500,"unit":"g"},{"name":"Tagliatelle","amount":320,"unit":"g"},{"name":"Tomate triturado","amount":400,"unit":"ml"},{"name":"Vino tinto","amount":150,"unit":"ml"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Apio","amount":50,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Picar cebolla muy fina.","Picar zanahoria muy fina.","Picar apio muy fino.","Picar ajo muy fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada, la zanahoria picada, el apio picado y el ajo picado hasta que estén blandos.","Añadir carne de jabalí picada y dorar hasta que no quede rosada, deshaciendo los grumos.","Verter vino tinto y llevar a fuego fuerte hasta que se evapore el alcohol.","Añadir tomate triturado y remover para integrar.","Salpimentar con sal y remover.","Tapar parcialmente y cocer a fuego muy suave hasta obtener un ragú denso y oscuro, removiendo de vez en cuando.","Llevar a ebullición una olla grande con agua abundante y sal cuando falten 15 min para que el ragú esté listo.","Rallar queso parmesano y reservar.","Cocer tagliatelle en el agua hirviendo según el tiempo del envase hasta que estén al dente.","Escurrir la pasta reservando un vaso del agua de cocción.","Mezclar los tagliatelle escurridos con el ragú, añadiendo agua de cocción si hace falta para ligar la salsa.","Servir con el parmesano rallado por encima."}', 'Tagliatelle con salsa oscura y densa de ragú de jabalí enroscada en la pasta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_037', 'Risotto de calabaza y parmesano', 'pasta_arroces', 'none', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 520, 14, 76, 16, 2, true, true, '{"lactosa"}', '[{"name":"Arroz arborio","amount":160,"unit":"g"},{"name":"Calabaza","amount":250,"unit":"g"},{"name":"Caldo de verduras","amount":700,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Mantequilla","amount":25,"unit":"g"},{"name":"Queso parmesano","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar calabaza y cortar en dados pequeños.","Picar cebolla muy fina.","Rallar queso parmesano y reservar.","Llevar caldo de verduras a ebullición en una olla a fuego medio, luego bajar a fuego suave para mantenerlo caliente.","Calentar aceite de oliva en una cazuela ancha a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir los dados de calabaza y saltear removiendo hasta que empiecen a ablandarse.","Añadir arroz arborio y remover hasta que los granos estén nacarados y translúcidos.","Verter vino blanco y remover hasta que se evapore por completo.","Añadir un cucharón de caldo caliente y remover hasta que se absorba por completo.","Repetir el proceso añadiendo el caldo caliente cucharón a cucharón, removiendo sin parar entre cada adición.","Aplastar ligeramente los dados de calabaza con la cuchara durante la última adición de caldo para que el arroz espese.","Retirar la cazuela del fuego y añadir mantequilla fría cortada en dados.","Añadir el queso parmesano rallado y mantear con movimientos envolventes hasta obtener una textura cremosa.","Añadir sal y remover para integrar.","Tapar la cazuela y dejar reposar.","Servir el risotto en platos hondos con virutas de queso parmesano rallado por encima."}', 'Risotto de un naranja intenso, cremoso, con virutas de parmesano recién rallado.', NULL, '{}', true, NULL, NULL, '{"verdura"}', NULL)
