insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pasta_arroces_038', 'Orecchiette con brócoli y anchoas', 'pasta_arroces', 'pescado_azul', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 470, 18, 64, 15, 2, false, true, '{"gluten","pescado"}', '[{"name":"Orecchiette","amount":180,"unit":"g"},{"name":"Brócoli","amount":250,"unit":"g"},{"name":"Anchoas en aceite","amount":30,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Guindilla","amount":1,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Separar brócoli en arbolitos pequeños.","Pelar ajo y laminar fino.","Llevar a ebullición una olla grande con agua abundante y sal.","Cocer el brócoli en el agua hirviendo durante 3 min.","Retirar el brócoli con una espumadera y reservar, manteniendo el agua hirviendo.","Cocer orecchiette en la misma agua según el tiempo indicado en el envase.","Calentar aceite de oliva en sartén a fuego medio.","Añadir el ajo laminado y guindilla y dorar 1 min hasta que el ajo esté dorado pero sin quemarse.","Añadir anchoas en aceite y deshacer con una cuchara hasta que se disuelvan en el aceite.","Añadir el brócoli reservado y saltear 3 min, aplastando ligeramente algunos arbolitos con la cuchara.","Escurrir la pasta reservando un vaso del agua de cocción.","Añadir la pasta escurrida a la sartén y saltear 2 min a fuego medio.","Añadir un poco del agua de cocción reservada si la pasta ha quedado seca y remover.","Servir enseguida en platos hondos."}', 'Orecchiette de un verde brócoli intenso, con el brillo del aceite y el ajo dorado con anchoas.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL),
  ('pasta_arroces_039', 'Arroz caldoso de bogavante', 'pasta_arroces', 'marisco', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 75, 'elaborada', 'all', 480, 30, 58, 14, 2, true, false, '{"marisco","pescado"}', '[{"name":"Bogavante","amount":500,"unit":"g"},{"name":"Arroz bomba","amount":160,"unit":"g"},{"name":"Caldo de pescado","amount":800,"unit":"ml"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pimiento rojo","amount":50,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar bogavante por la mitad longitudinalmente y separar las pinzas; reservar los jugos que suelte.","Picar cebolla, pimiento rojo y ajo muy finos.","Calentar aceite de oliva en una cazuela ancha a fuego fuerte.","Dorar el bogavante y las pinzas 2 min por cada lado hasta que la cáscara tome color; reservar.","Sofreír la cebolla picada, el pimiento rojo picado y el ajo picado en la misma cazuela a fuego medio.","Añadir tomate triturado y pimentón dulce; remover sin parar hasta que el pimentón no se queme.","Verter caldo de pescado junto con los jugos reservados del bogavante y llevar a ebullición a fuego fuerte.","Añadir arroz bomba y repartirlo bien por toda la cazuela; bajar a fuego medio.","Cocer el arroz a fuego medio, removiendo ocasionalmente, durante 10 min.","Incorporar el bogavante y las pinzas reservadas al caldo; cocer hasta que el arroz esté en su punto.","Salpimentar con sal; comprobar que el caldo queda meloso y abundante.","Retirar del fuego y reposar 2 min antes de servir.","Servir bien caliente en platos hondos, repartiendo el bogavante y el caldo a partes iguales."}', 'Arroz caldoso con caldo rojizo intenso y el bogavante partido en el centro del plato.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_040', 'Canelones de rabo de toro', 'pasta_arroces', 'ternera', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, 'horno', 240, 'elaborada', 'invierno', 640, 34, 48, 32, 4, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Rabo de toro troceado","amount":800,"unit":"g"},{"name":"Placas de canelones","amount":16,"unit":"ud"},{"name":"Vino tinto","amount":200,"unit":"ml"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Caldo de carne","amount":400,"unit":"ml"},{"name":"Leche","amount":600,"unit":"ml"},{"name":"Harina de trigo","amount":50,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Queso parmesano","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla, zanahoria, puerro y ajo en trozos finos.","Salpimentar rabo de toro troceado por todas sus caras con sal.","Calentar aceite de oliva en una olla a fuego fuerte.","Dorar el rabo de toro en la olla por todas sus caras hasta que esté bien sellado.","Retirar el rabo de toro de la olla y reservar.","Sofreír la cebolla picada, la zanahoria picada, el puerro picado y el ajo picado en la misma olla a fuego medio.","Devolver el rabo de toro a la olla y añadir vino tinto.","Dejar reducir el vino tinto a fuego medio hasta que se evapore el alcohol.","Añadir caldo de carne, tapar la olla y cocer a fuego suave hasta que la carne se despegue del hueso.","Retirar el rabo de toro de la olla y dejar templar hasta que esté manejable.","Colar la salsa de cocción y reservarla.","Desmigar la carne del rabo de toro descartando huesos y grasa.","Mezclar la carne desmigada con parte de la salsa colada hasta obtener un relleno jugoso.","Llevar a ebullición abundante agua con sal en una olla grande.","Cocer placas de canelones en el agua hirviendo el tiempo indicado en el envase.","Escurrir las placas de canelones y extenderlas sobre un paño limpio sin que se peguen.","Repartir el relleno de carne sobre cada placa y enrollar formando los canelones.","Precalentar el horno a 200 °C.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de trigo a la mantequilla fundida y remover sin parar hasta obtener un roux dorado.","Incorporar leche poco a poco sin dejar de remover hasta que la bechamel espese y esté lisa.","Salpimentar la bechamel al gusto y retirar del fuego.","Rallar queso parmesano.","Colocar los canelones en una fuente de horno en una sola capa.","Cubrir los canelones con la bechamel y espolvorear el queso parmesano rallado por encima.","Hornear la fuente a 200 °C hasta que la superficie quede dorada y gratinada.","Retirar la fuente del horno y servir los canelones bien calientes."}', 'Canelones de rabo de toro con bechamel gratinada y dorada, y el relleno oscuro asomando al cortar.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_041', 'Linguine alle vongole', 'pasta_arroces', 'marisco', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 490, 22, 66, 14, 2, true, false, '{"gluten","moluscos","sulfitos"}', '[{"name":"Linguine","amount":180,"unit":"g"},{"name":"Almejas","amount":500,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Vino blanco","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":35,"unit":"ml"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Guindilla","amount":1,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Sumergir almejas en un bol con agua fría y sal durante 30 min para que suelten la arena.","Pelar y laminar ajo.","Picar perejil fresco fino.","Llevar a ebullición una olla grande con agua abundante y sal.","Cocer linguine en el agua hirviendo hasta que estén al dente, siguiendo el tiempo del envase.","Escurrir las almejas bajo el grifo y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo laminado y guindilla en el aceite caliente hasta que el ajo empiece a dorarse, sin que se queme.","Añadir las almejas escurridas a la sartén y subir el fuego a fuerte.","Verter vino blanco sobre las almejas y tapar la sartén.","Cocer tapado hasta que las almejas se abran, unos 3 min. Retirar y descartar las que no se abran.","Reservar un cazo del agua de cocción antes de escurrir los linguine.","Escurrir los linguine al dente y añadirlos a la sartén con las almejas.","Saltear los linguine con las almejas a fuego fuerte durante 1 min, removiendo para ligar.","Añadir un poco del agua de cocción reservada si la salsa ha espesado demasiado, y remover.","Espolvorear el perejil picado sobre la pasta y servir enseguida."}', 'Linguine con almejas abiertas repartidas por el plato y perejil fresco recién picado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_042', 'Risotto negro con calamar', 'pasta_arroces', 'marisco', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 560, 26, 68, 18, 2, true, true, '{"moluscos","sulfitos","lactosa","pescado"}', '[{"name":"Arroz arborio","amount":160,"unit":"g"},{"name":"Calamar","amount":250,"unit":"g"},{"name":"Tinta de calamar","amount":8,"unit":"g"},{"name":"Caldo de pescado","amount":700,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Limpiar calamar: separar el cuerpo de los tentáculos y retirar la piel, la pluma y las vísceras.","Cortar el cuerpo del calamar en aros de 1 cm; reservar la mitad en un plato aparte para el emplatado.","Picar cebolla en brunoise muy fina.","Picar ajo en brunoise muy fina.","Llevar caldo de pescado a ebullición en una olla; bajar a fuego suave para mantenerlo caliente durante toda la cocción.","Calentar aceite de oliva en una cazuela ancha a fuego fuerte hasta que humee.","Dorar la mitad de los aros de calamar reservados 2 min, hasta que cojan color; retirar y reservar para el emplatado.","Bajar a fuego suave y sofreír la cebolla picada en la misma cazuela hasta que esté transparente.","Añadir el ajo picado y sofreír 1 min más sin que llegue a dorarse.","Añadir la otra mitad de los aros de calamar y saltear a fuego medio hasta que estén opacos.","Añadir arroz arborio y remover a fuego medio 2 min hasta que los granos queden translúcidos y nacarados.","Verter vino blanco y remover sin parar hasta que el alcohol se haya evaporado por completo.","Disolver tinta de calamar en un cucharón de caldo caliente; incorporar la mezcla al arroz y remover.","Añadir el caldo caliente cucharón a cucharón, esperando a que el arroz absorba cada adición antes de añadir la siguiente.","Ajustar el punto de sal y comprobar que el arroz está al dente; retirar la cazuela del fuego.","Añadir mantequilla fría cortada en dados y mantecar con movimientos envolventes hasta obtener una textura cremosa.","Reposar el risotto tapado 1 min antes de servir.","Servir el risotto en platos hondos y colocar los aros de calamar dorados encima."}', 'Risotto de un negro profundo con aros de calamar sellados por encima.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_043', 'Arroz con costra alicantino', 'pasta_arroces', 'pollo', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, 'horno', 90, 'normal', 'all', 600, 32, 62, 24, 4, true, true, '{"huevo"}', '[{"name":"Arroz bomba","amount":320,"unit":"g"},{"name":"Muslo de pollo deshuesado","amount":400,"unit":"g"},{"name":"Costillas de cerdo","amount":300,"unit":"g"},{"name":"Butifarra","amount":200,"unit":"g"},{"name":"Garbanzos cocidos","amount":150,"unit":"g"},{"name":"Caldo de pollo","amount":750,"unit":"ml"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Huevo","amount":300,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar ajo.","Cortar muslo de pollo deshuesado y costillas de cerdo en trozos medianos.","Salpimentar el muslo de pollo y las costillas de cerdo por todos los lados.","Batir huevo en un bol hasta que estén homogéneos. Reservar.","Calentar aceite de oliva en una cazuela apta para horno a fuego fuerte.","Dorar las costillas de cerdo y el muslo de pollo por todas las caras hasta que estén bien dorados.","Incorporar butifarra entera a la cazuela y dorar por todas las caras. Retirar la butifarra y reservar entera.","Sofreír el ajo picado en la misma cazuela a fuego medio hasta que esté dorado.","Añadir tomate triturado y sofreír a fuego medio hasta que pierda el agua y se oscurezca ligeramente.","Disolver azafrán en un poco de caldo de pollo caliente en un vaso pequeño.","Incorporar el resto del caldo de pollo con el azafrán disuelto a la cazuela y llevar a ebullición.","Añadir arroz bomba, la carne dorada y garbanzos cocidos. Repartir bien y rectificar con sal.","Cocer a fuego medio sin tapar hasta que el arroz haya absorbido casi todo el caldo.","Verter el huevo batido de forma uniforme sobre la superficie del arroz.","Colocar la butifarra reservada entera encima del huevo batido.","Introducir la cazuela en el horno a 200 °C y hornear hasta que el huevo cuaje y forme una costra dorada.","Retirar la cazuela del horno y dejar reposar antes de servir.","Servir directamente desde la cazuela repartiendo costra, arroz y carne en cada plato."}', 'Arroz con la costra dorada de huevo cuajado que se rompe al servir, típico de la comarca alicantina.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_044', 'Pappardelle con ragú de pato', 'pasta_arroces', 'pollo', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 150, 'elaborada', 'invierno', 620, 30, 60, 26, 2, true, true, '{"gluten","huevo","sulfitos","lactosa"}', '[{"name":"Muslos de pato","amount":500,"unit":"g"},{"name":"Pappardelle","amount":180,"unit":"g"},{"name":"Tomate triturado","amount":300,"unit":"ml"},{"name":"Vino tinto","amount":150,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Apio","amount":40,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Picar cebolla, zanahoria, apio y ajo en trozos finos.","Salpimentar muslos de pato con sal por ambas caras.","Calentar una cazuela a fuego fuerte sin aceite y colocar los muslos de pato con la piel hacia abajo.","Dorar los muslos hasta que la piel esté dorada y crujiente, unos 8 min, aprovechando su propia grasa.","Dar la vuelta a los muslos y dorar por el otro lado 4 min hasta que estén dorados. Retirar y reservar.","Retirar el exceso de grasa de la cazuela dejando solo una cucharada.","Sofreír la cebolla, la zanahoria, el apio y el ajo picados a fuego medio hasta que estén tiernos.","Devolver los muslos de pato a la cazuela y verter vino tinto.","Reducir el vino a fuego fuerte hasta que casi no quede líquido, unos 5 min.","Añadir tomate triturado, remover y tapar la cazuela parcialmente.","Cocer a fuego muy suave durante 2 horas hasta que la carne se separe fácilmente del hueso.","Retirar los muslos de pato de la cazuela y dejarlos templar sobre una tabla.","Desmigar la carne de pato descartando la piel y los huesos.","Devolver la carne desmigada a la cazuela con el ragú y remover hasta integrar a fuego suave.","Llevar a ebullición una olla grande con agua abundante y sal.","Cocer pappardelle en el agua hirviendo según el tiempo indicado en el envase.","Escurrir la pasta reservando un vaso del agua de cocción.","Añadir la pasta escurrida al ragú y mezclar a fuego suave hasta integrar. Añadir agua de cocción si la salsa ha espesado.","Rallar queso parmesano fino.","Servir la pasta con el ragú en platos hondos y terminar con el parmesano rallado por encima."}', 'Pappardelle en cinta ancha envueltos en la salsa oscura de un ragú de pato.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_045', 'Macarrones con mantequilla, parmesano y salvia crujiente', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 520, 16, 64, 22, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Macarrones","amount":180,"unit":"g"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Queso parmesano","amount":50,"unit":"g"},{"name":"Salvia fresca","amount":10,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Rallar queso parmesano finamente y reservar.","Cocer macarrones en el agua hirviendo según el tiempo indicado en el envase.","Calentar mantequilla en una sartén amplia a fuego medio hasta que tome un tono avellana.","Añadir salvia fresca a la mantequilla y freír hasta que esté crujiente.","Retirar las hojas de salvia y reservar sobre papel absorbente.","Reservar un cucharón del agua de cocción antes de escurrir los macarrones.","Escurrir los macarrones y añadirlos a la sartén con la mantequilla dorada.","Añadir el queso parmesano rallado y un poco del agua de cocción reservada.","Remover a fuego suave hasta que la salsa quede sedosa y envuelva bien la pasta.","Salpimentar con pimienta negra y mezclar.","Servir con las hojas de salvia crujiente por encima y más queso parmesano al gusto."}', 'El plato de pasta más sencillo, elevado con hojas de salvia fritas en un momento.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_046', 'Espaguetis cacio e pepe', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 500, 18, 62, 18, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Espaguetis","amount":180,"unit":"g"},{"name":"Queso pecorino","amount":80,"unit":"g"},{"name":"Pimienta negra en grano","amount":4,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua y sal, usando menos sal de lo habitual.","Machacar pimienta negra en grano en un mortero hasta obtener trozos gruesos, no polvo.","Rallar queso pecorino muy fino con un rallador fino y reservar en un bol.","Tostar la pimienta machacada en sartén amplia y seca a fuego medio hasta que desprenda aroma intenso.","Cocer espaguetis en el agua hirviendo 2 min menos del tiempo indicado en el envase.","Reservar 2 cucharones del agua de cocción en un bol y dejar templar ligeramente.","Añadir el queso pecorino rallado al bol con el agua templada y remover hasta obtener una crema lisa sin grumos.","Escurrir la pasta y añadirla a la sartén con la pimienta tostada a fuego medio.","Añadir un cucharón del agua de cocción reservada y cocer los espaguetis en la sartén hasta que estén al dente.","Retirar la sartén del fuego y añadir la crema de pecorino, moviendo la sartén con energía hasta que emulsione.","Añadir más agua de cocción si la salsa ha espesado demasiado, hasta conseguir una textura sedosa.","Servir enseguida con un golpe extra de pimienta negra recién machacada por encima."}', 'Espaguetis con solo queso, pimienta y agua de cocción: pura textura cremosa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_047', 'Carbonara auténtica con guanciale', 'pasta_arroces', 'cerdo', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 610, 26, 60, 28, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Espaguetis","amount":180,"unit":"g"},{"name":"Guanciale","amount":120,"unit":"g"},{"name":"Yema de huevo","amount":80,"unit":"g"},{"name":"Huevo","amount":60,"unit":"g"},{"name":"Queso pecorino","amount":50,"unit":"g"},{"name":"Pimienta negra","amount":3,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Rallar queso pecorino finamente y reservar.","Cortar guanciale en tiras de unos 5 mm de grosor.","Llevar a ebullición una olla con agua abundante y sal.","Batir yema de huevo y huevo en un bol hasta integrar.","Añadir el queso pecorino rallado y pimienta negra a la mezcla de huevo.","Remover hasta obtener una crema homogénea y reservar.","Cocer espaguetis en el agua hirviendo según el tiempo indicado en el envase.","Dorar el guanciale en sartén amplia sin aceite a fuego medio hasta que suelte la grasa y quede crujiente.","Retirar la sartén del fuego cuando el guanciale esté dorado y crujiente.","Reservar un cucharón del agua de cocción antes de escurrir los espaguetis.","Escurrir los espaguetis y añadirlos a la sartén con el guanciale y su grasa.","Verter la crema de huevo y queso sobre la pasta caliente fuera del fuego.","Remover con rapidez hasta que la salsa cuaje cremosa y sedosa, sin que forme grumos.","Añadir un poco del agua de cocción reservada si la salsa ha quedado demasiado espesa.","Servir enseguida con pimienta negra molida y queso pecorino rallado por encima."}', 'Carbonara auténtica con crema de yema sin nata y panceta de guanciale crujiente.', NULL, '{}', NULL, NULL, NULL, '{}', NULL)
