insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pasta_arroces_048', 'Pasta al limón con parmesano', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 500, 15, 64, 18, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Espaguetis","amount":180,"unit":"g"},{"name":"Limón","amount":80,"unit":"g"},{"name":"Nata para cocinar","amount":80,"unit":"ml"},{"name":"Queso parmesano","amount":50,"unit":"g"},{"name":"Mantequilla","amount":25,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Rallar la piel de limón y reservar la ralladura.","Exprimir el limón ya rallado y reservar el zumo por separado.","Rallar queso parmesano y reservar.","Cocer espaguetis en el agua hirviendo según el tiempo indicado en el envase.","Fundir mantequilla en una sartén amplia a fuego suave hasta que esté líquida.","Añadir nata para cocinar, el zumo de limón reservado y la mitad de la ralladura de limón.","Calentar la salsa a fuego suave removiendo sin parar hasta que esté caliente pero sin llegar a hervir.","Reservar un cucharón del agua de cocción antes de escurrir los espaguetis.","Escurrir los espaguetis y añadirlos a la sartén con la salsa a fuego suave.","Añadir el queso parmesano rallado y un poco del agua de cocción reservada.","Remover sin parar a fuego suave hasta que la salsa esté cremosa y envuelva bien los espaguetis.","Salpimentar con pimienta negra y ajustar de sal al gusto.","Servir de inmediato con el resto de la ralladura de limón esparcida por encima."}', 'Pasta con una salsa cremosa y cítrica de limón; el aroma sube nada más servirla.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_049', 'Pasta alla norma con berenjena y ricotta salada', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 560, 16, 68, 24, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Rigatoni","amount":200,"unit":"g"},{"name":"Berenjena","amount":300,"unit":"g"},{"name":"Tomate triturado","amount":300,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Ricotta salada","amount":40,"unit":"g"},{"name":"Albahaca fresca","amount":6,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar berenjena en dados de 2 cm.","Salar los dados de berenjena con sal y extenderlos sobre un colador.","Reposar la berenjena salada 15 min para que suelte el amargor.","Laminar ajo.","Rallar ricotta salada y reservar.","Secar los dados de berenjena con papel de cocina para eliminar la humedad.","Calentar la mitad de aceite de oliva en sartén a fuego fuerte.","Freír la berenjena por tandas hasta que esté dorada y tierna, sin amontonar la sartén.","Retirar la berenjena frita y reservar sobre papel absorbente.","Llevar a ebullición una olla grande con agua abundante y sal.","Cocer rigatoni en el agua hirviendo hasta que estén al dente, siguiendo el tiempo del envase.","Bajar el fuego a suave en la misma sartén y añadir el resto del aceite de oliva.","Sofreír el ajo laminado a fuego suave hasta que empiece a dorarse, sin que se queme.","Añadir tomate triturado y cocer a fuego suave hasta que la salsa espese.","Escurrir los rigatoni reservando un vaso del agua de cocción.","Incorporar la berenjena reservada a la salsa de tomate y mezclar con cuidado.","Añadir los rigatoni escurridos a la sartén y saltear con la salsa a fuego medio.","Añadir un poco del agua de cocción reservada si la salsa queda demasiado espesa.","Servir en platos hondos con la ricotta salada rallada y albahaca fresca por encima."}', 'Pasta con berenjena frita dorada, salsa de tomate y ricotta salada rallada, el clásico siciliano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_050', 'Spaghetti aglio, olio e peperoncino', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 480, 12, 68, 18, 2, false, true, '{"gluten"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Guindilla seca","amount":3,"unit":"g"},{"name":"Perejil fresco","amount":8,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Laminar ajo fino.","Picar perejil fresco fino.","Cocer espaguetis en el agua hirviendo hasta que estén al dente, según el tiempo del envase.","Calentar aceite de oliva en sartén a fuego suave.","Añadir el ajo laminado al aceite caliente y dorar a fuego suave hasta que esté dorado sin quemarse.","Añadir guindilla seca desmenuzada al aceite y sofreír hasta que aromatice.","Escurrir los espaguetis reservando un vaso del agua de cocción.","Añadir los espaguetis escurridos a la sartén con el aceite aromatizado.","Saltear la pasta a fuego medio hasta que se integre con el aceite, añadiendo agua de cocción si queda seca.","Añadir el perejil picado y mezclar hasta repartir de forma uniforme.","Servir de inmediato en platos calientes."}', 'Espaguetis salteados en aceite de oliva con ajo dorado, guindilla y perejil, sencillos y con punto picante.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_051', 'Gnocchi de patata con mantequilla y salvia', 'pasta_arroces', 'none', 'patatas', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 55, 'normal', 'all', 520, 11, 66, 22, 2, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Patata","amount":500,"unit":"g"},{"name":"Harina de trigo","amount":150,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Salvia fresca","amount":6,"unit":"g"},{"name":"Parmesano","amount":20,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Cocer patata con piel en agua con sal hasta que estén tiernas.","Escurrir las patatas y pelarlas en caliente con cuidado.","Pasar las patatas por un pasapurés sobre una superficie de trabajo enharinada con harina de trigo.","Extender el puré y añadir huevo, sal y nuez moscada.","Mezclar el puré con los añadidos hasta integrarlos de forma homogénea.","Incorporar la harina poco a poco hasta obtener una masa lisa y no pegajosa, sin trabajarla en exceso.","Dividir la masa en porciones y estirar cada una en cilindros de 2 cm de grosor.","Cortar los cilindros en trozos de 2 cm y marcar cada uno con un tenedor.","Llevar a ebullición una olla grande con agua y sal.","Cocer los gnocchi por tandas hasta que floten, unos 2 min por tanda.","Retirar los gnocchi con una espumadera y reservar.","Calentar mantequilla en sartén a fuego medio hasta que tome color avellana.","Añadir salvia fresca a la sartén y dorar las hojas hasta que estén crujientes.","Añadir los gnocchi reservados a la sartén y saltear hasta que se impregnen bien de mantequilla.","Rallar parmesano sobre los gnocchi y servir de inmediato."}', 'Gnocchi de patata caseros salteados en mantequilla avellana con salvia crujiente.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_052', 'Gnocchi de ricotta y espinacas', 'pasta_arroces', 'none', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 480, 18, 40, 26, 2, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Ricotta","amount":250,"unit":"g"},{"name":"Espinacas frescas","amount":200,"unit":"g"},{"name":"Harina de trigo","amount":80,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Parmesano","amount":30,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Nuez moscada","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Escaldar espinacas frescas en el agua hirviendo durante 1 min.","Escurrir las espinacas y presionarlas bien con las manos para eliminar toda el agua.","Picar las espinacas escurridas muy finas sobre la tabla.","Rallar parmesano finamente y reservar.","Mezclar en un bol ricotta, las espinacas picadas, huevo, la mitad del parmesano rallado y nuez moscada.","Añadir harina de trigo y mezclar lo justo hasta obtener una masa homogénea y algo pegajosa.","Enharinar ligeramente las manos y una bandeja.","Coger porciones de masa y formar bolitas de unos 3 cm, depositándolas sobre la bandeja enharinada.","Llevar de nuevo a ebullición el agua de la olla y cocer los gnocchi por tandas hasta que floten, unos 3 min.","Retirar los gnocchi con espumadera y escurrir bien.","Fundir mantequilla en sartén a fuego medio hasta que espume.","Saltear los gnocchi escurridos en la mantequilla durante 1 min hasta que se doren ligeramente.","Servir los gnocchi con el parmesano rallado restante por encima."}', 'Gnocchi caseros de ricotta y espinacas, verdes por dentro y mantecosos por fuera.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_053', 'Pasta con almejas y perejil', 'pasta_arroces', 'marisco', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 490, 24, 62, 14, 2, false, false, '{"gluten","moluscos","sulfitos"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Almejas","amount":400,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Guindilla","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Poner almejas en un bol con agua fría y sal durante 30 min para que suelten la arena.","Cambiar el agua del bol y dejar las almejas en remojo 30 min más.","Llevar a ebullición una olla grande con agua abundante y sal.","Picar ajo fino.","Picar perejil fresco fino y reservar.","Cocer espaguetis en el agua hirviendo según el tiempo del envase, hasta que estén al dente.","Calentar aceite de oliva en sartén a fuego suave.","Sofreír el ajo picado y guindilla en la sartén a fuego suave hasta que el ajo esté dorado sin quemarse.","Escurrir las almejas del agua de remojo y añadirlas a la sartén.","Subir el fuego a fuego fuerte y verter vino blanco.","Tapar la sartén y cocer hasta que las almejas se abran, unos 4 min.","Retirar y desechar las almejas que no se hayan abierto.","Escurrir los espaguetis reservando un vaso del agua de cocción.","Añadir los espaguetis escurridos a la sartén con las almejas y su jugo.","Saltear todo junto a fuego medio 2 min, añadiendo un poco del agua de cocción reservada si la salsa ha espesado.","Añadir el perejil picado y remover para integrar.","Servir de inmediato en platos hondos."}', 'Espaguetis con almejas abiertas al vino blanco, ajo y perejil fresco.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_054', 'Tortellini rellenos en caldo', 'pasta_arroces', 'cerdo', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'invierno', 380, 18, 38, 14, 2, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Tortellini frescos rellenos de carne","amount":300,"unit":"g"},{"name":"Caldo de carne","amount":800,"unit":"ml"},{"name":"Parmesano","amount":20,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Llevar caldo de carne a ebullición en una olla a fuego fuerte.","Rallar parmesano finamente y reservar.","Picar perejil fresco fino y reservar.","Probar el caldo de sal y añadir sal si fuera necesario.","Añadir tortellini frescos rellenos de carne al caldo hirviendo y cocer removiendo con suavidad para que no se peguen.","Retirar del fuego cuando los tortellini floten y estén tiernos.","Repartir los tortellini con el caldo en platos hondos.","Servir con el parmesano rallado y el perejil picado por encima."}', 'Tortellini rellenos de carne servidos flotando en caldo caliente, el clásico reconfortante de invierno.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_055', 'Macarrones gratinados con bechamel y queso', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, 'horno', 45, 'facil', 'all', 580, 19, 60, 26, 4, true, true, '{"gluten","lactosa"}', '[{"name":"Macarrones","amount":350,"unit":"g"},{"name":"Leche","amount":800,"unit":"ml"},{"name":"Harina de trigo","amount":60,"unit":"g"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Queso rallado","amount":180,"unit":"g"},{"name":"Nuez moscada","amount":2,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con función gratinador.","Llevar a ebullición una olla grande con agua y sal.","Cocer macarrones 2 min menos del tiempo indicado en el envase.","Escurrir los macarrones y reservar.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de trigo y remover sin parar 1 min hasta que la mezcla burbujee pero no coja color.","Incorporar leche poco a poco sin dejar de remover con varillas a fuego medio.","Seguir removiendo hasta que la bechamel espese y quede sin grumos.","Añadir nuez moscada y sal al gusto; remover y retirar del fuego.","Mezclar los macarrones escurridos con la bechamel y la mitad del queso rallado.","Volcar la mezcla en una fuente de horno y repartir el queso rallado restante por encima.","Gratinar en el horno 10 min hasta que la superficie esté dorada y burbujeante.","Reposar 3 min fuera del horno antes de servir.","Servir directamente desde la fuente bien caliente."}', 'Macarrones envueltos en bechamel cremosa, gratinados con queso hasta formar una corteza dorada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_056', 'Lasaña de verduras con bechamel', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, 'horno', 70, 'normal', 'all', 440, 15, 48, 20, 4, true, true, '{"gluten","lactosa"}', '[{"name":"Láminas de lasaña","amount":300,"unit":"g"},{"name":"Calabacín","amount":300,"unit":"g"},{"name":"Berenjena","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":200,"unit":"g"},{"name":"Cebolla","amount":120,"unit":"g"},{"name":"Tomate triturado","amount":300,"unit":"ml"},{"name":"Leche","amount":700,"unit":"ml"},{"name":"Harina de trigo","amount":50,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Queso rallado","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar calabacín en dados pequeños.","Cortar berenjena en dados pequeños.","Cortar pimiento rojo en dados pequeños.","Picar cebolla en dados pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté transparente.","Añadir el calabacín, la berenjena y el pimiento en dados y sofreír a fuego medio hasta que estén tiernos.","Añadir tomate triturado y cocer a fuego medio hasta que se integre con las verduras.","Salpimentar el sofrito con sal, remover y reservar fuera del fuego.","Fundir mantequilla en un cazo a fuego suave hasta que esté líquida.","Añadir harina de trigo de golpe y remover sin parar hasta que forme una pasta dorada.","Incorporar leche poco a poco sin dejar de remover a fuego suave.","Cocer la bechamel a fuego suave, removiendo sin parar, hasta que espese y no haya grumos.","Hidratar láminas de lasaña en agua caliente según las instrucciones del envase, si no son precocidas.","Extender una capa fina de bechamel en el fondo de una fuente de horno.","Colocar una capa de láminas de lasaña sobre la bechamel del fondo.","Repartir una parte del sofrito de verduras sobre las láminas.","Cubrir el sofrito con una capa de bechamel.","Repetir las capas de láminas, sofrito y bechamel hasta agotar los ingredientes, terminando con bechamel.","Repartir queso rallado de forma uniforme sobre la última capa de bechamel.","Hornear a 200 °C durante 25 min hasta que la superficie esté dorada.","Reposar la lasaña dentro del horno apagado antes de cortar.","Cortar en porciones y servir directamente desde la fuente."}', 'Capas de pasta, verduras salteadas y bechamel gratinada al horno hasta dorar.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_057', 'Canelones de espinacas y piñones con bechamel', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'all', 480, 17, 44, 25, 4, true, true, '{"gluten","lactosa","frutos_secos"}', '[{"name":"Placas de canelones","amount":16,"unit":"ud"},{"name":"Espinacas frescas","amount":600,"unit":"g"},{"name":"Piñones","amount":50,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Leche","amount":700,"unit":"ml"},{"name":"Harina de trigo","amount":50,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Queso rallado","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Nuez moscada","amount":2,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Cocer placas de canelones según el tiempo del envase hasta que estén tiernas.","Escurrir las placas de canelones y extender sobre un paño limpio para que no se peguen.","Picar cebolla fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir espinacas frescas por tandas hasta que reduzcan y suelten el agua.","Escurrir las espinacas bien, presionando para eliminar el exceso de agua.","Picar las espinacas escurridas en trozos pequeños y reservar.","Tostar piñones en la sartén limpia y seca a fuego medio hasta que se doren ligeramente.","Retirar los piñones de la sartén y reservar.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de trigo de golpe y remover sin parar hasta que se forme una pasta dorada.","Incorporar leche poco a poco sin dejar de remover hasta que no haya grumos.","Cocer la bechamel a fuego suave, removiendo, hasta que espese y tenga cuerpo.","Añadir nuez moscada y sal; remover y retirar del fuego.","Mezclar las espinacas picadas y los piñones tostados con un tercio de la bechamel en un bol.","Distribuir el relleno de espinacas sobre cada placa de canelón.","Enrollar cada placa sobre el relleno para formar los canelones.","Precalentar el horno a 200 °C.","Colocar los canelones en una fuente de horno en una sola capa.","Cubrir los canelones con el resto de la bechamel de forma uniforme.","Repartir queso rallado por encima de la bechamel.","Hornear a 200 °C durante 20 min hasta que la superficie esté dorada y gratinada.","Reposar la fuente fuera del horno 5 min antes de servir.","Servir los canelones racionados directamente desde la fuente."}', 'Canelones rellenos de espinacas y piñones, cubiertos de bechamel y gratinados al horno.', NULL, '{}', true, NULL, NULL, '{}', NULL)
