insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pasta_arroces_058', 'Canelones de pollo asado y jamón', 'pasta_arroces', 'pollo', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, 'horno', 70, 'normal', 'all', 520, 30, 42, 24, 4, true, true, '{"gluten","lactosa"}', '[{"name":"Placas de canelones","amount":16,"unit":"ud"},{"name":"Pechuga de pollo asada","amount":500,"unit":"g"},{"name":"Jamón cocido","amount":120,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Leche","amount":700,"unit":"ml"},{"name":"Harina de trigo","amount":50,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Queso rallado","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Cocer placas de canelones en el agua hirviendo el tiempo indicado en el envase.","Escurrir las placas de canelones y extenderlas sobre un paño limpio sin que se superpongan.","Picar pechuga de pollo asada fino a cuchillo o con picadora.","Picar jamón cocido fino a cuchillo o con picadora.","Picar cebolla fino.","Calentar aceite de oliva en una sartén a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir la pechuga de pollo asada picada y el jamón cocido picado.","Saltear el conjunto a fuego medio hasta que esté bien integrado.","Retirar el relleno del fuego y reservar en un bol.","Fundir mantequilla en un cazo a fuego suave.","Añadir harina de trigo de golpe y remover sin parar hasta que se forme una pasta dorada.","Incorporar leche poco a poco sin dejar de remover hasta que no queden grumos.","Cocer la bechamel a fuego suave, removiendo sin parar, hasta que espese y se despegue del cazo.","Salpimentar la bechamel con sal al gusto y retirar del fuego.","Mezclar el relleno reservado con un tercio de la bechamel hasta que esté bien ligado.","Precalentar el horno a 200 °C con calor arriba y abajo.","Disponer una cucharada generosa de relleno sobre cada placa de canelón y enrollar con cuidado.","Colocar los canelones en una fuente de horno formando una sola capa.","Cubrir los canelones con el resto de la bechamel repartiéndola de forma uniforme.","Repartir queso rallado por encima de la bechamel.","Hornear la fuente a 200 °C durante 20 min hasta que el queso esté dorado y gratinado.","Retirar la fuente del horno y dejar reposar 5 min antes de servir.","Servir los canelones bien calientes directamente desde la fuente."}', 'Canelones rellenos de pollo asado y jamón, cubiertos de bechamel bien gratinada. El clásico de fiesta.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_059', 'Lasaña boloñesa clásica', 'pasta_arroces', 'ternera', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, 'horno', 90, 'normal', 'all', 580, 32, 46, 28, 4, true, true, '{"gluten","lactosa","apio","sulfitos"}', '[{"name":"Láminas de lasaña","amount":300,"unit":"g"},{"name":"Carne picada de ternera","amount":600,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Apio","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":700,"unit":"ml"},{"name":"Vino tinto","amount":80,"unit":"ml"},{"name":"Leche","amount":800,"unit":"ml"},{"name":"Harina de trigo","amount":60,"unit":"g"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Queso rallado","amount":180,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Sal","amount":6,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar cebolla en dados muy finos.","Picar zanahoria en dados muy finos.","Picar apio en dados muy finos.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla picada, la zanahoria picada y el apio picado a fuego medio hasta que estén tiernos.","Añadir carne picada de ternera y dorar a fuego fuerte, deshaciendo los grumos, hasta que pierda el color crudo.","Verter vino tinto y remover hasta que se evapore el alcohol.","Añadir tomate triturado y sal. Tapar y cocer a fuego suave hasta que la boloñesa espese.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de trigo y remover sin parar hasta que la mezcla esté tostada y homogénea.","Incorporar leche poco a poco sin dejar de remover, a fuego medio, hasta que la bechamel espese.","Salpimentar la bechamel y reservar fuera del fuego.","Hidratar láminas de lasaña según las instrucciones del envase si no son precocidas.","Extender una capa fina de bechamel en el fondo de una fuente de horno.","Colocar una capa de láminas de lasaña sobre la bechamel.","Repartir una capa de boloñesa sobre las láminas y cubrir con un poco de bechamel.","Repetir las capas de láminas, boloñesa y bechamel hasta agotar los ingredientes, terminando con bechamel.","Repartir queso rallado uniformemente sobre la última capa de bechamel.","Hornear a 200 °C hasta que la superficie esté dorada.","Reposar la lasaña fuera del horno antes de cortar.","Cortar en porciones y servir."}', 'La lasaña de siempre, con capas de pasta, boloñesa jugosa y bechamel bien gratinada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_060', 'Pasta fría con tomate, mozzarella y albahaca', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'verano', 460, 16, 58, 18, 2, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Fusilli","amount":200,"unit":"g"},{"name":"Tomate cherry","amount":200,"unit":"g"},{"name":"Mozzarella","amount":150,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua y sal.","Cocer fusilli hasta que estén al dente, siguiendo el tiempo indicado en el envase.","Cortar tomate cherry por la mitad.","Cortar mozzarella en dados de bocado.","Escurrir los fusilli y enfriarlos bajo el grifo con agua fría hasta que estén completamente fríos.","Mezclar en un bol los fusilli fríos, los tomates cherry y la mozzarella.","Aliñar con aceite de oliva, vinagre balsámico y sal.","Remover bien hasta que el aliño cubra todos los ingredientes de forma uniforme.","Reposar el bol tapado en la nevera hasta que los sabores se integren.","Añadir albahaca fresca troceada a mano justo antes de servir y servir en plato."}', 'Pasta fría con tomate cherry, mozzarella y albahaca fresca, ideal para los días de calor.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_061', 'Ensalada de pasta con atún y aceitunas', 'pasta_arroces', 'pescado_azul', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 460, 24, 54, 16, 2, true, true, '{"gluten","pescado","sulfitos"}', '[{"name":"Fusilli","amount":200,"unit":"g"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Aceitunas negras","amount":40,"unit":"g"},{"name":"Tomate cherry","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua y sal.","Cocer fusilli en el agua hirviendo hasta que estén al dente, según el tiempo del envase.","Cortar tomate cherry por la mitad.","Cortar pimiento rojo en dados pequeños.","Laminar cebolla morada en juliana fina.","Escurrir atún en conserva y desmigar con un tenedor.","Escurrir los fusilli y enfriar bajo el grifo con agua fría hasta que estén completamente fríos.","Mezclar en un bol los fusilli fríos, el atún, aceitunas negras, el tomate cherry, el pimiento rojo y la cebolla morada.","Aliñar con aceite de oliva y vinagre, y remover hasta integrar bien el aliño."}', 'Ensalada de pasta fría con atún, aceitunas y verduras crujientes, un clásico de tupper.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_062', 'Trofie al pesto genovés', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 540, 15, 68, 24, 2, true, true, '{"gluten","frutos_secos","lactosa"}', '[{"name":"Trofie","amount":200,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Judía verde","amount":60,"unit":"g"},{"name":"Albahaca fresca","amount":60,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Parmesano","amount":40,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en dados pequeños.","Limpiar judía verde y cortar en trozos de unos 3 cm.","Llevar a ebullición una olla grande con agua abundante y sal.","Añadir ajo al vaso de la batidora junto con albahaca fresca, piñones, parmesano y aceite de oliva.","Triturar hasta obtener un pesto homogéneo.","Añadir la patata y la judía verde al agua hirviendo y cocer 8 min.","Añadir trofie al agua con la patata y la judía verde y cocer el tiempo indicado en el envase.","Reservar un cazo del agua de cocción antes de escurrir la pasta y las verduras.","Escurrir la pasta junto con la patata y la judía verde.","Mezclar en un bol amplio la pasta, la patata y la judía verde con el pesto hasta cubrir bien.","Añadir agua de cocción a cucharadas si el pesto ha quedado demasiado espeso, hasta conseguir la textura deseada.","Servir templado con parmesano rallado por encima."}', 'Trofie ligures con pesto de albahaca, piñones y parmesano, con patata y judía verde como manda la tradición.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_063', 'Rigatoni con salchicha y tomate', 'pasta_arroces', 'cerdo', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 560, 22, 62, 22, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Rigatoni","amount":200,"unit":"g"},{"name":"Salchicha fresca italiana","amount":250,"unit":"g"},{"name":"Tomate triturado","amount":300,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Retirar la piel de salchicha fresca italiana y desmenuzar la carne con las manos en trozos pequeños.","Picar cebolla en trozos finos.","Picar ajo fino.","Calentar aceite de oliva en sartén a fuego medio-alto.","Añadir la carne de salchicha desmenuzada y dorar hasta que pierda el color rosado, deshaciendo los grumos.","Añadir la cebolla picada y el ajo picado y sofreír a fuego medio hasta que la cebolla esté transparente.","Verter vino blanco y remover hasta que se evapore el alcohol.","Añadir tomate triturado y orégano. Remover y tapar.","Cocer la salsa a fuego suave hasta que espese.","Llevar a ebullición una olla con agua abundante y sal.","Cocer rigatoni en el agua hirviendo según el tiempo indicado en el envase.","Escurrir los rigatoni y añadirlos a la sartén con la salsa.","Mezclar la pasta con la salsa a fuego medio hasta que queden bien integradas.","Servir en platos hondos."}', 'Rigatoni con una salsa rústica de tomate y salchicha dorada, con un fondo de vino blanco.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_064', 'Penne all''arrabbiata', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 440, 12, 66, 14, 2, false, true, '{"gluten"}', '[{"name":"Penne","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":300,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Guindilla","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua y sal.","Picar ajo fino.","Desmenuzar guindilla en trozos pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado con la guindilla desmenuzada hasta que el ajo se dore ligeramente.","Añadir tomate triturado y sal a la sartén.","Cocer a fuego suave hasta que la salsa espese y el color rojo se intensifique.","Cocer penne en el agua hirviendo según el tiempo indicado en el envase.","Picar perejil fresco fino.","Escurrir la pasta reservando un vaso del agua de cocción.","Saltear la pasta escurrida en la sartén con la salsa a fuego medio durante 1 min.","Añadir un poco del agua de cocción reservada si la salsa ha quedado demasiado espesa.","Añadir el perejil picado, mezclar y servir de inmediato."}', 'Penne con salsa de tomate bien picante, ajo y guindilla, el clásico romano con carácter.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_065', 'Pasta con boletus y nata', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 580, 14, 60, 28, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Tagliatelle","amount":200,"unit":"g"},{"name":"Boletus","amount":200,"unit":"g"},{"name":"Nata para cocinar","amount":200,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Limpiar boletus con un paño húmedo para retirar la tierra.","Laminar los boletus limpios.","Picar cebolla finamente.","Picar ajo finamente.","Picar perejil fresco finamente y reservar.","Llevar a ebullición una olla grande con agua abundante y sal.","Cocer tagliatelle en el agua hirviendo según el tiempo indicado en el envase.","Fundir mantequilla en sartén a fuego medio.","Sofreír la cebolla picada y el ajo picado en la sartén hasta que estén tiernos.","Añadir los boletus laminados y saltear a fuego fuerte hasta que suelten el agua y se doren.","Verter nata para cocinar sobre los boletus y remover para integrar.","Cocer la salsa a fuego suave hasta que espese ligeramente.","Escurrir la pasta cocida y añadirla a la sartén con la salsa.","Mezclar bien la pasta con la salsa hasta que quede bien impregnada.","Añadir el perejil picado y servir de inmediato."}', 'Pasta en salsa cremosa de boletus con un fondo de mantequilla y ajo.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_066', 'Farfalle con salmón y eneldo', 'pasta_arroces', 'pescado_azul', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 560, 26, 58, 24, 2, true, true, '{"gluten","lactosa","pescado"}', '[{"name":"Farfalle","amount":200,"unit":"g"},{"name":"Salmón fresco","amount":200,"unit":"g"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Eneldo fresco","amount":6,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Picar cebolla en trozos finos.","Cortar salmón fresco en dados de 2 cm, retirando piel y espinas.","Picar eneldo fresco fino y reservar.","Llevar a ebullición una olla grande con agua y sal.","Cocer farfalle en el agua hirviendo según el tiempo del envase, hasta que estén al dente.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté transparente.","Añadir los dados de salmón y saltear a fuego medio-alto durante 2 min, sin remover en exceso para no deshacerlos.","Verter nata para cocinar en la sartén y salpimentar con pimienta negra.","Cocer la salsa a fuego suave hasta que espese ligeramente.","Escurrir la pasta y añadirla a la sartén con la salsa.","Mezclar con cuidado hasta que la pasta quede bien impregnada de salsa.","Añadir el eneldo picado, mezclar y servir de inmediato."}', 'Lazos de pasta en salsa cremosa de salmón con un toque fresco de eneldo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_067', 'Pasta con gambas y ajo', 'pasta_arroces', 'marisco', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 460, 26, 56, 14, 2, true, true, '{"gluten","marisco"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Gambas peladas","amount":250,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Guindilla","amount":2,"unit":"g"},{"name":"Perejil fresco","amount":8,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua y sal.","Cocer espaguetis en el agua hirviendo según el tiempo del envase.","Laminar ajo en rodajas finas.","Picar perejil fresco fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo laminado con guindilla hasta que el ajo se dore ligeramente.","Añadir gambas peladas y saltear a fuego fuerte hasta que cambien de color.","Escurrir los espaguetis reservando un vaso del agua de cocción.","Añadir los espaguetis escurridos a la sartén y saltear a fuego medio.","Añadir el agua de cocción reservada poco a poco si la pasta ha quedado seca.","Añadir el perejil picado, mezclar y servir de inmediato."}', 'Pasta salteada con gambas rosadas, ajo dorado y un toque de guindilla.', NULL, '{}', NULL, NULL, NULL, '{}', NULL)
