) values
  ('pasta_arroces_068', 'Espaguetis con almejas (vongole)', 'pasta_arroces', 'marisco', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 480, 24, 62, 14, 2, false, false, '{"gluten","moluscos","sulfitos"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Almejas","amount":400,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vino blanco","amount":80,"unit":"ml"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Guindilla","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Poner almejas en un bol con agua fría y sal durante 60 min para que suelten la arena.","Cambiar el agua del bol a mitad del remojo para eliminar mejor la arena.","Llevar a ebullición una olla grande con agua abundante y sal.","Picar ajo fino.","Picar perejil fresco fino y reservar.","Cocer espaguetis en la olla con agua hirviendo hasta que estén al dente, siguiendo el tiempo del envase.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado con guindilla a fuego suave hasta que el ajo esté dorado sin quemarse.","Escurrir las almejas y añadirlas a la sartén; subir el fuego a fuego fuerte.","Verter vino blanco y tapar la sartén hasta que las almejas se abran.","Retirar y desechar las almejas que no se hayan abierto.","Escurrir los espaguetis reservando un vaso del agua de cocción.","Añadir los espaguetis escurridos a la sartén con las almejas y su jugo.","Saltear a fuego fuerte durante 2 min; añadir un poco del agua de cocción reservada si la salsa espesa demasiado.","Añadir el perejil picado, remover y servir de inmediato."}', 'Espaguetis vongole con almejas abiertas al vino blanco y ajo, con las conchas entre la pasta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_069', 'Ravioli de queso y espinacas con mantequilla', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 540, 20, 52, 26, 2, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina de trigo","amount":250,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Ricotta","amount":200,"unit":"g"},{"name":"Espinacas frescas","amount":150,"unit":"g"},{"name":"Parmesano","amount":40,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Salvia fresca","amount":4,"unit":"g"},{"name":"Nuez moscada","amount":2,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Mezclar harina de trigo con 2 unidades de huevo en un bol hasta integrar.","Amasar la mezcla sobre la superficie de trabajo hasta obtener una masa lisa y elástica.","Envolver la masa en film y dejar reposar a temperatura ambiente.","Llevar a ebullición una olla con agua y sal a fuego fuerte.","Escaldar espinacas frescas en el agua hirviendo durante 1 min.","Escurrir las espinacas y presionar bien con las manos para eliminar el exceso de agua.","Picar las espinacas escurridas fino sobre la tabla.","Rallar parmesano fino.","Mezclar en un bol ricotta, las espinacas picadas, el parmesano rallado, 1 unidad de huevo y nuez moscada.","Salpimentar el relleno con sal y remover hasta obtener una mezcla homogénea.","Dividir la masa reposada en 2 partes y estirar cada una con rodillo hasta obtener láminas finas.","Repartir montoncitos de relleno sobre una lámina dejando 3 cm entre cada uno.","Cubrir con la segunda lámina de masa y presionar alrededor de cada montón de relleno para sellar.","Cortar los ravioli con un cortapastas y reservar sobre una superficie enharinada.","Llevar a ebullición una olla grande con agua abundante y sal a fuego fuerte.","Cocer los ravioli en el agua hirviendo por tandas hasta que floten, unos 3 min por tanda.","Retirar los ravioli con una espumadera y reservar.","Calentar mantequilla en sartén a fuego medio hasta que tome color avellana.","Añadir salvia fresca a la mantequilla y dorar las hojas 1 min hasta que estén crujientes.","Añadir los ravioli reservados a la sartén y saltear con cuidado 1 min para que se impregnen.","Servir los ravioli en plato y acabar con parmesano rallado por encima."}', 'Ravioli caseros rellenos de ricotta y espinacas, salteados en mantequilla de salvia.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_070', 'Ravioli de calabaza con mantequilla y salvia', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 520, 14, 58, 24, 2, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina de trigo","amount":250,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Parmesano","amount":40,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Salvia fresca","amount":4,"unit":"g"},{"name":"Nuez moscada","amount":2,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar calabaza en trozos de tamaño similar.","Colocar los trozos de calabaza en una bandeja y hornear a 200 °C hasta que estén tiernos.","Disponer harina de trigo en forma de volcán sobre la superficie de trabajo.","Cascar 2 huevo en el centro del volcán de harina.","Mezclar los huevos con la harina desde el centro hacia fuera hasta integrar.","Amasar la masa sobre la superficie hasta que esté lisa y elástica.","Envolver la masa en film transparente y dejar reposar.","Retirar la calabaza del horno cuando esté tierna y dejar templar.","Rallar parmesano finamente.","Triturar la calabaza templada con el parmesano rallado, 1 huevo, nuez moscada y sal hasta obtener un puré espeso.","Dividir la masa en 2 porciones y estirar cada una con el rodillo hasta obtener láminas finas.","Repartir montoncitos de relleno sobre una lámina, dejando espacio entre ellos.","Cubrir con la segunda lámina y presionar alrededor de cada montón de relleno para sellar bien.","Cortar los ravioli con un cortapastas o cuchillo y reservar en una superficie enharinada.","Llevar a ebullición una olla grande con agua abundante y sal.","Cocer los ravioli por tandas cuando el agua rompa a hervir, hasta que floten.","Retirar los ravioli con espumadera y reservar.","Calentar mantequilla en sartén a fuego medio hasta que tome color avellana.","Añadir salvia fresca a la mantequilla y dorar las hojas hasta que estén crujientes.","Añadir los ravioli reservados a la sartén y saltear con cuidado hasta que se impregnen.","Servir los ravioli con parmesano rallado por encima."}', 'Ravioli caseros rellenos de calabaza asada, con mantequilla dorada y salvia crujiente.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_071', 'Fettuccine Alfredo', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 680, 18, 62, 38, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Fettuccine","amount":200,"unit":"g"},{"name":"Mantequilla","amount":80,"unit":"g"},{"name":"Parmesano","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Rallar parmesano finamente y reservar.","Llevar a ebullición una olla grande con agua y sal.","Cocer fettuccine en el agua hirviendo según el tiempo del envase, hasta que estén al dente.","Fundir mantequilla en sartén amplia a fuego suave, sin que se dore.","Añadir nata para cocinar a la sartén y calentar a fuego suave hasta que humee, sin que llegue a hervir.","Escurrir los fettuccine reservando un vaso del agua de cocción.","Añadir los fettuccine escurridos a la sartén con la salsa y mezclar a fuego suave.","Retirar la sartén del fuego y añadir el parmesano rallado poco a poco, removiendo sin parar.","Aligerar la salsa con el agua de cocción reservada, cucharada a cucharada, hasta obtener una textura cremosa.","Añadir pimienta negra y sal, y remover para integrar.","Servir de inmediato en platos hondos con un poco más de parmesano rallado por encima."}', 'Fettuccine envueltas en una salsa cremosa de mantequilla y parmesano, sencilla y contundente.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_072', 'Pasta con brócoli, ajo y anchoas', 'pasta_arroces', 'pescado_azul', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 480, 20, 56, 20, 2, false, true, '{"gluten","pescado","lactosa"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Brócoli","amount":250,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Anchoas en aceite","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Queso parmesano","amount":20,"unit":"g"}]'::jsonb, '{"Lavar brócoli y separarlo en arbolitos pequeños.","Pelar ajo y laminarlo fino.","Picar anchoas en aceite en trozos pequeños.","Llevar a ebullición una olla grande con agua y sal.","Cocer el brócoli en el agua hirviendo 3 min hasta que esté al dente.","Retirar el brócoli con una espumadera y reservar sin tirar el agua.","Cocer espaguetis en la misma agua según el tiempo indicado en el envase.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo laminado hasta que se dore ligeramente.","Añadir las anchoas picadas y remover hasta que se deshagan en el aceite.","Añadir el brócoli reservado y saltear 2 min aplastando ligeramente algunos arbolitos.","Escurrir los espaguetis reservando un cazo del agua de cocción.","Añadir los espaguetis a la sartén con un poco del agua de cocción reservada.","Saltear a fuego medio hasta que la salsa ligue y cubra bien la pasta.","Rallar queso parmesano sobre la pasta y servir de inmediato."}', 'Espaguetis con brócoli, ajo dorado y anchoas deshechas en el aceite, verde intenso con el punto salado de la anchoa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_073', 'Arroz con leche de coco y pollo al curry', 'pasta_arroces', 'pollo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 560, 32, 54, 24, 2, true, true, '{}', '[{"name":"Arroz basmati","amount":160,"unit":"g"},{"name":"Pechuga de pollo","amount":300,"unit":"g"},{"name":"Leche de coco","amount":200,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jengibre","amount":10,"unit":"g"},{"name":"Curry en polvo","amount":8,"unit":"g"},{"name":"Caldo de pollo","amount":200,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Cilantro fresco","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en dados de 3 cm.","Pelar y picar cebolla finamente.","Pelar y picar ajo finamente.","Pelar y picar jengibre finamente.","Calentar aceite de oliva en una cazuela ancha a fuego medio.","Sofreír la cebolla, el ajo y el jengibre hasta que la cebolla esté transparente.","Añadir los dados de pechuga y dorar por todos los lados hasta que estén sellados.","Añadir curry en polvo y remover sin parar hasta que suelte aroma.","Incorporar arroz basmati y remover hasta que los granos queden impregnados de las especias.","Verter leche de coco y caldo de pollo y remover para integrar.","Llevar a ebullición a fuego fuerte.","Bajar a fuego suave, tapar y cocer hasta que el arroz esté tierno y haya absorbido el líquido.","Retirar del fuego y dejar reposar tapado.","Picar cilantro fresco finamente.","Espolvorear el cilantro picado sobre el arroz y servir directamente de la cazuela."}', 'Arroz jugoso en salsa de curry amarillo y leche de coco con pollo tierno, aroma que llena la cocina.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_074', 'Arroz meloso de setas', 'pasta_arroces', 'none', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 420, 12, 66, 12, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Arroz","amount":160,"unit":"g"},{"name":"Setas variadas","amount":300,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de verduras","amount":600,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Queso parmesano","amount":20,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo para retirar la tierra.","Laminar las setas limpias.","Pelar y picar cebolla finamente.","Pelar y picar ajo finamente.","Picar perejil finamente y reservar.","Rallar queso parmesano y reservar.","Calentar caldo de verduras en un cazo a fuego suave hasta que esté caliente; mantener a fuego mínimo.","Calentar aceite de oliva en una cazuela ancha a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté transparente.","Añadir el ajo picado y remover 1 min hasta que desprenda aroma.","Añadir las setas laminadas y saltear a fuego fuerte hasta que suelten el agua y se doren.","Añadir arroz y remover hasta que se impregne bien del sofrito.","Verter vino blanco y remover a fuego fuerte hasta que se evapore por completo.","Añadir un cazo de caldo caliente y remover hasta que el arroz lo absorba casi por completo.","Seguir añadiendo caldo caliente cazo a cazo, removiendo con frecuencia, hasta que el arroz esté meloso.","Retirar la cazuela del fuego y añadir el queso parmesano rallado.","Remover con energía hasta integrar el queso y obtener una textura cremosa.","Servir de inmediato en platos hondos y espolvorear con el perejil picado."}', 'Arroz cremoso de setas variadas sin nata, todo el sabor viene del caldo bien reducido.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_075', 'Arroz con costillas y verduras', 'pasta_arroces', 'cerdo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 55, 'normal', 'all', 562, 30, 52, 26, 2, true, true, '{}', '[{"name":"Arroz","amount":160,"unit":"g"},{"name":"Costillas de cerdo troceadas","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Judías verdes","amount":100,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de carne","amount":500,"unit":"ml"},{"name":"Pimentón dulce","amount":4,"unit":"g"}]'::jsonb, '{"Secar costillas de cerdo troceadas con papel de cocina y salpimentar.","Cortar pimiento rojo en tiras de 2-3 cm.","Cortar zanahoria en rodajas y judías verdes en trozos de 3 cm.","Picar ajo fino.","Calentar aceite de oliva en una cazuela ancha a fuego fuerte.","Dorar las costillas de cerdo troceadas por todos los lados hasta que estén bien selladas y reservar.","Sofreír el ajo picado, el pimiento rojo y la zanahoria en la misma cazuela a fuego medio hasta que empiecen a ablandarse.","Añadir tomate triturado y pimentón dulce y remover a fuego medio.","Incorporar las costillas reservadas a la cazuela y añadir caldo de carne.","Llevar a ebullición a fuego fuerte.","Tapar y cocer a fuego suave hasta que las costillas estén tiernas.","Añadir arroz y las judías verdes y remover para distribuir bien.","Cocer sin tapar a fuego medio hasta que el arroz esté en su punto y haya absorbido el caldo.","Retirar del fuego y dejar reposar 2 min antes de servir.","Servir directamente de la cazuela en platos hondos."}', 'Arroz meloso con costilla dorada y verduras de temporada, carne asomando entre el grano suelto.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_076', 'Arroz caldoso de marisco', 'pasta_arroces', 'marisco', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', 'pasta_arroces_019', NULL, 40, 'normal', 'all', 438, 28, 50, 14, 2, false, false, '{"marisco","moluscos","pescado"}', '[{"name":"Arroz","amount":160,"unit":"g"},{"name":"Gambas","amount":150,"unit":"g"},{"name":"Mejillones","amount":150,"unit":"g"},{"name":"Rape","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":550,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"}]'::jsonb, '{"Limpiar mejillones raspando las conchas y retirando las barbas.","Cortar rape en trozos de bocado.","Pelar gambas, reservando 2 enteras para el emplatado.","Picar ajo y cebolla fino.","Calentar aceite de oliva en una cazuela ancha a fuego medio.","Sofreír la cebolla y el ajo hasta que estén transparentes.","Añadir tomate triturado y pimentón dulce y sofreír 2 min removiendo.","Añadir arroz y remover 1 min hasta que se impregne del sofrito.","Verter caldo de pescado y llevar a ebullición a fuego fuerte.","Cocer a fuego medio 10 min removiendo de vez en cuando.","Añadir el rape y las gambas y cocer 3 min a fuego medio.","Añadir los mejillones y cocer 2-3 min hasta que se abran y el arroz esté en su punto.","Retirar del fuego y dejar reposar 2 min.","Servir en platos hondos colocando las gambas enteras reservadas encima."}', 'Arroz caldoso con gambas, mejillones y rape en un caldo intenso de pescado, con piezas de marisco enteras.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_077', 'Paella mixta', 'pasta_arroces', 'pollo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 60, 'elaborada', 'all', 518, 32, 48, 22, 2, false, false, '{"marisco","moluscos"}', '[{"name":"Arroz","amount":160,"unit":"g"},{"name":"Muslos de pollo deshuesados","amount":200,"unit":"g"},{"name":"Gambas","amount":100,"unit":"g"},{"name":"Mejillones","amount":100,"unit":"g"},{"name":"Judía verde plana","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Tomate rallado","amount":60,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Azafrán","amount":0.3,"unit":"g"},{"name":"Caldo de pollo y marisco","amount":500,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"}]'::jsonb, '{"Cortar muslos de pollo deshuesados en trozos de unos 3 cm.","Cortar pimiento rojo en tiras y judía verde plana en trozos de 3 cm.","Picar ajo fino.","Calentar caldo de pollo y marisco en un cazo a fuego suave hasta que esté caliente; disolver azafrán en el caldo.","Calentar aceite de oliva en la paellera a fuego fuerte.","Dorar los trozos de pollo por todos los lados hasta que estén dorados; retirar y reservar.","Sofreír el pimiento rojo y la judía verde en la misma paellera a fuego medio hasta que estén ligeramente tiernos.","Añadir el ajo picado y tomate rallado; sofreír hasta que el tomate pierda el agua y la mezcla espese.","Añadir pimentón dulce y remover de inmediato para que no se queme.","Incorporar arroz y remover para que se impregne del sofrito; repartirlo en una capa uniforme.","Verter el caldo caliente con el azafrán y devolver el pollo a la paellera; llevar a ebullición fuerte.","Bajar a fuego medio y cocer sin remover.","Repartir gambas y mejillones sobre el arroz de forma uniforme.","Subir a fuego fuerte para lograr el socarrat en el fondo; vigilar que no se queme.","Retirar la paellera del fuego y tapar con un paño limpio; dejar reposar.","Servir la paella directamente desde la paellera."}', 'Paella con pollo dorado y marisco repartidos sobre el socarrat, el clásico de fin de semana.', NULL, '{}', NULL, NULL, NULL, '{}', NULL)
