insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pasta_arroces_078', 'Arroz al horno con costilla y garbanzos', 'pasta_arroces', 'cerdo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'all', 580, 31, 57, 25, 2, true, true, '{}', '[{"name":"Arroz","amount":160,"unit":"g"},{"name":"Costillas de cerdo","amount":250,"unit":"g"},{"name":"Garbanzos cocidos","amount":200,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Cabeza de ajos","amount":1,"unit":"ud"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Caldo de carne","amount":450,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar patata y laminarla en rodajas de 5 mm.","Cortar tomate en rodajas.","Secar costillas de cerdo con papel de cocina y salpimentar.","Calentar aceite de oliva en una cazuela apta para horno a fuego fuerte.","Dorar las costillas de cerdo por todos los lados hasta que estén bien selladas. Reservar.","Dorar las rodajas de patata en la misma cazuela a fuego medio, 2 min por cada lado.","Añadir pimentón dulce y remover 20 segundos hasta que se integre con el aceite.","Disolver azafrán en caldo de carne caliente y verter en la cazuela.","Llevar a ebullición a fuego fuerte.","Añadir arroz y garbanzos cocidos y remover con cuidado para repartir en capa uniforme.","Colocar las costillas reservadas, las rodajas de tomate y cabeza de ajos entera sobre el arroz.","Introducir la cazuela en el horno y hornear a 200 °C hasta que el arroz esté en su punto y la superficie dorada.","Retirar del horno y dejar reposar la cazuela tapada.","Servir directamente en la cazuela."}', 'Arroz al horno con costra dorada por arriba, costilla y garbanzos, típico de domingo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_079', 'Risotto de espárragos verdes', 'pasta_arroces', 'none', 'arroz', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 430, 11, 56, 18, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Arroz arborio","amount":180,"unit":"g"},{"name":"Espárragos verdes","amount":250,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Caldo de verduras","amount":500,"unit":"ml"}]'::jsonb, '{"Lavar espárragos verdes y retirar la parte dura del tallo.","Cortar los espárragos en trozos de 2 cm, reservando las puntas aparte.","Pelar cebolla y picarla en dados pequeños.","Rallar queso parmesano y reservar.","Calentar caldo de verduras en un cazo a fuego suave hasta que humee; mantener caliente durante toda la cocción.","Fundir la mitad de mantequilla en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir los tallos de espárrago y saltear durante 2 min.","Añadir arroz arborio y remover hasta que los granos estén nacarados.","Verter vino blanco y remover hasta que el arroz lo absorba por completo.","Añadir el caldo caliente cucharón a cucharón, removiendo sin parar y esperando a que se absorba antes de añadir el siguiente.","Añadir las puntas de espárrago reservadas y continuar incorporando el caldo cucharón a cucharón, removiendo sin parar.","Retirar la olla del fuego y añadir la mantequilla restante y el queso parmesano rallado.","Remover con energía hasta integrar la mantequilla y el queso parmesano y conseguir una textura cremosa.","Tapar la olla y dejar reposar 2 min.","Servir el risotto en platos hondos calientes."}', 'Risotto verde vivo de espárragos, con la cremosidad clásica de un risotto bien trabajado.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_080', 'Risotto de gambas y limón', 'pasta_arroces', 'marisco', 'arroz', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 456, 26, 56, 14, 2, true, false, '{"marisco","lactosa","sulfitos","pescado"}', '[{"name":"Arroz arborio","amount":180,"unit":"g"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Caldo de pescado","amount":500,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Picar cebolla en trozos muy finos.","Rallar la piel de limón y exprimir su zumo; reservar por separado.","Calentar caldo de pescado en un cazo a fuego suave hasta que rompa a hervir; mantener caliente.","Fundir mantequilla en una olla a fuego medio.","Sofreír la cebolla picada en la olla hasta que esté transparente.","Añadir arroz arborio y remover hasta que los granos estén nacarados.","Verter vino blanco y remover hasta que el arroz lo absorba por completo.","Añadir el caldo caliente cucharón a cucharón, removiendo sin parar y esperando a que se absorba antes de añadir el siguiente.","Salpimentar gambas peladas cuando falten 5 min para que el arroz esté al dente.","Calentar sartén a fuego fuerte y saltear las gambas 1 min por cada lado hasta que estén rosadas; reservar.","Retirar la olla del fuego cuando el arroz esté al dente y cremoso.","Añadir la ralladura de limón al arroz y remover.","Añadir el zumo de limón al arroz y remover hasta integrar.","Incorporar las gambas salteadas al arroz y mezclar con cuidado.","Picar perejil fino y espolvorear sobre el risotto; servir de inmediato."}', 'Risotto rosado de gambas con un toque cítrico de limón que lo levanta todo.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_081', 'Arroz tres delicias casero', 'pasta_arroces', 'huevo', 'arroz', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 432, 17, 56, 15, 2, true, true, '{"huevo","soja"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Salsa de soja","amount":15,"unit":"ml"}]'::jsonb, '{"Llevar a ebullición agua con sal en una olla a fuego fuerte.","Cocer arroz en el agua hirviendo según el tiempo del paquete.","Pelar zanahoria y cortarla en dados pequeños.","Cortar jamón cocido en dados pequeños del mismo tamaño que la zanahoria.","Batir huevo en un bol hasta que estén homogéneos.","Escurrir el arroz cocido y extenderlo en una bandeja hasta que enfríe y quede suelto.","Calentar aceite de oliva en sartén a fuego medio.","Verter el huevo batido y cuajar en tortilla fina sin remover, hasta que esté cuajada.","Retirar la tortilla de la sartén y dejar templar sobre una tabla.","Cortar la tortilla en tiras finas y reservar.","Calentar el resto del aceite de oliva en la misma sartén a fuego fuerte.","Saltear la zanahoria en dados a fuego fuerte durante 2 min, hasta que empiece a estar tierna.","Añadir guisantes y el jamón cocido en dados y saltear 2 min removiendo.","Añadir el arroz frío y saltear a fuego fuerte 3 min removiendo sin parar hasta que esté suelto y caliente.","Añadir salsa de soja y las tiras de tortilla, mezclar con suavidad y servir de inmediato."}', 'Arroz salteado colorido con tortilla, guisantes, zanahoria y jamón, mejor que el del chino de siempre.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_082', 'Arroz con pato', 'pasta_arroces', 'pollo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 75, 'elaborada', 'all', 600, 34, 52, 28, 2, false, true, '{"sulfitos"}', '[{"name":"Arroz","amount":160,"unit":"g"},{"name":"Muslos de pato","amount":300,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Zanahoria","amount":50,"unit":"g"},{"name":"Puerro","amount":50,"unit":"g"},{"name":"Vino tinto","amount":60,"unit":"ml"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Caldo de carne","amount":500,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Secar muslos de pato con papel de cocina y salpimentar por ambos lados.","Picar cebolla, zanahoria y puerro en dados pequeños.","Calentar aceite de oliva en una cazuela ancha a fuego fuerte.","Dorar los muslos de pato por el lado de la piel hasta que estén dorados y hayan soltado grasa, unos 6 min.","Dar la vuelta a los muslos de pato y dorar 3 min por el otro lado.","Retirar los muslos de pato y reservar en un plato.","Retirar el exceso de grasa de la cazuela dejando solo una fina capa.","Sofreír la cebolla, la zanahoria y el puerro a fuego medio hasta que estén tiernos.","Añadir tomate triturado y sofreír a fuego medio hasta que pierda el agua y se concentre.","Verter vino tinto y remover hasta que se evapore el alcohol y reduzca a la mitad.","Incorporar los muslos de pato reservados, caldo de carne y tomillo.","Tapar la cazuela y cocer a fuego suave hasta que la carne se separe fácilmente del hueso.","Retirar los muslos de pato de la cazuela y dejar templar sobre un plato.","Deshuesar los muslos de pato y desmenuzar la carne en trozos irregulares.","Incorporar la carne desmenuzada de nuevo a la cazuela y remover para integrar.","Añadir arroz y remover para mezclar bien con el sofrito y la carne.","Cocer a fuego medio sin tapar, removiendo ocasionalmente, hasta que el arroz esté en su punto.","Retirar la cazuela del fuego y dejar reposar tapado.","Servir el arroz con pato directamente de la cazuela en platos hondos."}', 'Arroz meloso con carne de pato deshecha entre el grano dorado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_083', 'Fideos a la cazuela con costilla', 'pasta_arroces', 'cerdo', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 560, 30, 56, 24, 2, true, true, '{"gluten"}', '[{"name":"Fideos gordos","amount":200,"unit":"g"},{"name":"Costillas de cerdo troceadas","amount":300,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Caldo de carne","amount":500,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"}]'::jsonb, '{"Salpimentar costillas de cerdo troceadas por todos los lados.","Picar cebolla en trozos finos.","Picar pimiento verde en trozos finos.","Picar ajo fino.","Calentar aceite de oliva en una cazuela a fuego fuerte.","Dorar las costillas por todos los lados hasta que estén bien selladas.","Retirar las costillas de la cazuela y reservar.","Sofreír la cebolla, el pimiento verde y el ajo en la misma cazuela a fuego medio hasta que estén tiernos.","Añadir tomate triturado y pimentón dulce y sofreír hasta que el tomate pierda el agua.","Añadir fideos gordos y remover sin parar hasta que tomen color dorado.","Devolver las costillas a la cazuela y verter caldo de carne.","Llevar a ebullición a fuego fuerte.","Cocer a fuego medio sin tapar hasta que los fideos absorban el caldo y estén en su punto.","Retirar del fuego y dejar reposar.","Servir la cazuela directamente en la mesa."}', 'Fideos tostados en cazuela con costilla que se separa sola de tierna.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_084', 'Pasta con pesto rojo de tomate seco', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 558, 16, 62, 27, 2, true, true, '{"gluten","lactosa","frutos_secos"}', '[{"name":"Fusilli","amount":200,"unit":"g"},{"name":"Tomates secos en aceite","amount":60,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Queso parmesano","amount":25,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Albahaca fresca","amount":10,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Tostar piñones en sartén sin aceite a fuego suave hasta que estén ligeramente dorados.","Retirar los piñones de la sartén y reservar.","Escurrir tomates secos en aceite y cortar en trozos.","Rallar queso parmesano.","Triturar los tomates secos, los piñones tostados, ajo, albahaca fresca, el queso parmesano y aceite de oliva hasta obtener una pasta homogénea.","Cocer fusilli en el agua hirviendo según el tiempo indicado en el paquete.","Reservar un cazo del agua de cocción antes de escurrir la pasta.","Escurrir la pasta.","Mezclar la pasta caliente con el pesto rojo, añadiendo agua de cocción si la salsa ha quedado demasiado espesa.","Servir de inmediato."}', 'Pasta con un pesto rojo de tomate seco, rojo intenso y más potente que el pesto clásico.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_085', 'Nidos de pasta con boloñesa gratinados', 'pasta_arroces', 'ternera', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 620, 36, 54, 28, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Nidos de tallarines","amount":200,"unit":"g"},{"name":"Carne picada de ternera","amount":250,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Zanahoria","amount":40,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Queso mozzarella rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar cebolla y zanahoria en trozos muy finos.","Picar ajo fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, la zanahoria y el ajo hasta que estén blandos.","Subir el fuego a fuerte y añadir carne picada de ternera.","Dorar la carne picada, desmenuzándola con una cuchara, hasta que pierda el color rosado.","Añadir tomate triturado, orégano y sal al gusto.","Cocer a fuego suave hasta que la salsa espese.","Llevar a ebullición agua con sal en una olla y cocer nidos de tallarines 2 min menos del tiempo indicado en el envase.","Escurrir los nidos con cuidado de que no se deshagan.","Colocar los nidos escurridos en una fuente de horno.","Rellenar el centro de cada nido con la boloñesa.","Cubrir los nidos con queso mozzarella rallado.","Hornear a 200 °C hasta que el queso funda y se dore.","Servir de inmediato."}', 'Nidos de pasta individuales rellenos de boloñesa y gratinados, cada uno con su corteza dorada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_086', 'Pastel de macarrones con bechamel', 'pasta_arroces', 'pescado_azul', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'all', 622, 34, 54, 30, 2, true, true, '{"gluten","lactosa","pescado"}', '[{"name":"Macarrones","amount":200,"unit":"g"},{"name":"Atún en aceite","amount":160,"unit":"g"},{"name":"Tomate frito","amount":100,"unit":"ml"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Leche entera","amount":400,"unit":"ml"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar cebolla fino.","Llevar a ebullición una olla con agua abundante y sal.","Cocer macarrones en el agua hirviendo el tiempo indicado en el envase.","Calentar sartén a fuego medio con aceite de oliva y sofreír la cebolla picada hasta que esté transparente.","Añadir atún en aceite escurrido y tomate frito, remover y cocer 3 min a fuego medio.","Retirar el sofrito del fuego y reservar.","Escurrir los macarrones cocidos y reservar.","Fundir mantequilla en un cazo a fuego suave.","Añadir harina de golpe y remover sin parar 1 min hasta obtener una pasta homogénea.","Verter leche entera poco a poco sin dejar de remover hasta que la bechamel espese a fuego suave.","Añadir nuez moscada a la bechamel y remover para integrar.","Mezclar los macarrones escurridos con el sofrito de atún y la mitad de la bechamel en un bol grande.","Verter la mezcla en un molde apto para horno y extenderla de forma uniforme.","Cubrir con la bechamel restante y espolvorear queso rallado por encima.","Hornear a 200 °C durante 15 min hasta que la superficie esté dorada.","Reposar el pastel fuera del horno 5 min antes de servir.","Servir directamente del molde en porciones."}', 'Pastel de macarrones con atún y bechamel que se desmolda entero, corte limpio y cremoso.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_087', 'Espaguetis con almejas y guindilla', 'pasta_arroces', 'marisco', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 498, 24, 58, 18, 2, false, false, '{"gluten","moluscos","sulfitos"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Almejas","amount":400,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Guindilla fresca","amount":5,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Perejil","amount":8,"unit":"g"}]'::jsonb, '{"Sumergir almejas en agua fría con sal abundante durante 30 min para que suelten la arena.","Llevar a ebullición una olla grande con agua y sal a fuego fuerte.","Laminar ajo en láminas finas.","Picar guindilla fresca fina, retirando las semillas si se prefiere menos picante.","Picar perejil fino y reservar.","Escurrir las almejas del agua con sal y aclarar bajo el grifo.","Calentar aceite de oliva en sartén amplia a fuego medio hasta que esté caliente.","Sofreír el ajo laminado y la guindilla picada a fuego medio hasta que el ajo esté dorado sin quemarse.","Añadir las almejas escurridas y vino blanco a la sartén.","Tapar la sartén y cocer a fuego fuerte hasta que todas las almejas se abran.","Retirar y descartar las almejas que no se hayan abierto.","Cocer espaguetis en el agua hirviendo según el tiempo indicado en el envase.","Reservar un cazo del agua de cocción antes de escurrir la pasta.","Escurrir los espaguetis y añadirlos a la sartén con las almejas.","Saltear todo junto a fuego medio, añadiendo agua de cocción reservada poco a poco hasta ligar la salsa.","Espolvorear el perejil picado sobre la pasta y servir de inmediato."}', 'Espaguetis con almejas y un picante suave de guindilla, conchas brillantes entre la pasta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL)
