insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pasta_arroces_088', 'Arroz negro con sepia', 'pasta_arroces', 'marisco', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 445, 22, 55, 15, 2, false, false, '{"moluscos","pescado"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Sepia","amount":250,"unit":"g"},{"name":"Tinta de calamar","amount":8,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":450,"unit":"ml"}]'::jsonb, '{"Cortar sepia en trozos de bocado.","Picar cebolla y ajo finamente.","Disolver tinta de calamar en caldo de pescado y reservar.","Calentar aceite de oliva en una cazuela ancha a fuego medio.","Sofreír la cebolla y el ajo a fuego medio hasta que estén blandos.","Añadir la sepia y saltear a fuego fuerte hasta que se dore ligeramente.","Añadir tomate triturado y sofreír hasta que pierda el agua y oscurezca.","Añadir arroz y remover hasta que se impregne del sofrito.","Verter el caldo con la tinta y repartir el arroz en una capa uniforme.","Llevar a ebullición a fuego fuerte.","Cocer a fuego medio-suave sin remover hasta que el arroz absorba el caldo.","Retirar del fuego, tapar y dejar reposar.","Servir directamente en la cazuela."}', 'Arroz negro profundo con trozos tiernos de sepia repartidos por todo el grano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_089', 'Pasta con calabacín y gambas al ajillo', 'pasta_arroces', 'marisco', 'pasta', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 480, 28, 54, 16, 2, true, false, '{"gluten","marisco"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Calabacín","amount":200,"unit":"g"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Guindilla","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Cortar calabacín en medias lunas finas.","Laminar ajo.","Picar guindilla fina.","Cocer espaguetis en el agua hirviendo hasta que estén al dente, según el tiempo del envase.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír el ajo laminado y la guindilla picada hasta que el ajo se dore ligeramente.","Añadir el calabacín y saltear a fuego medio hasta que esté tierno pero con cuerpo.","Añadir gambas peladas y saltear hasta que cambien de color.","Escurrir los espaguetis reservando un cazo del agua de cocción.","Añadir los espaguetis escurridos a la sartén y saltear todo junto a fuego medio.","Añadir un poco del agua de cocción reservada si la mezcla necesita ligarse.","Picar perejil fino.","Espolvorear el perejil picado y servir de inmediato."}', 'Pasta con calabacín salteado y gambas al ajillo en un aceite perfumado, verde y rosa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_090', 'Pasta al horno con feta y tomates cherry', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 628, 20, 56, 36, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Penne","amount":200,"unit":"g"},{"name":"Queso feta","amount":200,"unit":"g"},{"name":"Tomates cherry","amount":300,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Albahaca fresca","amount":8,"unit":"g"},{"name":"Orégano","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar ajo y dejar los dientes enteros.","Colocar queso feta en el centro de una fuente de horno.","Rodear el queso feta con tomates cherry enteros y los dientes de ajo.","Regar con aceite de oliva y espolvorear orégano sobre el conjunto.","Hornear 25 min hasta que los tomates cherry estén arrugados y el queso feta blando y ligeramente dorado.","Llevar a ebullición una olla con agua abundante y sal.","Cocer penne en el agua hirviendo el tiempo indicado en el envase hasta que esté al dente.","Reservar un cazo del agua de cocción y escurrir la pasta.","Picar albahaca fresca en fino.","Retirar la fuente del horno y aplastar el queso feta y los tomates cherry con un tenedor hasta obtener una salsa cremosa.","Añadir la pasta escurrida a la fuente y mezclar con la salsa.","Añadir agua de cocción reservada si la salsa ha quedado demasiado espesa y remover hasta integrar.","Servir de inmediato con la albahaca fresca picada por encima."}', 'Pasta al horno donde la feta se funde entera y liga la salsa sola: el viral de TikTok.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_091', 'Pasta a la vodka con panceta', 'pasta_arroces', 'cerdo', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 664, 28, 58, 36, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Penne","amount":200,"unit":"g"},{"name":"Panceta ahumada","amount":120,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Vodka","amount":50,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"}]'::jsonb, '{"Cortar panceta ahumada en tiras finas.","Picar cebolla en trozos muy finos.","Llevar a ebullición una olla grande con agua abundante y sal.","Rallar queso parmesano y reservar.","Calentar sartén a fuego medio y dorar la panceta sin aceite hasta que esté crujiente.","Retirar la panceta crujiente y reservar, dejando la grasa en la sartén.","Cocer penne en el agua hirviendo según el tiempo del envase.","Sofreír la cebolla picada en la grasa de la panceta a fuego medio hasta que esté transparente.","Añadir vodka y dejar reducir a fuego fuerte hasta que se evapore casi por completo.","Añadir tomate triturado y cocer a fuego suave hasta que la salsa espese.","Añadir nata para cocinar y remover hasta que la salsa quede homogénea y de color rosado.","Escurrir la pasta cocida y añadirla a la salsa.","Añadir el queso parmesano rallado y remover hasta que se integre.","Servir la pasta en platos y colocar la panceta crujiente por encima."}', 'Pasta en salsa rosa cremosa con un toque de vodka reducido y panceta crujiente encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_092', 'Orzo mediterráneo con pollo, limón y espinacas', 'pasta_arroces', 'pollo', 'pasta', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 546, 36, 52, 22, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Orzo","amount":180,"unit":"g"},{"name":"Pechuga de pollo","amount":250,"unit":"g"},{"name":"Espinacas frescas","amount":150,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Caldo de pollo","amount":400,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Queso feta","amount":40,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en dados de bocado.","Salpimentar los dados de pollo y reservar.","Pelar y picar ajo fino.","Rallar la piel de limón y exprimir su zumo. Reservar por separado.","Calentar aceite de oliva en sartén amplia a fuego fuerte.","Dorar los dados de pollo por todos los lados hasta que estén dorados. Reservar fuera de la sartén.","Bajar a fuego medio y sofreír el ajo picado en la misma sartén hasta que esté dorado.","Añadir orzo y remover hasta que quede impregnado del aceite.","Verter caldo de pollo y llevar a ebullición a fuego fuerte.","Bajar a fuego medio y cocer sin tapar hasta que el orzo esté al dente, removiendo de vez en cuando.","Devolver el pollo reservado a la sartén y añadir espinacas frescas.","Remover hasta que las espinacas se marchiten.","Retirar del fuego y añadir la ralladura y el zumo de limón. Remover bien.","Desmenuzar queso feta por encima y servir de inmediato."}', 'Orzo suelto y brillante con pollo, limón y espinacas, verde y amarillo bien mediterráneo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_093', 'One-pot pasta con tomate, ajo y albahaca', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 460, 15, 64, 16, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":400,"unit":"ml"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"}]'::jsonb, '{"Picar cebolla fino.","Picar ajo fino.","Calentar aceite de oliva en una cazuela ancha a fuego medio.","Sofreír la cebolla picada y el ajo picado hasta que estén transparentes, unos 3 min.","Añadir tomate triturado y caldo de verduras a la cazuela.","Llevar a ebullición a fuego fuerte.","Partir espaguetis por la mitad e introducirlos en la cazuela, sumergiéndolos en el líquido.","Cocer a fuego medio, removiendo con frecuencia, hasta que la pasta esté al dente y el líquido forme una salsa, unos 10 min.","Rallar queso parmesano mientras la pasta cuece.","Picar albahaca fresca fino.","Añadir la albahaca picada a la cazuela y remover.","Servir de inmediato con el queso parmesano rallado por encima."}', 'Espaguetis cocidos en su propia salsa de tomate, ajo y albahaca, todo en la misma cazuela.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_094', 'Macarrones con tomate y queso', 'pasta_arroces', 'none', 'pasta', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 22, 'facil', 'all', 430, 15, 58, 14, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Macarrones","amount":180,"unit":"g"},{"name":"Tomate triturado","amount":300,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"},{"name":"Queso rallado curado","amount":50,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Picar cebolla y ajo muy finos.","Llevar a ebullición una olla grande con agua abundante y sal.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada y el ajo picado a fuego medio hasta que la cebolla esté transparente.","Cocer macarrones en el agua hirviendo el tiempo indicado en el envase hasta que estén al dente.","Añadir tomate triturado y orégano a la sartén y remover para integrar.","Cocer la salsa a fuego suave, removiendo de vez en cuando, hasta que espese y pierda acidez.","Escurrir los macarrones cuando estén al dente y reservar.","Añadir los macarrones escurridos a la sartén con la salsa y mezclar bien a fuego suave.","Repartir en los platos y cubrir con queso rallado curado por encima."}', 'Macarrones con salsa de tomate casera y una generosa capa de queso rallado fundiéndose por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_001', 'Merluza en salsa verde', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 286, 28, 6, 16, 2, true, true, '{"pescado","gluten"}', '[{"name":"Merluza en rodajas","amount":350,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Guisantes","amount":50,"unit":"g"}]'::jsonb, '{"Laminar ajo en láminas finas.","Picar perejil finamente y reservar.","Calentar aceite de oliva en una cazuela a fuego medio hasta que esté caliente.","Sofreír el ajo laminado a fuego suave hasta que esté dorado sin quemarse.","Añadir harina y remover sin parar durante 1 min hasta que se integre con el aceite.","Verter vino blanco y remover hasta que el alcohol se evapore y la salsa ligue.","Colocar merluza en rodajas en la cazuela en una sola capa.","Añadir guisantes repartidos entre las rodajas.","Cocer a fuego suave 10 min, moviendo la cazuela en círculos para ligar la salsa.","Añadir el perejil picado, remover suavemente y servir en la misma cazuela."}', 'Merluza en salsa verde con ajo, perejil y guisantes', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Prepara la salsa verde en una cazuela apta para horno, sofriendo el ajo y añadiendo el resto de ingredientes. Incorpora las rodajas de merluza y los guisantes, y hornea a 190°C durante 20-25 minutos. Cubre con papel de aluminio los primeros 15 minutos para mantener la humedad y q"},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo en el vaso, añade la harina, el vino y el caldo para la salsa, cocinando a 100°C. Luego, incorpora la merluza y los guisantes, y cocina a 100°C, giro inverso, velocidad cuchara durante 8-10 minutos, asegurando que el pescado se cocine suavemente sin deshacerse."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_002', 'Salmón al horno con patatas', 'pescados', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 468, 32, 26, 24, 2, true, true, '{"pescado"}', '[{"name":"Lomos de salmón","amount":300,"unit":"g"},{"name":"Patata","amount":250,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Eneldo","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar patata y cebolla.","Laminar la patata pelada en rodajas finas de unos 3 mm.","Laminar la cebolla pelada en aros finos.","Cortar limón por la mitad y reservar.","Disponer las rodajas de patata y los aros de cebolla en una bandeja de horno. Regar con aceite de oliva y salpimentar.","Hornear la bandeja a 200 °C durante 15 min, hasta que la patata empiece a estar tierna.","Retirar la bandeja del horno y colocar lomos de salmón sobre la cama de patatas y cebolla.","Exprimir el limón sobre el salmón y espolvorear eneldo por encima.","Hornear a 200 °C durante 15 min más, hasta que el salmón esté opaco y se desmenuce con facilidad.","Retirar la bandeja del horno y servir el salmón sobre las patatas y la cebolla."}', 'Lomos de salmón asados al horno sobre cama de patatas', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Cocina las patatas y cebolla en rodajas finas con aceite y sal durante 20 minutos, luego añade el salmón con limón y eneldo y hornea todo junto 15-20 minutos más hasta que el salmón esté tierno y las patatas doradas."},{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Corta las patatas en rodajas finas y la cebolla en juliana. Cocínalas en la airfryer a 180°C durante 15-20 minutos, agitando a mitad. Añade el salmón con limón y eneldo, y cocina todo junto 10-12 minutos más a 190°C para un acabado crujiente y jugoso."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_003', 'Bacalao con tomate', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 312, 30, 12, 16, 2, true, true, '{"pescado"}', '[{"name":"Bacalao desalado","amount":350,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Pelar cebolla y ajo, y limpiar pimiento verde; cortar la cebolla y el pimiento en trozos pequeños y picar el ajo fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, el ajo y el pimiento verde en la sartén hasta que estén tiernos y la cebolla esté transparente.","Añadir tomate triturado al sofrito y remover para integrar.","Cocer la salsa a fuego medio hasta que reduzca ligeramente y pierda el sabor ácido del tomate.","Colocar bacalao desalado sobre la salsa con la piel hacia abajo.","Tapar la sartén y cocer a fuego suave hasta que el bacalao esté opaco y se desmenuce con facilidad.","Servir el bacalao con la salsa de tomate por encima directamente desde la sartén."}', 'Bacalao desalado guisado en salsa de tomate casera', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Prepara un sofrito con las verduras en sartén, añade el tomate y el bacalao en una fuente de horno. Hornea a 180°C durante 20-25 minutos hasta que el bacalao esté tierno y la salsa reducida. Un truco es cubrir con papel de aluminio al principio para que el pescado no se seque."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas en el vaso con aceite (10-12 min, Varoma, vel 1). Añade el tomate y cocina unos minutos. Incorpora el bacalao y programa 15-18 min, 100°C, giro inverso, vel cuchara. Asegúrate de que el bacalao quede jugoso."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Haz un sofrito con las verduras en la olla abierta. Añade el tomate y el bacalao. Cierra la olla y cocina a presión durante 3-5 minutos desde que sube la válvula, dependiendo del grosor del bacalao. Despresuriza y sirve. El truco es no sobrecocer el pescado para que no se deshaga"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pescados_004', 'Sardinas a la plancha', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'verano', 342, 26, 1, 26, 2, false, false, '{"pescado"}', '[{"name":"Sardinas","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Limpiar sardinas bajo el grifo, retirar las escamas y las vísceras, y secar bien con papel de cocina.","Picar ajo muy fino y reservar.","Cortar limón en gajos y reservar.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Pincelar las sardinas con aceite de oliva y salpimentar por ambos lados.","Colocar las sardinas sobre la plancha y dorar 3 min por el primer lado sin moverlas.","Dar la vuelta a las sardinas y dorar 3 min por el segundo lado hasta que estén cocinadas.","Retirar las sardinas a la fuente de servir, espolvorear el ajo picado y perejil picado por encima.","Servir acompañadas de los gajos de limón al lado."}', 'Sardinas frescas a la plancha con ajo y limón', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina las sardinas previamente salpimentadas y untadas en aceite durante 10-12 minutos, volteándolas a mitad para un dorado uniforme y crujiente."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con función grill si es posible. Coloca las sardinas en una bandeja con papel de horno y cocina 10-12 minutos, dándoles un golpe de grill al final para un exterior dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_005', 'Lubina al horno', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 298, 32, 8, 14, 2, true, false, '{"pescado"}', '[{"name":"Lubina entera","amount":500,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cebolla, y laminarlas en rodajas de unos 3 mm de grosor.","Cortar limón en rodajas finas.","Picar perejil finamente y reservar.","Precalentar el horno a 200 °C con calor arriba y abajo.","Extender las rodajas de patata y cebolla en una bandeja de horno, regar con aceite de oliva y salpimentar al gusto.","Hornear las verduras durante 15 min a 200 °C hasta que comiencen a estar tiernas.","Retirar la bandeja del horno y colocar lubina entera encima de la cama de verduras.","Disponer las rodajas de limón sobre la lubina y espolvorear el perejil picado.","Hornear el conjunto 18 min a 200 °C hasta que la lubina esté cocinada y la piel ligeramente dorada.","Retirar del horno y servir la lubina sobre la cama de verduras, con el jugo de cocción por encima."}', 'Lubina entera al horno sobre cama de patata y cebolla', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Dispón la lubina sobre una cama de patatas y cebolla laminadas, riega con aceite y limón, y hornea hasta que esté tierna y dorada."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Coloca la lubina y las verduras cortadas finas en la cesta, rocía con aceite y cocina unos 25 minutos, volteando las verduras a mitad para una cocción uniforme."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_006', 'Atún a la plancha', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 308, 36, 1, 18, 2, true, true, '{"pescado"}', '[{"name":"Rodajas de atún fresco","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Picar ajo muy fino y reservar.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Salpimentar rodajas de atún fresco por ambas caras.","Añadir aceite de oliva sobre la plancha caliente y extender.","Colocar las rodajas de atún sobre la plancha y cocinar 2 min por cada lado hasta que el centro quede rosado.","Retirar el atún, distribuir el ajo picado por encima y exprimir limón al gusto antes de servir."}', 'Rodajas de atún fresco a la plancha, rosadas por dentro', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Marinar el atún con aceite de oliva, ajo picado, sal y pimienta. Precalentar la airfryer a 190-200°C. Cocinar el atún unos 8-12 minutos, volteando a mitad, para lograr un exterior dorado y un interior jugoso, sirviendo con limón."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Marinar el atún con aceite de oliva, ajo picado, sal y pimienta. Precalentar el horno a 200-220°C, preferiblemente con función grill. Colocar el atún en una bandeja y cocinar 8-12 minutos, según el grosor, hasta que esté sellado por fuera y tierno por dentro, sirviendo con limón."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_007', 'Merluza rebozada', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 368, 28, 18, 20, 2, true, true, '{"pescado","gluten","huevo"}', '[{"name":"Merluza en rodajas","amount":350,"unit":"g"},{"name":"Harina","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Secar merluza en rodajas con papel de cocina y salpimentar por ambos lados.","Batir huevo en un bol hasta que esté homogéneo.","Disponer harina en un plato llano.","Pasar cada rodaja de merluza por la harina, sacudir el exceso y luego sumergir en el huevo batido.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír las rodajas rebozadas hasta que estén doradas por un lado, unos 3 min, sin moverlas.","Dar la vuelta a las rodajas y freír por el otro lado hasta que estén doradas, otros 2 min.","Escurrir la merluza sobre papel de cocina para eliminar el exceso de aceite.","Cortar limón en gajos y servir la merluza rebozada con los gajos de limón al lado."}', 'Rodajas de merluza rebozadas en huevo y harina', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Reboza la merluza como de costumbre. Rocía ligeramente con aceite de oliva y cocina en la airfryer precalentada a 190-200°C durante 15-18 minutos, dándole la vuelta a mitad de cocción para un dorado uniforme y crujiente."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200-220°C. Reboza la merluza, rocíala con un poco de aceite y colócala en una bandeja con papel de horno. Hornea durante 20-25 minutos, volteando a mitad, hasta que esté dorada y crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_008', 'Dorada al horno', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 306, 34, 6, 14, 2, true, false, '{"pescado"}', '[{"name":"Dorada entera","amount":500,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar patata y cebolla, y cortar ambas en rodajas de unos 5 mm de grosor.","Cortar tomate en rodajas de unos 5 mm de grosor.","Cortar limón por la mitad: reservar una mitad en rodajas finas y la otra para el zumo final.","Precalentar el horno a 200 °C con calor arriba y abajo.","Disponer las rodajas de patata en una bandeja de horno formando una cama uniforme.","Colocar encima las rodajas de cebolla y luego las de tomate, cubriéndolas en una sola capa.","Regar las verduras con aceite de oliva y salpimentar al gusto.","Hornear la cama de verduras durante 15 min a 200 °C hasta que la patata empiece a estar tierna.","Limpiar dorada entera por dentro y colocar en su cavidad las rodajas de limón reservadas.","Retirar la bandeja del horno y colocar la dorada encima de la cama de verduras.","Hornear 18 min más a 200 °C hasta que la piel esté dorada y la carne se separe fácilmente de la espina.","Retirar la bandeja del horno y exprimir la mitad del limón reservada sobre la dorada antes de servir."}', 'Dorada entera al horno con patata, tomate y cebolla', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Coloca la dorada con las patatas y verduras cortadas en una bandeja, riega con aceite y limón. Hornea durante 35-40 minutos hasta que esté tierna y dorada."},{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Corta las patatas muy finas y las verduras en juliana. Cocina la dorada con las verduras y un chorrito de aceite durante 20-25 minutos, volteando a mitad para una cocción uniforme y piel crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_009', 'Salmón a la plancha', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 378, 30, 1, 28, 2, true, true, '{"pescado"}', '[{"name":"Lomos de salmón","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Eneldo","amount":3,"unit":"g"}]'::jsonb, '{"Salpimentar lomos de salmón por ambas caras y reservar.","Cortar limón en gajos y reservar.","Calentar plancha a fuego fuerte con aceite de oliva hasta que humee.","Colocar los lomos de salmón con la piel hacia abajo y dorar a fuego fuerte durante 4 min sin moverlos.","Dar la vuelta a los lomos de salmón y cocer 2 min más hasta que el centro esté apenas opaco.","Servir los lomos de salmón con los gajos de limón y espolvorear eneldo por encima."}', 'Lomos de salmón a la plancha con la piel crujiente', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Unta el salmón con aceite de oliva, eneldo y un poco de sal. Cocina durante 10-12 minutos, volteando a mitad, hasta que esté dorado y jugoso. Sirve con limón."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca el salmón untado con aceite de oliva y eneldo en una bandeja. Hornea durante 12-15 minutos hasta que esté cocido y ligeramente dorado. Sirve con un chorrito de limón."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_010', 'Bacalao al pil-pil', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'elaborada', 'all', 362, 28, 2, 26, 2, false, false, '{"pescado"}', '[{"name":"Bacalao desalado","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Guindilla","amount":1,"unit":"ud"}]'::jsonb, '{"Laminar ajo en láminas finas.","Verter aceite de oliva en una cazuela de fondo grueso y calentar a fuego suave.","Añadir el ajo laminado y guindilla al aceite caliente y confitar hasta que el ajo esté dorado y tierno.","Retirar el ajo dorado y la guindilla con una espumadera y reservar fuera de la cazuela.","Bajar el fuego al mínimo y colocar bacalao desalado con la piel hacia arriba en la cazuela con el aceite.","Cocer el bacalao a fuego muy suave durante 10 min hasta que la carne esté opaca y se vea que suelta gelatina.","Retirar la cazuela del fuego y mover en vaivén continuo hasta que la gelatina y el aceite liguen formando una salsa cremosa.","Colocar el bacalao en el plato, naparlo con la salsa pil-pil y disponer encima el ajo reservado y la guindilla."}', 'Bacalao confitado en aceite de oliva ligado con su gelatina', '[{"appliance":"thermomix","time":20,"difficulty":"normal","prepSummary":"Confitar el bacalao a baja temperatura (aprox. 80°C) con el aceite, ajo y guindilla durante unos 15 minutos. Retirar el bacalao y mezclar bien el aceite restante a velocidad progresiva (3-4) hasta obtener la salsa pil-pil, unos 5 minutos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_011', 'Calamares a la romana', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 356, 22, 26, 18, 2, true, false, '{"moluscos","gluten","huevo"}', '[{"name":"Calamares","amount":300,"unit":"g"},{"name":"Harina","amount":60,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Limpiar calamares bajo el grifo, retirar la piel y las vísceras, y cortar en anillas de unos 1 cm de grosor.","Batir huevo en un bol hasta que esté homogéneo.","Calentar aceite de oliva en sartén a fuego fuerte hasta que alcance unos 180 °C.","Pasar las anillas de calamar por harina, sacudir el exceso y sumergirlas en el huevo batido.","Freír las anillas en el aceite caliente, en tandas, hasta que estén doradas y crujientes, unos 2 min por tanda.","Escurrir las anillas sobre papel absorbente para eliminar el exceso de aceite.","Cortar limón en gajos y servir los calamares recién fritos acompañados de los gajos de limón."}', 'Anillas de calamar rebozadas en harina y huevo, fritas', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Rocía los calamares rebozados con un poco de aceite y cocínalos en tandas durante 12-15 minutos, dándoles la vuelta a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con ventilador. Coloca los calamares rebozados en una bandeja con papel de horno, rocía con aceite y hornea 15-20 minutos, volteándolos a mitad, hasta que estén dorados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_012', 'Gambas al ajillo', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 268, 22, 3, 18, 2, true, false, '{"marisco"}', '[{"name":"Gambas peladas","amount":250,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Guindilla","amount":1,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Calentar aceite con ajos laminados y guindilla","Cuando el ajo empiece a dorar, añadir las gambas","Saltear 2 min a fuego fuerte","Retirar del fuego y añadir perejil"}', 'Gambas salteadas en aceite de oliva con ajo y guindilla', '[{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Combina las gambas, ajo laminado, guindilla y aceite en una cazuela de barro o fuente apta para horno. Hornea a 200°C durante 10-12 minutos hasta que las gambas estén rosadas y el ajo ligeramente dorado. Sirve espolvoreado con perejil."},{"appliance":"airfryer","time":13,"difficulty":"facil","prepSummary":"En un recipiente pequeño apto para airfryer (tipo ramekin o cazuelita), mezcla las gambas, ajo laminado, guindilla y aceite. Cocina en la airfryer precalentada a 190°C durante 8-10 minutos, agitando a mitad, hasta que las gambas estén hechas y el ajo fragante. Añade perejil al se"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_013', 'Merluza al horno con verduras', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 296, 30, 14, 12, 2, true, true, '{"pescado"}', '[{"name":"Merluza en lomos","amount":350,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar patata y cortar en rodajas finas de unos 3 mm.","Pelar cebolla y cortar en aros finos.","Lavar pimiento rojo y cortar en aros finos, retirando las semillas.","Lavar tomate y cortar en rodajas de unos 4 mm.","Cortar limón en rodajas finas.","Extender la patata en una sola capa sobre una bandeja de horno y regar con aceite de oliva.","Distribuir la cebolla, el pimiento rojo y el tomate sobre la patata, formando una cama de verduras uniforme.","Hornear la bandeja de verduras durante 15 min a 200 °C hasta que la patata empiece a estar tierna.","Retirar la bandeja del horno y colocar merluza en lomos sobre las verduras con la piel hacia abajo.","Disponer las rodajas de limón sobre los lomos de merluza y regar con un chorrito de aceite de oliva.","Hornear de nuevo a 200 °C durante 12 min, hasta que la merluza esté opaca y se desmenuce con facilidad.","Retirar la bandeja del horno y servir los lomos de merluza sobre la cama de verduras, con el jugo de cocción por encima."}', 'Lomos de merluza al horno sobre verduras asadas', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Precalienta el horno a 180-200°C. Dispón las patatas y verduras cortadas en una bandeja con aceite, hornea unos 15-20 min, luego añade la merluza y hornea 15-20 min más hasta que el pescado esté tierno y las verduras doradas."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta las patatas y verduras muy finas para asegurar una cocción uniforme. Precalienta la airfryer a 180°C, cocina las verduras con un poco de aceite durante 10-15 min, luego añade la merluza y cocina 8-10 min más hasta que esté cocida y ligeramente dorada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pescados_014', 'Bacalao rebozado', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 388, 30, 20, 22, 2, true, true, '{"pescado","gluten","huevo"}', '[{"name":"Bacalao desalado","amount":350,"unit":"g"},{"name":"Harina","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":45,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar bacalao desalado en trozos de unos 5 cm y secar cada pieza con papel absorbente.","Batir huevo en un bol hasta que la clara y la yema queden integradas.","Extender harina en un plato llano para rebozar.","Pasar cada trozo de bacalao por la harina, sacudir el exceso y sumergir en el huevo batido hasta cubrir bien.","Calentar aceite de oliva en sartén a fuego fuerte hasta que el aceite alcance unos 180 °C.","Freír los trozos de bacalao rebozados en tandas hasta que estén dorados por ambos lados, unos 3 min por cada lado.","Escurrir el bacalao frito sobre papel absorbente para eliminar el exceso de aceite.","Cortar limón en gajos y servir el bacalao acompañado del limón para exprimir al gusto."}', 'Trozos de bacalao desalado rebozados en harina y huevo', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Rocía ligeramente el bacalao rebozado con aceite y cocina durante 15-18 minutos, dándole la vuelta a mitad de cocción, hasta que esté dorado y crujiente."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Coloca el bacalao rebozado en una bandeja con papel de horno y hornea durante 20-25 minutos, o hasta que esté dorado y cocido por dentro. Un chorrito de aceite sobre el rebozado ayuda a que quede más crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_015', 'Trucha a la navarra', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 392, 34, 8, 24, 2, true, false, '{"pescado","gluten"}', '[{"name":"Truchas enteras","amount":400,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Laminar ajo en láminas finas.","Abrir truchas enteras por el lomo sin separar los filetes y limpiar el interior con papel absorbente.","Rellenar el interior de cada trucha con jamón serrano en lonchas, distribuyéndolas de forma uniforme.","Cerrar cada trucha y enharinar con harina por ambos lados; sacudir el exceso.","Calentar aceite de oliva en sartén a fuego medio hasta que esté bien caliente.","Añadir el ajo laminado y sofreír hasta que empiece a dorarse.","Incorporar las truchas enharinadas y freír a fuego medio durante 5 min sin moverlas, hasta que el fondo esté dorado.","Dar la vuelta a las truchas con cuidado y freír 5 min más por el otro lado hasta que estén doradas y bien hechas.","Cortar limón en gajos.","Retirar las truchas a una fuente y servir con los gajos de limón al lado."}', 'Trucha entera rellena de jamón serrano, enharinada y frita', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rellena la trucha enharinada con el jamón, pincela con aceite y cocina 18 minutos, volteando a mitad, hasta que esté dorada. El truco es un ligero pincelado de aceite para el crujiente exterior."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Rellena la trucha con el jamón, sazona, rocía con aceite y hornea 20 minutos hasta que esté hecha y ligeramente dorada. El truco es un refrito de ajo en sartén para verter por encima al servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_016', 'Rape en salsa marinera', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 312, 30, 10, 16, 2, true, true, '{"pescado","moluscos","gluten"}', '[{"name":"Rape","amount":350,"unit":"g"},{"name":"Almejas","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Pelar y picar fino cebolla y ajo.","Cortar rape en trozos de bocado de unos 3 cm.","Calentar aceite de oliva en una cazuela a fuego medio hasta que esté caliente.","Sofreír la cebolla picada y el ajo picado a fuego medio hasta que estén transparentes, unos 4 min.","Añadir harina al sofrito y remover sin parar durante 1 min hasta que se integre y pierda el sabor a crudo.","Verter vino blanco y remover hasta que se evapore el alcohol, unos 2 min.","Incorporar los trozos de rape a la cazuela y cocer a fuego medio durante 5 min.","Añadir almejas, tapar la cazuela y cocer a fuego medio hasta que todas las almejas estén abiertas, unos 3 min.","Picar fino perejil mientras las almejas se abren.","Espolvorear el perejil picado sobre la cazuela y servir de inmediato."}', 'Rape guisado en salsa marinera con almejas y vino blanco', '[{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en una cazuela apta para horno. Añade la harina, el vino y un poco de caldo, integra el rape y las almejas. Hornea a 180°C durante 15-20 minutos hasta que el pescado esté tierno y las almejas se abran. Un truco es cubrir con papel de aluminio para que n"},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Trocea cebolla y ajo, sofríe en el vaso con aceite. Añade la harina, el vino y un poco de agua o caldo, y cocina la salsa. Incorpora el rape y las almejas, cocinando a temperatura Varoma o a 90°C, velocidad cuchara, hasta que el pescado esté en su punto y las almejas abiertas. El"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_017', 'Palitos de merluza caseros', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 348, 26, 22, 18, 2, true, true, '{"pescado","gluten","huevo"}', '[{"name":"Merluza en lomos","amount":300,"unit":"g"},{"name":"Pan rallado","amount":50,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Harina","amount":25,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Cortar merluza en lomos en bastones de unos 3 cm de grosor y salpimentar.","Batir huevo en un bol hondo hasta que esté homogéneo.","Disponer harina y pan rallado en 2 platos separados.","Pasar cada bastón de merluza primero por la harina, sacudiendo el exceso.","Bañar cada bastón enharinado en el huevo batido hasta que quede bien cubierto.","Rebozar cada bastón en el pan rallado, presionando ligeramente para que se adhiera.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír los bastones rebozados a fuego fuerte hasta que estén dorados por todos los lados, unos 3 min.","Retirar los palitos de la sartén y escurrir sobre papel absorbente hasta que pierdan el exceso de aceite.","Servir los palitos de merluza calientes."}', 'Bastones de merluza empanados caseros, ideal para niños', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C y cocina los palitos de merluza durante 12-15 minutos, volteándolos a mitad de cocción para un dorado uniforme y una textura crujiente."},{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Hornea los palitos a 200°C con calor arriba y abajo durante 15-20 minutos, o hasta que estén bien dorados y crujientes, dándoles la vuelta una vez a mitad de cocción."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_018', 'Salmón en papillote', 'pescados', 'pescado_azul', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 25, 'facil', 'all', 382, 30, 8, 26, 2, true, true, '{"pescado"}', '[{"name":"Lomos de salmón","amount":300,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Eneldo","amount":3,"unit":"g"}]'::jsonb, '{"Lavar y pelar zanahoria, luego laminar en tiras finas de unos 3 mm.","Cortar calabacín en tiras finas de unos 3 mm, sin pelarlo.","Cortar puerro en tiras finas, usando solo la parte blanca y verde tierna.","Cortar limón por la mitad: reservar una mitad en rodajas finas y la otra para exprimir el zumo.","Precalentar el horno a 200 °C con calor arriba y abajo.","Cortar 2 rectángulos de papel de horno de unos 40 × 30 cm y disponerlos sobre la bandeja.","Repartir las tiras de zanahoria, calabacín y puerro en el centro de cada rectángulo de papel.","Colocar lomos de salmón sobre el lecho de verduras, uno en cada paquete.","Aliñar cada lomo con aceite de oliva, el zumo de limón y las rodajas de limón reservadas.","Espolvorear eneldo sobre cada lomo.","Cerrar cada papillote plegando los bordes del papel con varios dobleces apretados para que no escape el vapor.","Hornear los papillotes a 200 °C durante 18 min, hasta que el papel esté hinchado y ligeramente dorado.","Retirar la bandeja del horno y abrir los papillotes con cuidado por el centro, apartando el vapor hacia arriba.","Servir el salmón directamente en el papel o trasladarlo al plato junto con las verduras y el jugo acumulado."}', 'Salmón cocinado al vapor en papillote con verduras en juliana', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 180-200°C. Envuelve el salmón y las verduras con aceite, limón y eneldo en papel de horno o aluminio, sellando bien. Hornea durante 20-25 minutos para un resultado jugoso."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Prepara los papillotes en papel de aluminio bien sellado para evitar que se abran. Cocina durante 15-20 minutos, comprobando que el pescado esté en su punto."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Vierte 500-700ml de agua en el vaso. Coloca los papillotes (en papel de horno o aluminio) en el recipiente Varoma. Cocina 20-25 minutos, Varoma, velocidad 1, asegurando una cocción uniforme al vapor."},{"appliance":"vaporera","time":22,"difficulty":"facil","prepSummary":"Prepara los papillotes con todos los ingredientes bien sellados. Llena la base de la vaporera con agua y coloca los paquetes en la cesta. Cocina al vapor durante 20-25 minutos hasta que el salmón esté tierno."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Añade 250ml de agua a la olla y coloca una rejilla. Pon los papillotes bien cerrados sobre la rejilla. Cocina a presión alta durante 5-7 minutos y libera la presión rápidamente para evitar que el salmón se seque."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_019', 'Atún encebollado', 'pescados', 'pescado_azul', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 362, 34, 10, 20, 2, true, true, '{"pescado"}', '[{"name":"Atún fresco","amount":300,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar cebolla y laminar en juliana fina.","Cortar atún fresco en 2 filetes o tacos uniformes y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla laminada a fuego suave hasta que esté tierna y ligeramente dorada.","Añadir tomate triturado, vino blanco y laurel; remover para integrar.","Cocer la salsa a fuego medio hasta que el alcohol se evapore y la salsa reduzca ligeramente, unos 2 min.","Colocar el atún sobre la salsa, tapar y cocer a fuego suave hasta que el atún esté justo cocinado en el centro.","Retirar el laurel y servir el atún con la cebolla y la salsa por encima."}', 'Atún fresco guisado sobre cama de cebolla pochada al vino', '[{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Sofríe la cebolla en una cazuela apta para horno hasta que esté tierna. Añade el resto de ingredientes, cubre y hornea a 180°C durante 25-30 minutos, o hasta que el atún esté cocido y la salsa reducida, para una cocción uniforme y sabores concentrados."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Trocea la cebolla y sofríela con aceite a 120°C, velocidad cuchara, durante 10 min. Incorpora el resto de ingredientes (excepto el atún), programa 10 min, 100°C, velocidad cuchara. Añade el atún en trozos y cocina 5-7 min más, 100°C, giro inverso, velocidad cuchara, para un guiso"},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe la cebolla en la olla abierta con aceite. Añade el tomate, vino y laurel, cierra y cocina a presión durante 5 minutos. Abre, incorpora el atún en trozos y cocina sin tapa a fuego medio otros 5-7 minutos hasta que el atún esté hecho y la salsa reducida, logrando un guiso rá"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_020', 'Emperador a la plancha', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 282, 32, 1, 16, 2, true, true, '{"pescado"}', '[{"name":"Rodajas de emperador","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Picar ajo muy fino y reservar.","Picar perejil fino y reservar.","Exprimir limón y reservar el zumo.","Salpimentar rodajas de emperador por ambas caras.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Añadir aceite de oliva sobre la plancha y colocar las rodajas de emperador.","Cocinar las rodajas de emperador 3 min por el primer lado sin moverlas, hasta que se doren.","Dar la vuelta a las rodajas de emperador y cocinar 3 min por el segundo lado hasta que estén hechas.","Mezclar en un bol el ajo picado, el perejil picado y el zumo de limón hasta obtener una salsa homogénea.","Retirar las rodajas de emperador de la plancha y verter la salsa por encima. Servir de inmediato."}', 'Rodajas de pez espada a la plancha con ajo y perejil', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Marina el emperador con el aceite, ajo y perejil. Precalienta la airfryer a 190°C y cocina el pescado durante 12-15 minutos, dándole la vuelta a mitad para un dorado uniforme y una textura jugosa."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con función grill o calor arriba y abajo. Coloca el emperador marinado con aceite, ajo y perejil en una bandeja y hornea/gratina durante 10-15 minutos hasta que esté cocido y ligeramente dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_021', 'Fideuá', 'pescados', 'marisco', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 448, 24, 48, 18, 2, true, false, '{"gluten","marisco","pescado","moluscos"}', '[{"name":"Fideos n°2","amount":180,"unit":"g"},{"name":"Gambas","amount":150,"unit":"g"},{"name":"Sepia","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Caldo de pescado","amount":400,"unit":"ml"}]'::jsonb, '{"Cortar sepia en trozos de bocado de aproximadamente 2 cm.","Picar ajo muy fino.","Calentar caldo de pescado en un cazo a fuego medio hasta que esté caliente; retirar del fuego y reservar.","Calentar aceite de oliva en una paella o sartén amplia a fuego fuerte.","Sofreír la sepia troceada en el aceite caliente durante 3 min hasta que esté dorada; retirar y reservar.","Sofreír gambas en la misma sartén a fuego fuerte durante 2 min hasta que cambien de color; retirar y reservar.","Sofreír el ajo picado en la misma sartén a fuego medio durante 1 min hasta que esté dorado sin quemarse.","Añadir tomate triturado y sofreír a fuego medio durante 3 min hasta que reduzca y oscurezca.","Añadir pimentón y remover durante 30 segundos hasta integrarlo; retirar la sartén del fuego un instante para evitar que se queme.","Añadir fideos n°2 y tostarlos a fuego medio durante 3 min removiendo hasta que estén dorados.","Verter el caldo caliente reservado, remover para repartir los fideos en capa uniforme y llevar a ebullición a fuego fuerte.","Cocer a fuego medio sin remover durante 8 min hasta que los fideos absorban casi todo el caldo.","Incorporar la sepia y las gambas reservadas distribuyéndolas por la superficie; cocer 2 min más hasta que el caldo restante se absorba.","Retirar del fuego, tapar con un paño limpio y dejar reposar 5 min para que los fideos terminen de hidratarse.","Servir la fideuá directamente desde la sartén."}', 'Fideos tostados con gambas y sepia en caldo de pescado', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Sella las gambas y la sepia, y sofríe el ajo y tomate en una paellera o cazuela apta para horno. Añade los fideos y tuéstalos ligeramente antes de incorporar el caldo caliente. Termina la cocción en el horno precalentado a 200°C durante unos 15-20 minutos, hasta que los fideos ab"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_022', 'Rosada al horno con limón', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 25, 'facil', 'all', 262, 30, 4, 14, 2, true, true, '{"pescado"}', '[{"name":"Rosada en lomos","amount":350,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"}]'::jsonb, '{"Laminar ajo en rodajas finas.","Cortar limón en rodajas de medio centímetro.","Picar perejil fino y reservar.","Precalentar el horno a 190 °C con calor arriba y abajo.","Disponer rosada en lomos en una bandeja de horno con la piel hacia abajo.","Repartir el ajo laminado sobre los lomos.","Colocar las rodajas de limón encima del pescado.","Verter aceite de oliva y vino blanco sobre los lomos.","Hornear en el centro del horno a 190 °C durante 18 min, hasta que el pescado esté opaco y se desmenuce al tocarlo.","Retirar la bandeja del horno y espolvorear el perejil picado sobre los lomos antes de servir."}', 'Lomos de rosada al horno con limón, ajo y vino blanco', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Coloca la rosada en una bandeja de horno junto con el limón en rodajas, ajo picado, perejil, un chorrito de aceite y el vino blanco. Hornea durante 20-25 minutos hasta que el pescado esté tierno y jugoso, evitando el sobrecocinado para mantener su te"},{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Dispón la rosada en la cesta con el resto de ingredientes, asegurándote de que el limón y el ajo estén bien distribuidos. Cocina por 12-15 minutos, revisando el punto de cocción para que quede jugosa por dentro y ligeramente dorada por fuera."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_023', 'Caballa a la plancha con limón', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 246, 24, 1, 16, 2, true, true, '{"pescado"}', '[{"name":"Caballa","amount":350,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar limón por la mitad y reservar una mitad para el zumo y la otra para decorar.","Picar ajo muy fino y picar perejil igualmente fino.","Mezclar el ajo picado y el perejil picado con aceite de oliva en un bol pequeño hasta integrar bien.","Limpiar caballa, retirar las espinas centrales y abrirla en lomos iguales. Secar bien con papel de cocina.","Calentar plancha a fuego fuerte hasta que humee ligeramente.","Colocar los lomos de caballa con la piel hacia abajo en la plancha caliente y dorar 3 min sin moverlos, hasta que la piel esté crujiente.","Dar la vuelta a los lomos y cocinar 1 min por el lado de la carne, hasta que esté opaca en el centro.","Retirar los lomos de la plancha y disponer en el plato con la piel hacia arriba.","Exprimir la mitad del limón reservada sobre los lomos y repartir el aliño de ajo, perejil y aceite de oliva por encima. Servir de inmediato."}', 'Caballa a la plancha con un aliño de ajo, perejil y limón', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Coloca los lomos de caballa en la freidora de aire a 190°C durante 8-10 minutos hasta que la piel quede dorada. Sirve con el aliño de ajo, perejil, aceite y limón."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
