insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pescados_024', 'Pescadilla al horno', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 272, 28, 10, 12, 2, true, true, '{"pescado"}', '[{"name":"Pescadilla en lomos","amount":350,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en rodajas de unos 3 mm de grosor.","Pelar cebolla y cortar en rodajas finas.","Cortar limón en rodajas finas.","Picar perejil fino y reservar.","Precalentar el horno a 200 °C con calor arriba y abajo.","Disponer las rodajas de patata en una sola capa sobre una bandeja de horno.","Colocar las rodajas de cebolla sobre la patata y regar con aceite de oliva.","Hornear la bandeja durante 15 min hasta que la patata empiece a estar tierna.","Retirar la bandeja del horno y colocar pescadilla en lomos con la piel hacia abajo sobre la cama de verduras.","Disponer las rodajas de limón sobre los lomos y regar con el resto del aceite de oliva.","Hornear 12 min más hasta que la pescadilla esté opaca y se desmenuce con facilidad.","Retirar del horno y servir con el perejil picado esparcido por encima."}', 'Lomos de pescadilla al horno con patata y cebolla', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Precalentar el horno a 190°C. Extender las patatas y cebolla en rodajas finas con aceite en una bandeja y hornear 15-20 min. Añadir la pescadilla, salpimentar, rociar con limón y aceite, y hornear 10-12 min más hasta que el pescado esté en su punto."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalentar la airfryer a 180°C. Cocinar las patatas y cebolla en rodajas finas con un poco de aceite durante 15-18 minutos, removiendo a mitad. Incorporar la pescadilla, salpimentar y rociar con limón, cocinando 7-9 minutos adicionales hasta que el pescado esté tierno y dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_025', 'Calamares encebollados', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 298, 22, 12, 18, 2, true, true, '{"moluscos"}', '[{"name":"Calamares","amount":300,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar cebolla y laminar en juliana fina.","Pelar ajo y picar fino.","Limpiar calamares y cortar en anillas de 1 cm.","Calentar aceite de oliva en sartén a fuego medio.","Añadir la cebolla laminada y sofreír a fuego suave hasta que esté transparente y blanda.","Añadir el ajo picado y sofreír 1 min hasta que desprenda aroma.","Añadir las anillas de calamar y saltear a fuego fuerte hasta que cambien de color.","Verter vino blanco y añadir laurel; remover para integrar.","Tapar la sartén y cocer a fuego suave hasta que los calamares estén tiernos.","Picar perejil fino mientras cuecen los calamares.","Retirar el laurel, espolvorear el perejil picado y servir en plato hondo."}', 'Calamares en anillas guisados con abundante cebolla pochada', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Pocha la cebolla y el ajo en una cazuela apta para horno. Añade los calamares, el vino, el laurel y un poco de agua si es necesario. Tapa y cocina en el horno precalentado a 180°C durante 30-35 minutos, hasta que los calamares estén tiernos."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe con aceite. Incorpora los calamares troceados, el vino blanco y el laurel. Cocina a temperatura Varoma, giro inverso, velocidad cuchara durante 25-30 minutos, hasta que los calamares estén tiernos y la salsa reducida."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla a presión. Añade los calamares, el vino, el laurel y un chorrito de agua. Cierra la olla y cocina durante 8-10 minutos desde que sube la válvula. Despresuriza y, si es necesario, reduce la salsa a fuego vivo sin tapa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_026', 'Tosta de aguacate, huevo poché y salmón ahumado', 'pescados', 'pescado_azul', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 430, 22, 32, 24, 2, true, false, '{"gluten","huevo","pescado"}', '[{"name":"Pan de masa madre","amount":4,"unit":"ud"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Vinagre","amount":15,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Llevar agua a ebullición en un cazo ancho con vinagre a fuego medio.","Tostar pan de masa madre en una tostadora o sartén hasta que estén doradas y crujientes.","Cortar aguacate por la mitad, retirar el hueso y extraer la pulpa con una cuchara.","Machacar la pulpa de aguacate con un tenedor hasta obtener una crema rústica.","Añadir zumo de limón, sal y pimienta negra al aguacate machacado y mezclar.","Cascar huevo uno a uno en una taza pequeña para verterlos con control.","Bajar el fuego a suave cuando el agua rompa a hervir, hasta que quede a punto de ebullición suave.","Remover el agua con una cuchara para crear un remolino y verter un huevo en el centro con cuidado.","Cocer el huevo poché hasta que la clara esté cuajada y la yema blanda, unos 3 min.","Retirar el huevo poché con una espumadera y escurrir sobre papel absorbente.","Repetir el proceso con el segundo huevo en el mismo cazo.","Untar cada rebanada de pan tostado con el aguacate machacado de forma generosa.","Repartir salmón ahumado en láminas sobre el aguacate de cada tosta.","Colocar un huevo poché encima de cada tosta con cuidado para no romper la yema.","Terminar con eneldo fresco picado, un hilo de aceite de oliva virgen extra y pimienta negra al gusto."}', 'Tosta crujiente con aguacate machacado, huevo poché y salmón ahumado, un desayuno o cena rápida y resultona.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Tuesta el pan a 180-200°C por 5-7 minutos. Para el huevo poché, coloca cada huevo en un ramequín con un poco de agua y cocina en la airfryer a 160°C durante 8-10 minutos hasta que la clara esté cuajada y la yema líquida."},{"appliance":"thermomix","time":17,"difficulty":"facil","prepSummary":"Prepara los huevos poché en el recipiente Varoma durante 10-12 minutos a temperatura Varoma, velocidad cuchara. Utiliza el vaso para triturar el aguacate con el limón, sal y pimienta. El pan se tostaría aparte en una tostadora o sartén."},{"appliance":"vaporera","time":17,"difficulty":"facil","prepSummary":"Para los huevos poché, coloca cada huevo en un ramequín ligeramente engrasado y cocina en la vaporera durante 8-12 minutos, hasta que la clara esté firme y la yema a tu gusto. El pan se tostaría aparte en una tostadora o sartén."}]'::jsonb, '{}', true, true, NULL, '{}', NULL),
  ('pescados_027', 'Poke bowl de salmón, aguacate y edamame', 'pescados', 'pescado_azul', 'arroz', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 640, 32, 65, 26, 2, false, false, '{"pescado","soja","sesamo","gluten"}', '[{"name":"Arroz sushi","amount":160,"unit":"g"},{"name":"Salmón fresco para sushi","amount":200,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Edamame desvainado","amount":100,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Salsa de soja","amount":30,"unit":"ml"},{"name":"Vinagre de arroz","amount":15,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Semillas de sésamo","amount":6,"unit":"g"},{"name":"Alga nori","amount":2,"unit":"g"}]'::jsonb, '{"Lavar arroz sushi bajo el grifo hasta que el agua salga clara.","Cocer el arroz en un cazo con el doble de agua fría; llevar a ebullición a fuego fuerte.","Tapar el cazo, bajar a fuego suave y cocer hasta que el arroz absorba toda el agua.","Laminar aguacate en láminas finas.","Rallar zanahoria o cortar en bastones finos.","Cortar pepino en bastones finos.","Cortar salmón fresco para sushi en dados de bocado de unos 2 cm.","Hervir edamame desvainado en agua con sal durante 3 min y escurrir.","Retirar el cazo del fuego y dejar reposar el arroz tapado 5 min.","Extender el arroz en una fuente y aliñar con vinagre de arroz; mezclar con suavidad.","Dejar templar el arroz extendido hasta que pierda el exceso de calor.","Mezclar salsa de soja con aceite de sésamo en un cuenco pequeño.","Repartir el arroz templado en 2 boles.","Disponer el salmón, el aguacate, el edamame, la zanahoria y el pepino en montones sobre el arroz.","Aliñar cada bol con la mezcla de salsa de soja y aceite de sésamo.","Espolvorear semillas de sésamo y cortar alga nori en tiras finas para terminar."}', 'Bowl fresco de arroz templado con salmón, aguacate y edamame en bloques de color, listo en minutos.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina el arroz de sushi en el cestillo o Varoma (aprox. 20-25 min) y cuece el edamame al vapor en el Varoma (aprox. 15 min), pudiendo solaparse. La Thermomix también puede mezclar la salsa para el aliño, facilitando la preparación."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Prepara el arroz de sushi en el recipiente adecuado de la vaporera (aprox. 25-30 min) y cocina el edamame al vapor (aprox. 15 min), pudiendo solaparse. Es un método ideal para una cocción saludable y perfecta de ambos ingredientes."},{"appliance":"olla_express","time":22,"difficulty":"normal","prepSummary":"Cocina el arroz de sushi en la olla a presión (aprox. 5-7 min de cocción + 15 min de reposo natural), lo que acelera el proceso. El edamame también se puede cocer al vapor rápidamente en un cestillo (aprox. 2-3 min)."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_028', 'Tosta de salmón ahumado, queso crema y eneldo', 'pescados', 'pescado_azul', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 8, 'facil', 'all', 410, 18, 26, 25, 2, true, false, '{"gluten","lactosa","pescado"}', '[{"name":"Pan de centeno","amount":4,"unit":"ud"},{"name":"Queso crema","amount":100,"unit":"g"},{"name":"Salmón ahumado","amount":120,"unit":"g"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Zumo de limón","amount":5,"unit":"ml"},{"name":"Alcaparras","amount":15,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Tostar pan de centeno en una tostadora o sartén seca a fuego medio hasta que estén crujientes.","Mezclar queso crema con zumo de limón y pimienta negra hasta obtener una crema homogénea.","Picar eneldo fresco fino.","Untar cada tosta con la crema de queso de forma generosa.","Disponer salmón ahumado en láminas onduladas sobre el queso crema.","Repartir alcaparras por encima del salmón.","Espolvorear el eneldo picado y servir enseguida."}', 'Tosta de pan de centeno con queso crema, salmón ahumado y eneldo fresco, lista en menos de diez minutos.', '[{"appliance":"airfryer","time":7,"difficulty":"facil","prepSummary":"Para tostar el pan, coloca las rebanadas en la airfryer a 180°C durante 4-5 minutos hasta que estén doradas. Luego, unta el queso crema y añade el salmón, eneldo, limón y alcaparras."},{"appliance":"horno","time":9,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C y tuesta el pan de centeno durante 5-7 minutos hasta que esté crujiente. Retira, unta el queso crema y decora con el salmón, eneldo, zumo de limón y alcaparras."}]'::jsonb, '{}', true, true, NULL, '{}', NULL),
  ('pescados_029', 'Bowl de arroz, atún y aguacate al estilo hawaiano', 'pescados', 'pescado_azul', 'arroz', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 560, 30, 68, 18, 2, false, false, '{"pescado","soja","sesamo","gluten"}', '[{"name":"Arroz blanco","amount":160,"unit":"g"},{"name":"Atún fresco para sushi","amount":220,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Mango","amount":100,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Salsa de soja","amount":25,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Semillas de sésamo","amount":6,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"}]'::jsonb, '{"Cocer arroz blanco en abundante agua con sal según el paquete.","Exprimir lima y reservar el zumo.","Cortar atún fresco para sushi en dados regulares de unos 2 cm.","Cortar aguacate en dados del mismo tamaño que el atún.","Cortar mango en dados del mismo tamaño que el aguacate.","Laminar cebolleta en aros finos.","Escurrir el arroz cocido y dejar templar 3 min fuera del fuego.","Mezclar salsa de soja, aceite de sésamo y el zumo de lima en un bol pequeño.","Repartir el arroz templado en 2 boles como base.","Disponer el atún, el aguacate y el mango en montones separados sobre el arroz.","Repartir la cebolleta laminada y semillas de sésamo por encima.","Rociar con la mezcla de salsa de soja, aceite de sésamo y zumo de lima al gusto."}', 'Bowl al estilo hawaiano con arroz templado, atún fresco, aguacate y mango en dados de colores.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina el arroz en el cestillo con agua y sal (20 min/Varoma/vel 4). Mientras, pica la cebolleta y mezcla los ingredientes de la salsa y el atún marinado para montar el bowl."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Prepara el arroz blanco en la vaporera siguiendo las instrucciones para un arroz suelto y aromático (aprox. 25 min). Mientras, corta el resto de ingredientes y prepara la marinada del atún."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Cocina el arroz en la olla express con la proporción adecuada de agua (5-7 min a presión, luego despresuriza). Esto asegura un arroz rápido y perfecto para el bowl mientras preparas los demás ingredientes."},{"appliance":"microondas","time":18,"difficulty":"facil","prepSummary":"Cocina el arroz en un recipiente apto para microondas con la proporción de agua y sal (aprox. 18 min a máxima potencia). El resto de la preparación es montar el bowl con los ingredientes frescos y la salsa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_030', 'Tortilla wrap de atún y maíz', 'pescados', 'pescado_azul', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 470, 23, 40, 22, 2, true, false, '{"gluten","pescado","huevo"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Atún en conserva escurrido","amount":160,"unit":"g"},{"name":"Maíz dulce","amount":80,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Lechuga","amount":40,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"}]'::jsonb, '{"Escurrir atún en conserva escurrido y desmigarlo en un bol.","Cortar tomate en dados pequeños.","Laminar cebolla morada en tiras finas.","Añadir maíz dulce y mayonesa al bol con el atún y mezclar hasta integrar.","Calentar tortilla de trigo en sartén a fuego medio, 30 segundos por cada lado, hasta que estén flexibles.","Repartir lechuga sobre cada tortilla caliente.","Distribuir la mezcla de atún y maíz sobre la lechuga de cada tortilla.","Añadir el tomate en dados y la cebolla morada laminada sobre cada tortilla.","Enrollar cada tortilla apretando bien y cortar por la mitad en diagonal para servir."}', 'Wrap relleno de atún, maíz dulce y mayonesa, enrollado y cortado en rodajas para llevar.', '[{"appliance":"airfryer","time":7,"difficulty":"facil","prepSummary":"Para un toque crujiente, precalienta la airfryer a 180°C y calienta las tortillas 1-2 minutos antes de rellenar, o el wrap ya montado durante 3-5 minutos para dorarlo ligeramente."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Para calentar las tortillas y hacerlas más flexibles, precalienta el horno a 180°C y caliéntalas envueltas en papel de aluminio durante 5-7 minutos. También puedes tostar el wrap montado unos minutos para un exterior crujiente."},{"appliance":"microondas","time":2,"difficulty":"facil","prepSummary":"Para ablandar las tortillas y que sean más fáciles de enrollar, envuélvelas en papel de cocina húmedo y caliéntalas en el microondas durante 30-60 segundos a máxima potencia."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('pescados_031', 'Tosta de tomate rallado, anchoas y aceite', 'pescados', 'pescado_azul', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 8, 'facil', 'verano', 420, 13, 46, 15, 2, false, false, '{"gluten","pescado"}', '[{"name":"Pan de payés","amount":4,"unit":"ud"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Anchoas en aceite","amount":60,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Tostar pan de payés en una tostadora o sartén a fuego medio hasta que estén crujientes.","Rallar tomate maduro por el lado del corte hasta desechar la piel.","Frotar ajo pelado sobre cada tostada caliente.","Repartir la pulpa de tomate rallado sobre las tostadas.","Escurrir anchoas en aceite y colocar 2-3 filetes sobre cada tosta.","Rociar aceite de oliva virgen extra sobre cada tosta y añadir sal."}', 'El clásico pan con tomate rallado coronado con filetes de anchoa y un buen aceite de oliva.', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Tuesta el pan en la airfryer a 180-200°C durante 3-5 minutos, hasta que esté dorado y crujiente. Mientras tanto, ralla el tomate y pica el ajo para el montaje final."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C (preferiblemente con función grill). Tuesta el pan durante 5-8 minutos, vigilando que quede bien dorado y crujiente. Prepara el resto de ingredientes mientras el pan se hornea."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('pescados_032', 'Salmón a la plancha con ensalada de aguacate, pepino y eneldo', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', 'pescados_009', NULL, 20, 'normal', 'all', 510, 34, 8, 38, 2, true, false, '{"pescado"}', '[{"name":"Lomos de salmón","amount":300,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Pepino","amount":150,"unit":"g"},{"name":"Eneldo fresco","amount":10,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Retirar lomos de salmón de la nevera y dejar atemperar 10 min antes de cocinar.","Cortar aguacate en dados pequeños.","Cortar pepino en dados pequeños.","Picar eneldo fresco fino.","Mezclar el aguacate y el pepino con la mitad del eneldo picado, zumo de limón, sal y aceite de oliva virgen extra.","Salpimentar pimienta negra los lomos de salmón por ambas caras.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Añadir aceite de oliva virgen extra sobre la plancha y colocar los lomos de salmón con la piel hacia abajo.","Cocinar los lomos por el lado de la piel 4 min hasta que la piel esté crujiente y dorada.","Dar la vuelta a los lomos y cocinar 2 min más hasta que estén al punto deseado.","Repartir la ensalada de aguacate y pepino en los platos.","Colocar los lomos de salmón sobre la ensalada, añadir el resto del eneldo picado y un hilo de aceite de oliva virgen extra."}', 'Salmón a la plancha con la piel crujiente, acompañado de una ensalada fresca de aguacate, pepino y eneldo.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina el salmón sazonado durante 12-15 minutos, dándole la vuelta a mitad, para un exterior crujiente y un interior jugoso."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Hornea el salmón sazonado sobre papel de horno durante 15-18 minutos hasta que esté tierno y cocido, manteniendo su jugosidad."},{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Cocina el salmón sazonado en el recipiente Varoma durante 15-18 minutos a temperatura Varoma, para un resultado muy jugoso y saludable."},{"appliance":"vaporera","time":18,"difficulty":"facil","prepSummary":"Coloca el salmón sazonado en la cesta de la vaporera y cocina al vapor durante 12-15 minutos para obtener una textura tierna y jugosa, ideal para una comida ligera."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_033', 'Atún a la plancha con ensalada de tomate, aguacate y cebolla morada', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 18, 'normal', 'verano', 440, 34, 10, 26, 2, false, false, '{"pescado","sulfitos"}', '[{"name":"Lomo de atún fresco","amount":300,"unit":"g"},{"name":"Tomate","amount":200,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Vinagre de Jerez","amount":15,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Retirar lomo de atún fresco de la nevera para que atempere.","Cortar tomate en dados medianos.","Cortar aguacate en dados medianos.","Laminar cebolla morada en tiras muy finas.","Mezclar el tomate, el aguacate y la cebolla morada en un bol.","Añadir vinagre de jerez, sal y la mitad de aceite de oliva virgen extra. Remover con suavidad.","Salpimentar el lomo de atún por todas sus caras con sal y pimienta negra.","Calentar plancha a fuego fuerte con un chorrito del aceite de oliva virgen extra hasta que humee.","Sellar el lomo de atún 1 min por cada lado hasta que el exterior esté dorado y el centro quede rosado.","Retirar el atún de la plancha y dejar reposar.","Cortar el lomo de atún en rodajas gruesas.","Repartir la ensalada de tomate, aguacate y cebolla morada en los platos.","Colocar las rodajas de atún sobre la ensalada y terminar con el resto del aceite de oliva virgen extra."}', 'Atún sellado por fuera y rosado por dentro junto a una ensalada vistosa de tomate, aguacate y cebolla morada.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para el atún, precalienta la airfryer a 200°C. Cocina el lomo de atún previamente salpimentado y aceitado durante 8-10 minutos, dándole la vuelta a mitad, para un exterior sellado y un interior jugoso."},{"appliance":"horno","time":20,"difficulty":"normal","prepSummary":"Precalienta el horno a 220°C. Coloca el lomo de atún en una bandeja con un poco de aceite y hornea durante 10-12 minutos, asegurando que quede cocido pero sin resecarse, para una textura tierna."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
