insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pescados_034', 'Gambas salteadas al ajo con ensalada de aguacate y tomate cherry', 'pescados', 'marisco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 390, 25, 9, 24, 2, true, false, '{"marisco"}', '[{"name":"Gambas peladas","amount":300,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Tomates cherry","amount":150,"unit":"g"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar aguacate en dados de unos 2 cm.","Cortar tomates cherry por la mitad.","Mezclar el aguacate y los tomates cherry con zumo de limón, sal y aceite de oliva virgen extra.","Reservar la ensalada a temperatura ambiente.","Picar ajo muy fino.","Picar perejil fino.","Secar gambas peladas con papel absorbente para que no suelten agua al saltear.","Calentar el aceite de oliva virgen extra restante en sartén a fuego fuerte hasta que humee ligeramente.","Sofreír el ajo picado 30 segundos, removiendo sin parar, hasta que esté dorado pero sin quemarse.","Añadir las gambas peladas en una sola capa.","Saltear las gambas a fuego fuerte, sin remover, hasta que estén rosadas por un lado (1 min).","Dar la vuelta a las gambas y saltear 1 min más hasta que estén firmes y rosadas por completo.","Espolvorear el perejil picado sobre las gambas y añadir sal al gusto.","Servir las gambas recién salteadas junto a la ensalada de aguacate y tomates cherry."}', 'Gambas doradas salteadas al ajo servidas junto a una ensalada fresca de aguacate y tomate cherry.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para las gambas, marínalas con ajo, aceite y sal. Cocínalas en la airfryer a 200°C durante 8-10 minutos, agitándolas a mitad de cocción para un dorado uniforme. La clave es no sobrecocerlas para mantenerlas jugosas."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Extiende las gambas marinadas con ajo, aceite y sal en una bandeja de horno. Hornea a 220°C (con función grill si es posible) durante 8-10 minutos hasta que estén rosadas. Un truco es precalentar bien la bandeja para un mejor sellado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_035', 'Salteado de langostinos con ensalada de aguacate, pomelo y menta', 'pescados', 'marisco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'normal', 'all', 380, 23, 15, 21, 2, true, false, '{"marisco"}', '[{"name":"Langostinos pelados","amount":300,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Pomelo","amount":200,"unit":"g"},{"name":"Menta fresca","amount":8,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Zumo de lima","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar pomelo a vivo sobre un bol para recoger el jugo que suelte.","Separar los gajos de pomelo y reservar junto con el jugo.","Picar menta fresca finamente.","Cortar aguacate en dados.","Mezclar en un bol los gajos de pomelo, el aguacate y la menta picada.","Añadir zumo de lima, sal y la mitad de aceite de oliva virgen extra. Remover con cuidado.","Secar langostinos pelados con papel absorbente hasta que estén bien secos.","Calentar el resto del aceite de oliva virgen extra en sartén a fuego fuerte.","Saltear los langostinos 2 min por cada lado hasta que estén dorados y firmes.","Salpimentar los langostinos con sal y pimienta negra al retirar del fuego.","Repartir la ensalada de pomelo y aguacate en los platos.","Colocar los langostinos encima de la ensalada y servir de inmediato."}', 'Langostinos salteados y dorados junto a una ensalada cítrica de aguacate, pomelo y menta.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Cocina los langostinos con un chorrito de aceite a 190°C durante 8-10 minutos, agitándolos a mitad para un dorado uniforme. Mientras, prepara la ensalada fresca de aguacate, pomelo y menta."},{"appliance":"horno","time":20,"difficulty":"normal","prepSummary":"Asa los langostinos en una bandeja con un poco de aceite a 200°C (con función ventilador si es posible) durante 10-12 minutos, hasta que estén rosados y ligeramente dorados. Aprovecha el tiempo para montar la ensalada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_036', 'Lubina entera a la sal con hierbas', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 55, 'normal', 'all', 300, 42, 1, 12, 2, true, false, '{"pescado","huevo"}', '[{"name":"Lubina entera limpia","amount":800,"unit":"g"},{"name":"Sal gruesa","amount":1500,"unit":"g"},{"name":"Clara de huevo","amount":2,"unit":"ud"},{"name":"Romero fresco","amount":10,"unit":"g"},{"name":"Tomillo fresco","amount":10,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 220 °C con calor arriba y abajo.","Cortar limón en rodajas finas.","Rellenar la cavidad de lubina entera limpia con romero fresco, tomillo fresco y las rodajas de limón.","Mezclar sal gruesa con clara de huevo en un bol hasta obtener una textura de arena húmeda.","Extender una capa de la mezcla de sal en la base de una bandeja de horno del tamaño de la lubina.","Colocar la lubina rellena encima de la capa de sal.","Cubrir la lubina por completo con el resto de la mezcla de sal, presionando bien para sellarla sin dejar huecos.","Hornear la bandeja en el centro del horno hasta que la costra esté firme y ligeramente dorada.","Retirar la bandeja del horno y dejar reposar 3 min antes de romper la costra.","Romper la costra de sal golpeando suavemente con el dorso de una cuchara por todo el contorno.","Retirar los trozos de costra con cuidado, evitando que caiga sal sobre la carne.","Retirar la piel de la lubina y separar los lomos limpios de espinas con una espátula.","Servir los lomos en los platos y aliñar con aceite de oliva virgen extra."}', 'Lubina entera horneada bajo una costra de sal y hierbas, que se rompe en la mesa liberando todo el aroma.', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Precalienta el horno a 200°C. Cubre la lubina con la mezcla de sal gruesa y claras, y hornea durante 55 minutos hasta que la costra esté dura y dorada, cocinándose en su propio jugo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_037', 'Rodaballo a la plancha con salsa de marisco', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 430, 38, 6, 26, 2, true, false, '{"pescado","marisco","lactosa","sulfitos"}', '[{"name":"Lomos de rodaballo","amount":350,"unit":"g"},{"name":"Gambas peladas","amount":100,"unit":"g"},{"name":"Chalota","amount":40,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Fumet de pescado","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Picar chalota muy fina.","Salpimentar lomos de rodaballo con sal y pimienta negra por ambas caras.","Calentar aceite de oliva en plancha a fuego fuerte hasta que humee ligeramente.","Colocar los lomos de rodaballo en plancha y cocinar 3 min por cada lado hasta que estén dorados.","Retirar los lomos de rodaballo de plancha y reservar en un plato caliente.","Fundir mantequilla en la misma sartén a fuego medio.","Sofreír la chalota picada a fuego suave hasta que esté transparente, unos 3 min.","Añadir gambas peladas y saltear a fuego fuerte hasta que estén rosadas, 1 min.","Verter vino blanco y dejar reducir a fuego fuerte hasta que se evapore a la mitad, unos 2 min.","Añadir fumet de pescado y nata para cocinar y remover para mezclar.","Cocer a fuego suave hasta que la salsa espese ligeramente, unos 5 min, removiendo de vez en cuando.","Retirar la mitad de la salsa con parte de las gambas y triturar hasta obtener una crema homogénea.","Verter la crema triturada de nuevo en la sartén y mezclar con el resto de la salsa a fuego suave 1 min.","Disponer los lomos de rodaballo reservados en el plato y salsear generosamente con la salsa de marisco."}', 'Rodaballo a la plancha napado con una cremosa salsa de marisco con trocitos de gamba.', '[]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_038', 'Tartar de atún rojo con aguacate y sésamo', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'completo', NULL, NULL, 20, 'normal', 'all', 370, 28, 6, 20, 2, false, false, '{"pescado","soja","sesamo","gluten"}', '[{"name":"Atún rojo fresco de calidad sashimi","amount":250,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Semillas de sésamo","amount":8,"unit":"g"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar atún rojo fresco de calidad sashimi en dados pequeños y uniformes con un cuchillo bien afilado.","Cortar aguacate en dados del mismo tamaño que el atún.","Picar cebolleta muy fina.","Rallar jengibre fresco hasta obtener una pasta fina.","Exprimir lima y reservar el zumo; rallar la piel y reservar la ralladura por separado.","Mezclar en un bol el atún dados, la cebolleta picada, el jengibre rallado, salsa de soja y aceite de sésamo.","Añadir sal y remover con suavidad hasta integrar.","Tapar el bol y dejar marinar en la nevera hasta que el atún absorba los aromas.","Añadir el aguacate en dados sobre el atún marinado y mezclar con suavidad para no aplastarlo.","Colocar un aro de emplatar sobre el plato y rellenar con la mezcla, presionando ligeramente para compactar.","Retirar el aro con cuidado y terminar con semillas de sésamo, el zumo y la ralladura de lima reservados."}', 'Tartar de atún rojo fresco con aguacate en dados y un toque de sésamo tostado.', '[{"appliance":"thermomix","time":15,"difficulty":"normal","prepSummary":"Utiliza la función de picado a pulsos para el atún y el resto de ingredientes, asegurando una textura homogénea sin triturar. Mezcla suavemente en el vaso para integrar los sabores y emulsionar la vinagreta."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_039', 'Ceviche de corvina con leche de tigre', 'pescados', 'pescado_blanco', NULL, ARRAY['cena','segundo']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'verano', 220, 30, 18, 3, 2, false, false, '{"pescado","apio"}', '[{"name":"Corvina fresca","amount":300,"unit":"g"},{"name":"Lima","amount":4,"unit":"ud"},{"name":"Cebolla morada","amount":60,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Ají amarillo o guindilla fresca","amount":5,"unit":"g"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Apio","amount":20,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Maíz tostado","amount":40,"unit":"g"}]'::jsonb, '{"Cortar corvina fresca en dados de unos 2 cm y reservar en la nevera.","Cortar cebolla morada en juliana fina y sumergir en agua fría.","Dejar reposar la cebolla morada en agua fría 5 min para suavizar su sabor.","Exprimir lima y verter el zumo en el vaso de la batidora.","Cortar apio en trozos y añadir al vaso junto al zumo de lima.","Rallar jengibre fresco e incorporar al vaso.","Picar ají amarillo o guindilla fresca e incorporar al vaso.","Añadir sal al vaso y triturar todo hasta obtener una mezcla homogénea.","Colar la leche de tigre por un colador fino y reservar el líquido resultante.","Escurrir la cebolla morada y secarla ligeramente con papel de cocina.","Picar cilantro fresco fino y reservar.","Mezclar la corvina con la cebolla morada escurrida en un bol frío.","Verter la leche de tigre sobre la corvina y remover con cuidado para cubrir todos los dados.","Dejar marinar 4 min sin remover para que el pescado quede firme pero jugoso.","Añadir el cilantro picado y remover con suavidad.","Servir de inmediato en platos fríos con maíz tostado por encima."}', 'Ceviche de corvina marinada en una intensa leche de tigre con lima, cilantro y ají.', '[{"appliance":"thermomix","time":25,"difficulty":"normal","prepSummary":"Utiliza la Thermomix para picar finamente la cebolla, el cilantro, el ají, el jengibre y el apio. Luego, mezcla estos ingredientes con el zumo de lima y la sal para crear la leche de tigre en pocos segundos. Finalmente, incorpora la corvina cortada y deja marinar."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_040', 'Vieiras con puré de guisantes y panceta', 'pescados', 'marisco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 380, 26, 15, 22, 2, true, false, '{"moluscos","lactosa"}', '[{"name":"Vieiras limpias","amount":6,"unit":"ud"},{"name":"Guisantes","amount":250,"unit":"g"},{"name":"Panceta ahumada en lonchas finas","amount":60,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Caldo de verduras","amount":80,"unit":"ml"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Hervir agua con sal en un cazo a fuego fuerte.","Cocer guisantes en el agua hirviendo hasta que estén tiernos.","Escurrir los guisantes y triturarlos con caldo de verduras, mantequilla y menta fresca hasta obtener un puré fino.","Colar el puré por un colador fino hasta que esté sedoso.","Salpimentar el puré con pimienta negra y reservar caliente tapado.","Cortar panceta ahumada en lonchas finas en tiras.","Dorar las tiras de panceta en sartén sin aceite a fuego medio hasta que estén crujientes.","Retirar la panceta y reservar sobre papel absorbente.","Secar vieiras limpias con papel absorbente.","Salpimentar las vieiras por ambas caras con sal y pimienta negra.","Calentar aceite de oliva en la misma sartén a fuego fuerte hasta que humee.","Marcar las vieiras 90 segundos por el primer lado sin moverlas hasta que estén doradas.","Dar la vuelta a las vieiras y marcar 90 segundos por el otro lado hasta que estén jugosas por dentro.","Repartir el puré de guisantes en la base de los platos.","Colocar las vieiras encima del puré y terminar con la panceta crujiente."}', 'Vieiras doradas a la plancha sobre un puré sedoso de guisantes con panceta crujiente.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"La airfryer es ideal para la panceta crujiente y las vieiras doradas. Los guisantes se cocinan aparte (microondas o vaporera) y se trituran para el puré, logrando un plato completo y delicioso."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_041', 'Merluza a la vasca con kokotxas y almejas', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 45, 'elaborada', 'all', 430, 40, 8, 22, 2, false, false, '{"pescado","moluscos","gluten","sulfitos"}', '[{"name":"Merluza en trozos","amount":300,"unit":"g"},{"name":"Kokotxas de merluza","amount":150,"unit":"g"},{"name":"Almejas","amount":250,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Perejil","amount":15,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de pescado","amount":150,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Sumergir almejas en agua fría con sal durante 30 min para que suelten la arena.","Picar ajo fino.","Picar perejil fino y reservar.","Salpimentar merluza en trozos y kokotxas de merluza con sal y reservar.","Escurrir las almejas y reservar.","Calentar aceite de oliva virgen extra en una cazuela a fuego suave hasta que esté caliente.","Sofreír el ajo picado a fuego suave hasta que se dore ligeramente, sin que se queme.","Añadir harina y remover sin parar durante 1 min hasta que quede integrada sin coger color.","Verter vino blanco y remover hasta que el alcohol evapore, unos 2 min a fuego medio.","Añadir caldo de pescado y mover la cazuela en círculos hasta que la salsa ligue, 2 min a fuego suave.","Incorporar la merluza en trozos y cocer a fuego suave durante 4 min, moviendo la cazuela con suavidad.","Añadir las kokotxas de merluza y las almejas escurridas.","Cocer a fuego suave 5 min, moviendo la cazuela, hasta que las almejas se abran y la salsa ligue.","Espolvorear con el perejil picado y servir en la misma cazuela."}', 'Merluza guisada en salsa verde con kokotxas y almejas, un clásico vasco con conchas abiertas en la mesa.', '[{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"Sofríe el ajo y perejil, añade el vino y el caldo. Incorpora la merluza y las kokotxas para una cocción suave y controlada. Al final, añade las almejas para que se abran y emulsiona la salsa para lograr la textura perfecta."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_042', 'Kokotxas de bacalao al pil-pil', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'elaborada', 'all', 400, 24, 1, 32, 2, false, false, '{"pescado"}', '[{"name":"Kokotxas de bacalao","amount":400,"unit":"g"},{"name":"Ajo","amount":30,"unit":"g"},{"name":"Guindilla","amount":3,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":120,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Secar kokotxas de bacalao con papel absorbente hasta que no quede humedad superficial.","Laminar ajo.","Cortar guindilla en aros finos.","Calentar aceite de oliva virgen extra en una cazuela de barro a fuego suave hasta que esté templado.","Sofreír el ajo laminado y los aros de guindilla a fuego suave hasta que el ajo esté dorado.","Retirar el ajo y la guindilla con una espumadera y reservar.","Colocar las kokotxas con la piel hacia arriba en el aceite templado a fuego muy suave.","Cocinar a fuego muy suave 4 min sin que el aceite hierva, moviendo la cazuela en círculos para que las kokotxas suelten gelatina.","Retirar la cazuela del fuego y seguir moviéndola en círculos sin parar.","Añadir el aceite de la cazuela poco a poco sobre las kokotxas mientras se mueve en círculos hasta que la salsa emulsione y forme un pil-pil espeso.","Volver la cazuela al fuego muy suave un instante si la salsa se corta, sin dejar de mover en círculos hasta que vuelva a ligar.","Salpimentar con sal y remover suavemente.","Servir las kokotxas con el pil-pil en cazuelitas individuales y coronar con el ajo y la guindilla reservados."}', 'Kokotxas de bacalao ligadas al pil-pil, con el clásico movimiento de cazuela para emulsionar la salsa.', '[{"appliance":"thermomix","time":30,"difficulty":"normal","prepSummary":"La Thermomix es excelente para el pil-pil. Primero, sofríe el ajo y la guindilla en el aceite. Luego, añade las kokotxas y cocina a baja temperatura (80-90°C) con giro inverso y velocidad cuchara, batiendo suavemente para emulsionar la gelatina con el aceite hasta lograr la textu"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_043', 'Cigalas a la plancha con alioli de azafrán', 'pescados', 'marisco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 340, 22, 3, 25, 2, true, false, '{"marisco","huevo"}', '[{"name":"Cigalas frescas","amount":8,"unit":"ud"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva suave","amount":150,"unit":"ml"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Machacar ajo con sal en un mortero hasta obtener una pasta fina.","Poner huevo, la pasta de ajo y azafrán en hebras en el vaso de la batidora.","Añadir aceite de oliva suave y triturar sin mover el brazo de la batidora.","Verter el resto del aceite de oliva suave en hilo fino hasta que emulsione en un alioli espeso.","Añadir zumo de limón y sal al alioli, mezclar y reservar en la nevera.","Secar cigalas frescas con papel absorbente hasta que estén bien secas por fuera.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Cocinar las cigalas frescas 1-2 min por cada lado hasta que estén rosadas y firmes.","Retirar las cigalas de la plancha y salar de inmediato.","Servir las cigalas calientes junto al alioli de azafrán reservado."}', 'Cigalas a la plancha servidas con un alioli suave de azafrán con hebras doradas.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para las cigalas, precalienta la airfryer a 190-200°C. Píntalas con un poco de aceite y sal, y cocínalas durante 8-10 minutos, dándoles la vuelta a mitad, hasta que estén doradas y rosadas. El alioli se prepara aparte de forma tradicional."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Para las cigalas, precalienta el horno con función grill o a 220°C. Colócalas en una bandeja con un chorrito de aceite y sal, y ásalas durante 8-12 minutos, hasta que estén bien rosadas y ligeramente doradas. El alioli se prepara aparte."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
