insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pescados_044', 'Arroz de bogavante', 'pescados', 'marisco', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 60, 'elaborada', 'all', 520, 34, 58, 15, 4, true, true, '{"marisco","pescado"}', '[{"name":"Bogavante","amount":800,"unit":"g"},{"name":"Arroz bomba","amount":320,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Caldo de pescado y marisco","amount":900,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Cortar bogavante por la mitad longitudinalmente, reservar los jugos y separar las pinzas.","Picar cebolla, pimiento rojo y ajo muy finos.","Calentar aceite de oliva virgen extra en una paellera a fuego fuerte hasta que esté bien caliente.","Dorar los trozos de bogavante 2 min por cada lado hasta que la cáscara tome color rojo intenso.","Retirar el bogavante y reservar junto con los jugos que haya soltado.","Sofreír la cebolla picada, el pimiento rojo picado y el ajo picado en el mismo aceite a fuego medio.","Añadir tomate triturado y pimentón dulce, y remover bien para integrar con el sofrito.","Cocinar el tomate con el pimentón a fuego medio, removiendo de vez en cuando, hasta que pierda el agua.","Añadir arroz bomba y sofreír, removiendo, hasta que los granos estén translúcidos y bien impregnados.","Infusionar azafrán en hebras en un poco de caldo de pescado y marisco caliente durante 2 min.","Verter el resto del caldo y el azafrán infusionado en la paellera y llevar a ebullición a fuego fuerte.","Salpimentar con sal y colocar los trozos de bogavante y sus jugos sobre el arroz.","Cocinar a fuego medio-alto sin remover durante 10 min.","Bajar a fuego suave y cocinar sin remover hasta que el arroz haya absorbido casi todo el caldo.","Retirar del fuego, tapar la paellera con un paño de cocina limpio y dejar reposar.","Servir directamente de la paellera, repartiendo el bogavante entre los comensales."}', 'Arroz meloso cocinado con un bogavante entero partido por la mitad y un caldo intenso de marisco.', '[{"appliance":"horno","time":70,"difficulty":"elaborada","prepSummary":"Prepara el sofrito en una cazuela apta para horno en el fuego. Añade el arroz, el caldo y el bogavante, y termina la cocción en el horno precalentado a 190°C durante 20-25 minutos para un arroz meloso y uniforme."},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Elabora el sofrito en el vaso de la Thermomix. Incorpora el arroz, el caldo y el bogavante troceado, cocinando a temperatura Varoma o 100°C con giro inverso y velocidad cuchara durante 20-22 minutos."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Sofríe las verduras en la olla a presión. Añade el arroz, el caldo caliente y el bogavante troceado, cierra y cocina a fuego medio durante 5-7 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_045', 'Gravlax de salmón casero con eneldo', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 1450, 'normal', 'all', 390, 32, 6, 27, 4, true, true, '{"pescado","mostaza","sulfitos"}', '[{"name":"Lomo de salmón fresco con piel","amount":600,"unit":"g"},{"name":"Sal gruesa","amount":100,"unit":"g"},{"name":"Azúcar","amount":80,"unit":"g"},{"name":"Eneldo fresco","amount":50,"unit":"g"},{"name":"Pimienta negra en grano machacada","amount":5,"unit":"g"},{"name":"Mostaza de Dijon","amount":40,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Vinagre de vino blanco","amount":10,"unit":"ml"},{"name":"Aceite de girasol","amount":30,"unit":"ml"}]'::jsonb, '{"Retirar las espinas del lomo de salmón fresco con piel pasando los dedos a contrapelo y extrayéndolas con unas pinzas.","Picar eneldo fresco fino y dividirlo en dos partes iguales; reservar cada mitad por separado.","Machacar ligeramente pimienta negra en grano machacada con el reverso de un cuchillo hasta obtener trozos gruesos.","Mezclar en un bol sal gruesa, azúcar, la pimienta machacada y la primera mitad del eneldo picado hasta integrar.","Extender la mezcla de curado sobre toda la superficie del lomo de salmón, cubriéndolo por completo por ambos lados.","Envolver el salmón cubierto con film transparente, apretando bien para que la mezcla quede en contacto con la carne.","Colocar el salmón envuelto en una bandeja y disponer encima un peso (p. ej. una tabla con botes) para prensarlo.","Curar el salmón en la nevera durante 720 min (12 h); pasado ese tiempo, dar la vuelta al paquete y desechar el líquido.","Curar el salmón 720 min más en la nevera (otras 12 h), completando así las 24 h mínimas de curado.","Retirar el film y aclarar el salmón bajo un chorro de agua fría para eliminar el exceso de mezcla de curado.","Secar el salmón con papel absorbente, presionando con suavidad por todas las caras hasta que quede bien seco.","Cubrir la superficie del salmón con la segunda mitad del eneldo picado, presionando para que se adhiera a la carne.","Mezclar en un bol mostaza de dijon, miel y vinagre de vino blanco hasta integrar.","Añadir aceite de girasol en hilo fino sobre la mezcla mientras se remueve sin parar hasta que la salsa emulsione.","Cortar el salmón en lonchas muy finas en diagonal, con el cuchillo inclinado, separándolas con cuidado.","Servir las lonchas de salmón en el plato y acompañar con la salsa de mostaza y eneldo aparte o en hilo por encima."}', 'Salmón curado en casa con sal, azúcar y eneldo, cortado en lonchas finas y servido con salsa de mostaza.', '[{"appliance":"thermomix","time":1450,"difficulty":"normal","prepSummary":"La Thermomix es ideal para picar finamente el eneldo y machacar la pimienta en grano para la mezcla de curado. También permite emulsionar la salsa de mostaza y miel de forma rápida y homogénea, facilitando la preparación de los componentes de la receta."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_046', 'Bacalao ajoarriero', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 40, 'normal', 'all', 380, 27, 15, 22, 2, true, true, '{"pescado"}', '[{"name":"Bacalao desalado y desmigado","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Guindilla","amount":2,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"},{"name":"Perejil","amount":8,"unit":"g"}]'::jsonb, '{"Picar cebolla en trozos pequeños.","Cortar pimiento rojo y pimiento verde en trozos pequeños.","Picar ajo fino.","Calentar aceite de oliva virgen extra en una cazuela a fuego medio.","Sofreír la cebolla, el pimiento rojo y el pimiento verde hasta que estén blandos.","Añadir el ajo picado y guindilla y sofreír hasta que el ajo suelte aroma.","Añadir tomate triturado y remover para integrar.","Cocer a fuego suave hasta que la salsa reduzca y pierda el exceso de agua.","Añadir bacalao desalado y desmigado y remover con cuidado para integrarlo sin deshacerlo.","Cocer a fuego suave hasta que el bacalao esté cocinado y se integre en la salsa.","Picar perejil fino.","Espolvorear el perejil picado sobre el guiso y servir bien caliente."}', 'Bacalao desmigado en un sofrito de pimientos, tomate y ajo, un guiso reconfortante y sencillo.', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Prepara un sofrito con las verduras en una cazuela apta para horno. Añade el bacalao desmigado y hornea a 180°C durante 20 minutos, permitiendo que los sabores se concentren y el bacalao se cocine suavemente."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica las verduras y sofríelas con aceite y guindilla. Incorpora el tomate y cocina. Añade el bacalao desmigado y cocina a 90°C en giro inverso, velocidad cuchara, durante 8-10 minutos para integrar sin deshacer el pescado."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Sofríe las verduras en la olla abierta hasta que estén tiernas. Añade el tomate y cocina unos minutos. Incorpora el bacalao desmigado y cocina a fuego suave sin tapar durante 5-7 minutos, permitiendo que los sabores se mezclen sin sobrecocer el pescado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_047', 'Bacalao a la vizcaína', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 60, 'elaborada', 'invierno', 420, 33, 20, 22, 2, true, true, '{"pescado","gluten"}', '[{"name":"Bacalao desalado en lomos","amount":350,"unit":"g"},{"name":"Pimientos choriceros","amount":4,"unit":"ud"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pan frito","amount":20,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Sumergir pimientos choriceros en agua caliente hasta cubrirlos.","Esperar hasta que los pimientos choriceros estén hidratados.","Picar cebolla muy fina.","Picar ajo muy fino.","Retirar la pulpa de los pimientos choriceros hidratados raspando con una cuchara y reservar.","Calentar aceite de oliva virgen extra en una cazuela a fuego medio.","Sofreír la cebolla picada y el ajo picado a fuego suave hasta que estén muy tiernos.","Añadir la pulpa de los pimientos choriceros a la cazuela.","Añadir tomate triturado y remover para integrar.","Cocinar la salsa a fuego suave hasta que se concentre.","Añadir pan frito desmenuzado a la salsa y remover para integrar.","Triturar la salsa hasta obtener una textura fina.","Colar la salsa triturada sobre la misma cazuela.","Añadir sal y remover.","Colocar bacalao desalado en lomos con la piel hacia arriba sobre la salsa caliente.","Cocinar a fuego muy suave moviendo la cazuela en círculos hasta que el bacalao esté hecho.","Servir el bacalao napado con la salsa vizcaína."}', 'Bacalao en salsa vizcaína, con el intenso sabor del pimiento choricero y una salsa oscura y sedosa.', '[{"appliance":"horno","time":75,"difficulty":"elaborada","prepSummary":"Prepara el sofrito y la base de la salsa en una cazuela apta para horno en la encimera. Incorpora el bacalao y hornea a 170°C durante 30-40 minutos, permitiendo que los sabores se integren y el pescado se cocine suavemente en su jugo, logrando una textura melosa."},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Pica y sofríe la cebolla y el ajo en la Thermomix. Añade el tomate, los pimientos choriceros rehidratados y el pan frito, tritura y cocina la salsa. Finalmente, incorpora el bacalao y cocínalo a 90°C en giro inverso durante 15-20 minutos para que quede jugoso y la salsa ligada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_048', 'Gambas al ajillo con jerez y guindilla', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 380, 22, 3, 30, 2, false, false, '{"marisco","sulfitos"}', '[{"name":"Gambas frescas o congeladas","amount":350,"unit":"g"},{"name":"Ajo","amount":25,"unit":"g"},{"name":"Guindilla","amount":6,"unit":"g"},{"name":"Vino de Jerez","amount":40,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":60,"unit":"ml"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Pelar gambas frescas o congeladas dejando la cola si se desea, y secarlas bien con papel de cocina.","Laminar ajo finamente.","Cortar guindilla en aros, retirando las semillas si se quiere menos picante.","Picar perejil fino y reservar.","Calentar aceite de oliva virgen extra en una cazuela de barro a fuego medio.","Añadir el ajo laminado y los aros de guindilla y sofreír hasta que el ajo empiece a dorarse.","Subir el fuego a fuego fuerte y añadir las gambas secas.","Saltear las gambas hasta que empiecen a coger color, aproximadamente 1 min por cada lado.","Verter vino de jerez y remover la cazuela hasta que el alcohol se evapore.","Añadir sal y espolvorear el perejil picado por encima.","Servir burbujeante en la misma cazuela de barro."}', 'Gambas al ajillo con un toque de jerez y guindilla, burbujeantes recién salidas de la cazuela.', '[{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Combina las gambas, ajo laminado, guindilla, jerez, aceite y sal en una cazuela de barro. Hornea 12-15 minutos hasta que las gambas estén rosadas y el aceite burbujee."},{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Trocea el ajo y la guindilla. Sofríelos con el aceite en la Thermomix a 120°C, velocidad cuchara, durante 5 min. Añade las gambas, el jerez y la sal, y cocina 6-8 min a 100°C, giro inverso, velocidad cuchara."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_049', 'Navajas a la plancha con limón', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 240, 24, 3, 12, 2, true, false, '{"moluscos"}', '[{"name":"Navajas frescas","amount":500,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Sumergir navajas frescas en agua fría con sal durante 20 min para que suelten la arena.","Picar ajo muy fino.","Picar perejil muy fino.","Cortar limón en gajos.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Escurrir las navajas y colocarlas en la plancha con la concha hacia abajo.","Cocinar 1-2 min hasta que se abran, retirando cada navaja en cuanto abra para que no se pasen.","Rociar las navajas con aceite de oliva virgen extra y repartir el ajo y el perejil picados por encima.","Servir de inmediato con los gajos de limón al lado."}', 'Navajas a la plancha abiertas al momento, con ajo, perejil y un chorro de limón.', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 200°C. Coloca las navajas limpias en la cesta, rocía con un poco de aceite de oliva y cocina durante 6-8 minutos, o hasta que se abran y estén ligeramente doradas. Sirve con el ajo, perejil y limón."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 220°C con función grill si es posible. Coloca las navajas en una bandeja de horno, rocía con aceite de oliva y hornea durante 8-10 minutos, o hasta que se abran y los bordes estén ligeramente crujientes. Añade el ajo, perejil y limón al servir."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_050', 'Zamburiñas gratinadas', 'pescados', 'marisco', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, 'horno', 30, 'normal', 'all', 372, 27, 19, 21, 2, true, false, '{"moluscos","gluten","lactosa","sulfitos"}', '[{"name":"Carne de zamburiña","amount":240,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Queso rallado","amount":20,"unit":"g"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Picar cebolla y ajo muy finos.","Cortar carne de zamburiña en 2-3 trozos si son grandes.","Calentar aceite de oliva y la mitad de mantequilla en sartén a fuego suave.","Sofreír la cebolla y el ajo picados a fuego suave hasta que estén tiernos.","Picar perejil fino.","Subir el fuego a fuerte y añadir la carne de zamburiña troceada a la sartén.","Saltear hasta que la carne de zamburiña cambie de color por fuera.","Verter vino blanco y remover hasta que se evapore casi por completo.","Retirar la sartén del fuego y salpimentar el relleno al gusto.","Mezclar pan rallado, queso rallado y el perejil picado en un bol.","Fundir el resto de la mantequilla y añadirla a la mezcla de pan rallado; remover hasta integrar.","Precalentar el horno con el grill a temperatura máxima.","Repartir el relleno de zamburiña entre 8 conchas cóncavas limpias dispuestas en una bandeja.","Espolvorear la mezcla de pan rallado y queso sobre cada concha de forma uniforme.","Gratinar en el horno con el grill fuerte hasta que la superficie esté dorada.","Servir las conchas muy calientes recién salidas del horno."}', 'Zamburiñas gratinadas en su concha con cebolla pochada, vino blanco y una costra dorada de pan rallado y queso.', '[{"appliance":"horno","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo, añade las zamburiñas y el vino. Mezcla con el resto de ingredientes y gratina en el horno precalentado a 180-200°C durante 10-15 minutos hasta dorar."},{"appliance":"airfryer","time":20,"difficulty":"normal","prepSummary":"Prepara el sofrito en una sartén. Rellena las conchas o moldes y gratina en la airfryer a 180-190°C durante 8-12 minutos, vigilando que el queso se dore sin quemarse."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_051', 'Tartar de salmón con mango y lima', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 340, 26, 14, 19, 2, false, false, '{"pescado","soja","sesamo"}', '[{"name":"Salmón fresco calidad sashimi","amount":240,"unit":"g"},{"name":"Mango maduro","amount":150,"unit":"g"},{"name":"Lima","amount":2,"unit":"ud"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"},{"name":"Cilantro fresco","amount":8,"unit":"g"},{"name":"Sésamo tostado","amount":5,"unit":"g"}]'::jsonb, '{"Congelar salmón fresco calidad sashimi un mínimo de 48 h antes de preparar el tartar para eliminar el riesgo de anisakis.","Descongelar el salmón en la nevera la noche anterior hasta que esté completamente descongelado.","Cortar el salmón en dados de 0,5 cm uniformes y reservar en la nevera.","Pelar mango maduro y cortar en dados del mismo tamaño que el salmón.","Picar cebolleta muy fina.","Picar cilantro fresco muy fino.","Exprimir lima en un bol.","Añadir salsa de soja y aceite de sésamo al zumo de lima y mezclar hasta integrar.","Añadir el salmón, el mango, la cebolleta y el cilantro al bol del aliño y mezclar con cuidado sin machacar los dados.","Tapar el bol y reposar en la nevera hasta que los sabores se integren.","Emplatar el tartar con un aro de cocina y espolvorear sésamo tostado por encima.","Rallar la piel de la lima sobre el tartar emplatado y servir muy frío."}', 'Tartar fresco de salmón con dados de mango, aliñado con lima, soja y aceite de sésamo.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Utiliza la función de picado para el salmón, mango, cebolleta y cilantro, ajustando la velocidad para obtener la textura deseada. Luego, mezcla suavemente todos los ingredientes con la salsa de soja, aceite de sésamo y zumo de lima para un tartar homogéneo y rápido."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_052', 'Suquet de pescado y marisco', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 397, 35, 28, 12, 4, true, true, '{"pescado","marisco","moluscos","sulfitos"}', '[{"name":"Rape","amount":250,"unit":"g"},{"name":"Merluza en rodajas","amount":200,"unit":"g"},{"name":"Gambas peladas","amount":150,"unit":"g"},{"name":"Mejillones","amount":200,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Cebolla","amount":120,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Caldo de pescado","amount":500,"unit":"ml"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Aceite de oliva","amount":35,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos medianos. Reservar en agua fría.","Picar cebolla y pimiento rojo muy finos.","Picar ajo muy fino.","Calentar aceite de oliva en una cazuela ancha a fuego medio.","Sofreír la cebolla, el ajo y el pimiento rojo a fuego medio hasta que estén tiernos.","Añadir tomate triturado y cocinar a fuego medio hasta que pierda el agua.","Escurrir las patatas y añadirlas a la cazuela. Remover para que se impregnen del sofrito.","Verter vino blanco y dejar reducir a fuego medio.","Añadir caldo de pescado y azafrán en hebras. Remover y llevar a ebullición.","Cocer a fuego medio hasta que las patatas estén casi tiernas.","Cortar rape y merluza en rodajas en trozos regulares mientras cuecen las patatas.","Colocar el rape y la merluza sobre las patatas. Repartir gambas peladas y mejillones alrededor.","Cocer a fuego medio hasta que el pescado esté hecho y los mejillones se hayan abierto.","Retirar los mejillones que no se hayan abierto.","Picar perejil fino y espolvorear sobre la cazuela. Servir directamente en la misma cazuela."}', 'Guiso marinero de pescado y marisco con patatas en un caldo dorado de azafrán.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Prepara el sofrito en una cazuela apta para horno. Añade las patatas, pescado, vino, caldo y azafrán, y hornea a 180°C durante 45 minutos. Incorpora las gambas y mejillones y cocina 5-10 minutos más hasta que estén listos."},{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas en el vaso. Añade las patatas, pescado, vino, caldo y azafrán, y cocina a 100°C, giro inverso, velocidad cuchara, durante 35-40 minutos. Incorpora las gambas y mejillones y cocina 3-5 minutos más."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Prepara el sofrito en la olla sin presión. Añade las patatas, vino, caldo y azafrán, cierra la olla y cocina 10-12 minutos desde que sube la válvula. Libera la presión, incorpora el pescado, gambas y mejillones, y cocina 3-5 minutos más sin presión hasta que estén hechos."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_053', 'Calamares rellenos en su tinta', 'pescados', 'marisco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 90, 'elaborada', 'all', 452, 38, 19, 17, 4, false, true, '{"moluscos","gluten","sulfitos","huevo"}', '[{"name":"Calamares medianos limpios con tinta","amount":800,"unit":"g"},{"name":"Bolsas de tinta de calamar","amount":4,"unit":"ud"},{"name":"Jamón serrano en tacos","amount":50,"unit":"g"},{"name":"Cebolla","amount":250,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Huevo cocido","amount":2,"unit":"ud"},{"name":"Vino blanco","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Perejil","amount":10,"unit":"g"}]'::jsonb, '{"Picar finamente los tentáculos y las aletas de calamares medianos limpios con tinta, reservando los cuerpos enteros.","Picar finamente la mitad de cebolla y ajo.","Picar jamón serrano en tacos en trozos pequeños.","Picar huevo cocido finamente.","Mezclar en un bol los tentáculos y aletas picados, la cebolla picada, el ajo picado, el jamón picado, el huevo cocido picado y pan rallado hasta obtener el relleno.","Rellenar cada cuerpo de calamar con la mezcla sin llenarlo del todo para que no se abra al cocer.","Cerrar la boca de cada calamar con un palillo.","Picar el resto de la cebolla y pimiento verde muy finos.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla restante y el pimiento verde picados hasta que estén muy pochados.","Añadir tomate triturado y sofreír hasta que pierda el agua.","Añadir harina y remover sin parar hasta que se integre con el sofrito.","Verter vino blanco y remover hasta que el alcohol se evapore y la salsa espese ligeramente.","Disolver el contenido de bolsas de tinta de calamar en 50 ml de agua fría y añadir a la cazuela.","Triturar la salsa con la batidora hasta que quede fina y homogénea.","Colocar los calamares rellenos en la cazuela y cubrir con la salsa negra.","Cocer a fuego suave con la cazuela tapada hasta que los calamares estén tiernos, dando la vuelta a mitad de cocción.","Retirar los palillos de los calamares con cuidado.","Picar perejil finamente.","Servir los calamares napados con la salsa negra y espolvorear el perejil picado por encima."}', 'Calamares rellenos de jamón, huevo y sus propios tentáculos, cocinados lentamente en una salsa negra de su tinta.', '[{"appliance":"horno","time":95,"difficulty":"elaborada","prepSummary":"Tras sellar los calamares rellenos en una sartén, estófalos en una cazuela con la salsa de tinta en el horno precalentado a 160°C durante 60-75 minutos, cubierto, para una cocción uniforme y tierna."},{"appliance":"thermomix","time":80,"difficulty":"normal","prepSummary":"Prepara los sofritos para el relleno y la salsa en el vaso. Una vez rellenos, cocina los calamares en la salsa de tinta en el vaso a 100°C, velocidad cuchara inversa, durante 45-60 minutos, asegurando una cocción suave y homogénea."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Realiza los sofritos y la salsa directamente en la olla. Tras rellenar y sellar los calamares, cocínalos en la salsa a presión durante 15-20 minutos desde que sube la válvula, logrando una ternura excepcional en mucho menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
