insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pescados_054', 'Merluza a la plancha con salsa rápida de limón y perejil', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 257, 27, 2, 16, 2, true, true, '{"pescado"}', '[{"name":"Lomos de merluza","amount":320,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Picar ajo muy fino.","Picar perejil muy fino.","Exprimir limón y reservar el zumo.","Salpimentar lomos de merluza por ambos lados.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee.","Colocar los lomos de merluza con la piel hacia abajo y cocinar 3 min hasta que la piel esté dorada.","Mezclar en un bol el resto del aceite de oliva, el zumo de limón, el ajo picado y el perejil picado.","Dar la vuelta a los lomos de merluza y cocinar 2 min más hasta que estén hechos por dentro.","Retirar los lomos de merluza de la plancha y colocar en los platos.","Regar con la salsa de limón y perejil y servir."}', 'Lomos de merluza a la plancha con una salsa rápida de limón, ajo y perejil.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para la merluza, precalienta la airfryer a 190°C. Pincela los lomos con aceite, sazona y cocina durante 12-15 minutos, dándoles la vuelta a mitad para un dorado uniforme y una textura jugosa. La salsa se prepara aparte."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca los lomos de merluza en una bandeja con papel de horno, rocíalos con un poco de aceite y hornea durante 15-20 minutos hasta que estén cocidos y ligeramente dorados. La salsa se puede hacer mientras."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_055', 'Salmón a la plancha con ensalada de pepino y eneldo', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', 'pescados_009', NULL, 20, 'facil', 'all', 445, 34, 7, 30, 2, true, true, '{"pescado","lactosa"}', '[{"name":"Lomos de salmón","amount":320,"unit":"g"},{"name":"Pepino","amount":250,"unit":"g"},{"name":"Yogur natural","amount":80,"unit":"g"},{"name":"Eneldo fresco","amount":8,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar pepino, cortar por la mitad a lo largo y retirar las semillas con una cuchara.","Cortar el pepino pelado en medias lunas finas.","Laminar cebolla morada en juliana muy fina.","Picar eneldo fresco fino.","Exprimir limón y reservar el zumo.","Mezclar yogur natural con el eneldo picado, el zumo de limón y lomos de salmón en un bol hasta obtener un aliño homogéneo.","Añadir el pepino y la cebolla morada al aliño y mezclar bien.","Reservar la ensalada en la nevera hasta el momento de servir.","Salpimentar lomos de salmón por ambos lados.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee.","Colocar los lomos de salmón con la piel hacia abajo y cocinar 4 min hasta que la piel esté crujiente.","Dar la vuelta a los lomos de salmón y cocinar 2 min más hasta que el interior esté jugoso.","Servir los lomos de salmón con la ensalada de pepino y eneldo al lado."}', 'Salmón a la plancha con piel crujiente y una ensalada fresca de pepino y eneldo.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Para el salmón, precalienta la airfryer a 190-200°C. Cocina los lomos durante 12-15 minutos, girándolos a mitad, hasta que estén dorados y jugosos. La ensalada se prepara aparte mientras el salmón se cocina."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con función de aire si es posible. Hornea los lomos de salmón en una bandeja con papel de horno durante 15-18 minutos hasta que estén cocidos y ligeramente dorados. La ensalada se prepara aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_056', 'Filetes de lenguado a la plancha con salsa de mantequilla y limón', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 364, 28, 9, 24, 2, true, false, '{"pescado","lactosa","gluten"}', '[{"name":"Filetes de lenguado","amount":320,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Picar perejil fino y reservar.","Exprimir limón y reservar el zumo.","Salpimentar filetes de lenguado por ambas caras.","Pasar los filetes de lenguado por harina, sacudiendo bien el exceso.","Calentar aceite de oliva en plancha a fuego fuerte.","Añadir la mitad de mantequilla y fundir hasta que deje de burbujear.","Colocar los filetes de lenguado en la plancha y dorar 1 min por cada lado, hasta que estén dorados.","Retirar los filetes de lenguado y reservar en los platos.","Bajar a fuego suave y añadir el resto de la mantequilla a la misma plancha hasta que tome un tono avellana.","Añadir el zumo de limón y remover para ligar la salsa con los jugos de la plancha.","Verter la salsa sobre los filetes de lenguado y espolvorear el perejil picado."}', 'Filetes finos de lenguado a la plancha con una salsa de mantequilla dorada y limón.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Rocía los filetes enharinados con un poco de aceite y cocina durante 10-12 minutos, volteando a mitad, hasta que estén dorados y crujientes. La salsa se prepara aparte."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Hornea los filetes enharinados y ligeramente aceitados a 180-200°C durante 12-15 minutos, hasta que estén cocidos y ligeramente dorados. La salsa de mantequilla y limón se prepara aparte y se vierte al servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_057', 'Emperador a la plancha con salsa rápida de tomate y albahaca', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 330, 33, 5, 19, 2, true, true, '{"pescado"}', '[{"name":"Rodajas de emperador","amount":320,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Picar ajo muy fino.","Cortar albahaca fresca en trozos pequeños con los dedos o con cuchillo.","Calentar aceite de oliva en un cazo a fuego medio.","Sofreír el ajo picado hasta que empiece a desprender aroma, sin que se dore.","Añadir tomate triturado y cocer a fuego medio hasta que reduzca y espese ligeramente.","Salpimentar la salsa y retirar del fuego.","Añadir la mitad de la albahaca troceada a la salsa y reservar.","Salpimentar rodajas de emperador por ambas caras.","Calentar el resto del aceite de oliva en plancha a fuego fuerte.","Marcar las rodajas de emperador 3 min por el primer lado sin moverlas.","Dar la vuelta a las rodajas de emperador y marcar 3 min más hasta que estén hechas pero jugosas.","Exprimir limón sobre el emperador recién hecho.","Servir el emperador napado con la salsa de tomate y con el resto de la albahaca troceada por encima."}', 'Emperador a la plancha con una salsa rápida de tomate y albahaca fresca.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Sazona el emperador y cocínalo en la airfryer precalentada a 200°C durante 10-12 minutos, dándole la vuelta a mitad para un dorado uniforme. Mientras, prepara la salsa mezclando el tomate, ajo picado, albahaca y aceite de oliva, calentándola ligeramente si lo deseas."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con función grill. Sazona el emperador, rocía con aceite y hornea 12-15 minutos, usando el grill al final para dorar. Prepara la salsa rápida de tomate y albahaca mientras el pescado se hornea."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
